import React, { useState, useEffect, useMemo } from 'react';
import { 
  UserProfile, 
  HealthRecord, 
  ChatMessage, 
  Interaction, 
  MedicalProblem, 
  Medication, 
  Surgery, 
  Allergy, 
  TreatmentNote, 
  FamilyHistory 
} from './types';
import { ICONS, APP_NAME, STORAGE_KEY } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | 'family' | null;

const UNIVERSAL_SCHEMES = [
  { id: 'pmjay', name: 'Ayushman Bharat (PM-JAY)', benefits: 'Cashless cover of up to ₹5 lakh per family per year for secondary and tertiary care hospitalization.', eligibility: 'Identified through SECC data or RSBY cards.' },
  { id: 'cghs', name: 'Central Govt Health Scheme', benefits: 'Comprehensive medical care facilities for Central Government employees, pensioners, and their dependents.', eligibility: 'Central government employees and pensioners.' },
  { id: 'state-ma', name: 'State Specific (MA / Aarogyasri)', benefits: 'Varies by state (e.g. up to ₹2.5-5 Lakhs cover for specific surgical procedures).', eligibility: 'Low-income households as defined by state ration cards.' }
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [loginId, setLoginId] = useState('');
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');

  // Registration form state
  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', isPremium: false
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    const newHealthId = `HS-${Math.floor(1000 + Math.random() * 9000)}-${Math.floor(1000 + Math.random() * 9000)}`;
    const newRecord: HealthRecord = {
      profile: { ...regForm, healthId: newHealthId },
      problems: [], medications: [], surgeries: [], allergies: [], notes: [], familyHistory: [], interactions: []
    };
    await dbService.saveRecord(newRecord);
    setCurrentUser(newRecord);
    setIsAuth(true);
    localStorage.setItem(SESSION_KEY, newHealthId);
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    const record = await dbService.getRecord(loginId);
    if (record) {
      setCurrentUser(record);
      setIsAuth(true);
      localStorage.setItem(SESSION_KEY, loginId.toUpperCase());
    } else {
      setAuthError('Invalid Health ID. Use HS-XXXX-XXXX format.');
    }
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    localStorage.removeItem(SESSION_KEY);
  };

  const handleAskAi = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);

    try {
      const response = await analyzeHealthRecord(currentUser, userQuery);
      const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
      setChatHistory(prev => [...prev, aiMsg]);

      // Update local storage interaction history
      const updatedUser = { ...currentUser, interactions: [...(currentUser.interactions || []), { id: Date.now().toString(), query: userQuery, response, timestamp: Date.now() }] };
      setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAiLoading(false);
    }
  };

  const addProblem = async (problem: MedicalProblem) => {
    if (!currentUser) return;
    const updated = { ...currentUser, problems: [...currentUser.problems, problem] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  const filteredProblems = useMemo(() => {
    if (!currentUser) return [];
    return currentUser.problems.filter(p => 
      recordFilter === 'present' ? p.status === 'present' : (p.status === 'past' || p.status === 'recovered')
    );
  }, [currentUser, recordFilter]);

  if (isLoading) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-900 text-white">
      <div className="text-center">
        <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
        <p className="font-bold tracking-widest text-indigo-300">DECRYPTING VAULT...</p>
      </div>
    </div>
  );

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-4 bg-slate-900">
        <div className="w-full max-w-md animate-pop-in">
          <div className="bg-white/10 backdrop-blur-xl border border-white/10 rounded-[2.5rem] p-8 auth-card text-white">
            <div className="text-center mb-8">
              <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-3xl mx-auto mb-4 shadow-xl shadow-indigo-500/20">
                {ICONS.LOCK}
              </div>
              <h1 className="text-2xl font-bold">{APP_NAME}</h1>
              <p className="text-slate-400 text-sm mt-1">Universal Medical Vault Access</p>
            </div>

            <div className="flex bg-slate-800/50 p-1 rounded-2xl mb-8">
              <button 
                onClick={() => setAuthMode('login')}
                className={`flex-1 py-2 rounded-xl text-sm font-bold transition-all ${authMode === 'login' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}
              >
                Login
              </button>
              <button 
                onClick={() => setAuthMode('register')}
                className={`flex-1 py-2 rounded-xl text-sm font-bold transition-all ${authMode === 'register' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}
              >
                Register
              </button>
            </div>

            {authMode === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-4">
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2">Vault Health ID</label>
                  <input 
                    type="text" 
                    placeholder="HS-XXXX-XXXX"
                    className="w-full bg-slate-800 border border-white/5 rounded-xl px-4 py-3 focus:ring-2 focus:ring-indigo-500 outline-none transition-all placeholder:text-slate-600"
                    value={loginId}
                    onChange={(e) => setLoginId(e.target.value.toUpperCase())}
                  />
                  {authError && <p className="text-red-400 text-xs mt-2 font-medium">{authError}</p>}
                </div>
                <button type="submit" className="w-full bg-indigo-600 hover:bg-indigo-500 py-4 rounded-xl font-bold transition-all shadow-lg shadow-indigo-500/20">
                  Open Vault
                </button>
              </form>
            ) : (
              <form onSubmit={handleRegister} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">Full Name</label>
                    <input required className="w-full bg-slate-800 border border-white/5 rounded-xl px-3 py-2 text-sm" placeholder="John Doe" onChange={e => setRegForm({...regForm, name: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">Age</label>
                    <input required type="number" className="w-full bg-slate-800 border border-white/5 rounded-xl px-3 py-2 text-sm" placeholder="25" onChange={e => setRegForm({...regForm, age: parseInt(e.target.value)})} />
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">Aadhaar (Last 4 digits preferred)</label>
                  <input required className="w-full bg-slate-800 border border-white/5 rounded-xl px-3 py-2 text-sm" placeholder="0000 0000 0000" onChange={e => setRegForm({...regForm, aadhaar: e.target.value})} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">Gender</label>
                    <select className="w-full bg-slate-800 border border-white/5 rounded-xl px-3 py-2 text-sm" onChange={e => setRegForm({...regForm, gender: e.target.value})}>
                      <option>Male</option>
                      <option>Female</option>
                      <option>Other</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">Blood Group</label>
                    <input className="w-full bg-slate-800 border border-white/5 rounded-xl px-3 py-2 text-sm" placeholder="O+" onChange={e => setRegForm({...regForm, bloodGroup: e.target.value})} />
                  </div>
                </div>
                <button type="submit" className="w-full bg-emerald-600 hover:bg-emerald-500 py-4 rounded-xl font-bold transition-all shadow-lg shadow-emerald-500/20">
                  Generate Secure Health ID
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      userName={currentUser?.profile.name || ''} 
      isPremium={currentUser?.profile.isPremium}
      onLogout={handleLogout}
    >
      <div className="max-w-7xl mx-auto space-y-8 animate-pop-in">

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-8">
              {/* Premium Health ID Card */}
              <div className="relative group">
                <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-[2.5rem] blur opacity-25 group-hover:opacity-40 transition duration-1000"></div>
                <div className="relative bg-indigo-950 rounded-[2.5rem] p-8 text-white overflow-hidden shadow-2xl">
                  <div className="absolute top-0 right-0 p-12 opacity-10 transform scale-150 rotate-12">
                    <i className="fas fa-microchip text-9xl"></i>
                  </div>
                  <div className="flex justify-between items-start mb-12">
                    <div>
                      <p className="text-indigo-300 text-[10px] font-black uppercase tracking-widest mb-1">Vault Carrier</p>
                      <h3 className="text-2xl font-bold tracking-tight">{currentUser?.profile.name}</h3>
                    </div>
                    <div className="text-right">
                      <p className="text-indigo-300 text-[10px] font-black uppercase tracking-widest mb-1">ID Issued By</p>
                      <p className="font-bold">{APP_NAME}</p>
                    </div>
                  </div>
                  <div className="flex items-end justify-between">
                    <div>
                      <p className="text-indigo-300 text-[10px] font-black uppercase tracking-widest mb-1">Secure Health ID</p>
                      <p className="text-2xl font-mono font-bold tracking-[0.2em]">{currentUser?.profile.healthId}</p>
                    </div>
                    <div className="flex space-x-4 text-xs font-bold">
                      <div className="bg-white/10 px-3 py-1.5 rounded-lg">Blood: {currentUser?.profile.bloodGroup}</div>
                      <div className="bg-white/10 px-3 py-1.5 rounded-lg">Age: {currentUser?.profile.age}</div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <RecordCard title="Active Treatments" icon={ICONS.MEDS}>
                  <div className="space-y-4">
                    {currentUser?.medications.filter(m => m.status === 'active').map(med => (
                      <div key={med.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                        <div className="flex items-center space-x-3">
                          <div className="text-indigo-600 text-xl">{ICONS.MEDS}</div>
                          <div>
                            <p className="font-bold text-slate-800">{med.name}</p>
                            <p className="text-xs text-slate-500">{med.dosage} • {med.frequency}</p>
                          </div>
                        </div>
                        <span className="text-[10px] font-black bg-emerald-100 text-emerald-700 px-2 py-1 rounded-md uppercase">Active</span>
                      </div>
                    ))}
                    {currentUser?.medications.filter(m => m.status === 'active').length === 0 && (
                      <p className="text-slate-400 text-sm text-center py-4 italic">No active medications reported.</p>
                    )}
                  </div>
                </RecordCard>

                <RecordCard title="Critical Allergies" icon={ICONS.ALLERGY}>
                  <div className="flex flex-wrap gap-2">
                    {currentUser?.allergies.map(allergy => (
                      <span key={allergy.id} className={`px-4 py-2 rounded-xl text-xs font-bold border ${allergy.severity === 'high' ? 'bg-red-50 text-red-600 border-red-100' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>
                        {allergy.substance} ({allergy.severity.toUpperCase()})
                      </span>
                    ))}
                    {currentUser?.allergies.length === 0 && (
                      <p className="text-slate-400 text-sm italic w-full text-center py-4">No allergies recorded.</p>
                    )}
                  </div>
                </RecordCard>
              </div>
            </div>

            <div className="space-y-8">
              <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6">Security Overview</h3>
                <div className="space-y-6">
                  <div className="flex items-center space-x-4">
                    <div className="w-10 h-10 rounded-full bg-emerald-100 flex items-center justify-center text-emerald-600">{ICONS.CHECK}</div>
                    <div>
                      <p className="text-sm font-bold text-slate-800">Biometric Sync</p>
                      <p className="text-xs text-slate-500">Last verified 12m ago</p>
                    </div>
                  </div>
                  <div className="flex items-center space-x-4">
                    <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600">{ICONS.SHIELD_CHECK}</div>
                    <div>
                      <p className="text-sm font-bold text-slate-800">Quantum Encrypted</p>
                      <p className="text-xs text-slate-500">AES-256-GCM Protocol</p>
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-indigo-600 rounded-[2.5rem] p-8 text-white shadow-xl shadow-indigo-600/20">
                <h4 className="font-bold mb-2">Emergency Access</h4>
                <p className="text-indigo-100 text-xs mb-4">In case of emergency, provide your Health ID to any authorized medical professional for instant record retrieval.</p>
                <div className="bg-white/10 p-4 rounded-2xl flex items-center space-x-3">
                  <div className="text-xl">{ICONS.EMERGENCY}</div>
                  <div>
                    <p className="text-[10px] font-black uppercase opacity-60">Primary Contact</p>
                    <p className="font-bold">+91 98XXX XXXXX</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'records' && (
          <div className="space-y-8">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h3 className="text-2xl font-black text-slate-800">Medical Vault</h3>
                <p className="text-slate-500 text-sm">Organized history of all medical conditions.</p>
              </div>
              <div className="flex bg-slate-200/50 p-1.5 rounded-2xl w-fit">
                <button 
                  onClick={() => setRecordFilter('present')}
                  className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${recordFilter === 'present' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  Active Conditions
                </button>
                <button 
                  onClick={() => setRecordFilter('past')}
                  className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${recordFilter === 'past' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  Medical History
                </button>
              </div>
            </div>

            <RecordCard 
              title={recordFilter === 'present' ? "Current Medical Challenges" : "Resolved Conditions & History"} 
              icon={ICONS.MEDICAL}
              onAdd={() => setShowAddModal('problem')}
            >
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {filteredProblems.map(p => (
                  <div key={p.id} className={`group relative p-6 rounded-3xl border transition-all hover:scale-[1.02] ${recordFilter === 'present' ? 'bg-white border-slate-100 shadow-sm hover:shadow-xl' : 'bg-slate-50/50 border-slate-200 grayscale-[0.5] opacity-80'}`}>
                    <div className="flex justify-between items-start mb-4">
                      <div>
                        <span className={`text-[9px] font-black uppercase px-2 py-1 rounded-md mb-2 inline-block ${p.severity === 'severe' ? 'bg-red-100 text-red-700' : p.severity === 'moderate' ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700'}`}>
                          {p.severity} {p.isChronic ? '• Chronic' : ''}
                        </span>
                        <h4 className="text-lg font-bold text-slate-800">{p.condition}</h4>
                      </div>
                      <div className="text-slate-300 group-hover:text-indigo-500 transition-colors">
                        {ICONS.HISTORY}
                      </div>
                    </div>
                    <div className="space-y-3">
                      <div className="flex items-center text-xs text-slate-500">
                        <span className="w-16 font-bold uppercase tracking-tighter">Onset:</span>
                        <span>{new Date(p.onsetDate).toLocaleDateString()}</span>
                      </div>
                      {p.treatment && (
                        <div className="flex items-start text-xs text-slate-500">
                          <span className="w-16 font-bold uppercase tracking-tighter">Plan:</span>
                          <span className="flex-1 italic">{p.treatment}</span>
                        </div>
                      )}
                    </div>
                    {recordFilter === 'present' && p.severity === 'severe' && (
                      <div className="absolute top-0 right-0 p-4">
                        <span className="flex h-2 w-2">
                          <span className="animate-ping absolute inline-flex h-2 w-2 rounded-full bg-red-400 opacity-75"></span>
                          <span className="relative inline-flex rounded-full h-2 w-2 bg-red-500"></span>
                        </span>
                      </div>
                    )}
                  </div>
                ))}
                {filteredProblems.length === 0 && (
                  <div className="col-span-full py-20 text-center">
                    <div className="text-4xl text-slate-200 mb-4">{ICONS.CHECK}</div>
                    <p className="text-slate-400 font-medium">No records found for this category.</p>
                  </div>
                )}
              </div>
            </RecordCard>
          </div>
        )}

        {activeTab === 'schemes' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {UNIVERSAL_SCHEMES.map(scheme => (
                <div key={scheme.id} className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm hover:shadow-xl transition-all border-t-4 border-t-indigo-500">
                  <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 text-xl mb-4">
                    {ICONS.SCHEME}
                  </div>
                  <h4 className="font-bold text-slate-800 mb-2">{scheme.name}</h4>
                  <p className="text-xs text-slate-600 mb-4 line-clamp-3">{scheme.benefits}</p>
                  <div className="pt-4 border-t border-slate-50">
                    <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Eligibility</p>
                    <p className="text-xs font-medium text-slate-700">{scheme.eligibility}</p>
                  </div>
                </div>
              ))}
            </div>
            <div className="bg-indigo-900 rounded-[2.5rem] p-8 text-white flex items-center justify-between">
              <div>
                <h3 className="text-xl font-bold mb-1">Personalized Scheme Analysis</h3>
                <p className="text-indigo-200 text-sm">Let Shield AI analyze your medical records to find schemes you qualify for.</p>
              </div>
              <button 
                onClick={() => setActiveTab('shield')}
                className="bg-white text-indigo-900 px-6 py-3 rounded-2xl font-bold text-sm shadow-lg hover:scale-105 transition-all"
              >
                Start AI Analysis
              </button>
            </div>
          </div>
        )}

        {activeTab === 'shield' && (
          <div className="max-w-4xl mx-auto flex flex-col h-[calc(100vh-12rem)]">
            <div className="flex-grow overflow-y-auto space-y-4 p-4 custom-scrollbar">
              {chatHistory.length === 0 && (
                <div className="text-center py-20">
                  <div className="w-20 h-20 bg-indigo-100 rounded-[2rem] flex items-center justify-center text-indigo-600 text-4xl mx-auto mb-6">
                    {ICONS.AI}
                  </div>
                  <h3 className="text-xl font-bold text-slate-800">I am Shield AI</h3>
                  <p className="text-slate-500 max-w-sm mx-auto mt-2">I can analyze your medications, check eligibility for Indian Govt schemes, or explain your medical history.</p>
                </div>
              )}
              {chatHistory.map((chat, i) => (
                <div key={i} className={`flex ${chat.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] p-4 rounded-3xl ${chat.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-white border border-slate-100 text-slate-800 shadow-sm rounded-tl-none'}`}>
                    <p className="text-sm whitespace-pre-wrap">{chat.content}</p>
                    <p className={`text-[8px] mt-2 font-bold opacity-50 uppercase tracking-widest ${chat.role === 'user' ? 'text-white' : 'text-slate-400'}`}>
                      {new Date(chat.timestamp).toLocaleTimeString()}
                    </p>
                  </div>
                </div>
              ))}
              {isAiLoading && (
                <div className="flex justify-start animate-pulse">
                  <div className="bg-slate-100 p-4 rounded-3xl rounded-tl-none w-24 h-12 flex items-center space-x-1">
                    <div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce"></div>
                    <div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-75"></div>
                    <div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-150"></div>
                  </div>
                </div>
              )}
            </div>

            <div className="mt-6 p-4 bg-white border border-slate-100 rounded-[2rem] flex items-center space-x-3 shadow-lg focus-within:ring-2 focus-within:ring-indigo-500/20 transition-all">
              <input 
                type="text" 
                className="flex-grow outline-none text-sm px-2 text-slate-700" 
                placeholder="Ask about your records, health schemes, or medications..."
                value={userQuery}
                onChange={(e) => setUserQuery(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAskAi()}
              />
              <button 
                onClick={handleAskAi}
                disabled={isAiLoading || !userQuery.trim()}
                className="w-12 h-12 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl flex items-center justify-center transition-all disabled:opacity-50 disabled:grayscale"
              >
                <i className="fas fa-paper-plane"></i>
              </button>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
