  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');

  // Registration form state
  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', isPremium: false
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const newHealthId = `HS-${Math.floor(1000 + Math.random() * 9000)}-${Math.floor(1000 + Math.random() * 9000)}`;
    const newRecord: HealthRecord = {
      profile: { ...regForm, healthId: newHealthId },
      problems: [], medications: [], surgeries: [], allergies: [], notes: [], familyHistory: [], interactions: []
    };
    await dbService.saveRecord(newRecord);

    setTimeout(() => {
      setCurrentUser(newRecord);
      setIsAuth(true);
      setIsSubmitting(false);
      localStorage.setItem(SESSION_KEY, newHealthId);
    }, 1500);
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    setIsSubmitting(true);

    if (loginMethod === 'phone' && !isVerifyingOtp) {
      const record = await dbService.getRecordByPhone(phoneInput);
      if (record) {
        setTimeout(() => {
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
        }, 1000);
      } else {
        setAuthError('No record found with this phone number.');
        setIsSubmitting(false);
      }
      return;
    }

    let record: HealthRecord | null = null;
    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
    } else {
      if (otpInput === '123456') {
        record = await dbService.getRecordByPhone(phoneInput);
      } else {
        setAuthError('Invalid OTP code. Try 123456 for demo.');
        setIsSubmitting(false);
        return;
      }
    }

    if (record) {
      setTimeout(() => {
        setCurrentUser(record);
        setIsAuth(true);
        setIsSubmitting(false);
        localStorage.setItem(SESSION_KEY, record!.profile.healthId);
      }, 1200);
    } else {
      setAuthError('Invalid credentials. Access Denied.');
      setIsSubmitting(false);
    }
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    localStorage.removeItem(SESSION_KEY);
  };

  const handleAskAi = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);

    try {
      const response = await analyzeHealthRecord(currentUser, userQuery);
      const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
      setChatHistory(prev => [...prev, aiMsg]);

      const updatedUser = { ...currentUser, interactions: [...(currentUser.interactions || []), { id: Date.now().toString(), query: userQuery, response, timestamp: Date.now() }] };
      setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAiLoading(false);
    }
  };

  const addProblem = async (problem: MedicalProblem) => {
    if (!currentUser) return;
    const updated = { ...currentUser, problems: [...currentUser.problems, problem] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  const filteredProblems = useMemo(() => {
    if (!currentUser) return [];
    return currentUser.problems.filter(p => 
      recordFilter === 'present' ? p.status === 'present' : (p.status === 'past' || p.status === 'recovered')
    );
  }, [currentUser, recordFilter]);

  if (isLoading) return (
    <div className="min-h-screen flex items-center justify-center bg-[#0a0f1d] text-white">
      <div className="text-center">
        <div className="w-20 h-20 border-t-4 border-indigo-500 rounded-full animate-spin mx-auto mb-6"></div>
        <p className="font-black tracking-[0.3em] text-indigo-400 text-sm">ENCRYPTION ENGINE INITIALIZING</p>
      </div>
    </div>
  );

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-[#0a0f1d] overflow-hidden relative">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-600/10 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-emerald-600/10 blur-[120px] rounded-full"></div>

        <div className="w-full max-w-lg animate-pop-in relative z-10">
          <div className="bg-white/[0.03] backdrop-blur-3xl border border-white/10 rounded-[3rem] p-10 auth-card shadow-2xl">
            <div className="text-center mb-10">
              <div className="relative inline-block mb-6">
                <div className="absolute inset-0 bg-indigo-500 blur-2xl opacity-20 animate-pulse"></div>
                <div className="w-20 h-20 bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-3xl flex items-center justify-center text-4xl shadow-2xl relative border border-white/20">
                  {isSubmitting ? <i className="fas fa-circle-notch animate-spin text-white"></i> : ICONS.LOCK}
                </div>
              </div>
              <h1 className="text-3xl font-black text-white tracking-tight">{APP_NAME}</h1>
              <p className="text-indigo-300/60 text-xs font-bold uppercase tracking-widest mt-2">Personal Health Vault • Biometric Sync</p>
            </div>

            <div className="flex bg-white/5 p-1.5 rounded-[1.5rem] mb-10 border border-white/5">
              <button 
                onClick={() => { setAuthMode('login'); setAuthError(''); setIsVerifyingOtp(false); }}
                className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'login' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20' : 'text-slate-400 hover:text-white'}`}
              >
                Login
              </button>
              <button 
                onClick={() => { setAuthMode('register'); setAuthError(''); }}
                className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'register' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20' : 'text-slate-400 hover:text-white'}`}
              >
                Register
              </button>
            </div>

            {authMode === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-6">
                {!isVerifyingOtp && (
                  <div className="flex bg-white/5 p-1 rounded-xl mb-4 border border-white/5">
                    <button 
                      type="button"
                      onClick={() => {setLoginMethod('healthid'); setAuthError('');}}
                      className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'healthid' ? 'bg-white/10 text-white' : 'text-slate-500'}`}
                    >
                      Health ID
                    </button>
                    <button 
                      type="button"
                      onClick={() => {setLoginMethod('phone'); setAuthError('');}}
                      className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'phone' ? 'bg-white/10 text-white' : 'text-slate-500'}`}
                    >
                      Phone Number
                    </button>
                  </div>
                )}

                {loginMethod === 'healthid' ? (
                  <div className="animate-slide-in">
                    <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-indigo-400/80 mb-3">Vault Health ID</label>
                    <div className="relative">
                      <div className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-500/50">{ICONS.HEALTH_ID}</div>
                      <input 
                        type="text" 
                        placeholder="HS-XXXX-XXXX"
                        disabled={isSubmitting}
                        className="w-full bg-white/5 border border-white/10 rounded-2xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all placeholder:text-slate-600"
                        value={loginId}
                        onChange={(e) => setLoginId(e.target.value.toUpperCase())}
                      />
                    </div>
                  </div>
                ) : (
                  <div className="animate-slide-in">
                    {!isVerifyingOtp ? (
                      <div>
                        <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-indigo-400/80 mb-3">Linked Phone Number</label>
                        <div className="relative">
                          <div className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-500/50">{ICONS.EMERGENCY}</div>
                          <input 
                            type="tel" 
                            placeholder="+91 00000 00000"
                            disabled={isSubmitting}
                            className="w-full bg-white/5 border border-white/10 rounded-2xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all placeholder:text-slate-600"
                            value={phoneInput}
                            onChange={(e) => setPhoneInput(e.target.value)}
                          />
                        </div>
                      </div>
                    ) : (
                      <div className="animate-pop-in">
                        <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-emerald-400 mb-3 text-center">Enter 6-Digit Secure OTP</label>
                        <div className="flex justify-center space-x-2">
                           <input 
                            type="text" 
                            maxLength={6}
                            placeholder="······"
                            autoFocus
                            className="w-full bg-white/5 border border-white/10 rounded-2xl px-4 py-4 text-center text-2xl font-black tracking-[1em] text-white focus:ring-2 focus:ring-emerald-500 outline-none transition-all placeholder:text-slate-800"
                            value={otpInput}
                            onChange={(e) => setOtpInput(e.target.value)}
                          />
                        </div>
                        <p className="text-[10px] text-slate-500 mt-4 text-center uppercase font-bold">Resend OTP in 59s</p>
                      </div>
                    )}
                  </div>
                )}

                {authError && <p className="text-red-400 text-xs mt-2 font-bold text-center bg-red-400/10 py-2 rounded-lg border border-red-400/20">{authError}</p>}

                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className={`w-full py-5 rounded-[1.5rem] font-black uppercase tracking-widest transition-all flex items-center justify-center space-x-3 group ${isVerifyingOtp ? 'bg-emerald-600 hover:bg-emerald-500 shadow-emerald-500/20' : 'bg-indigo-600 hover:bg-indigo-500 shadow-indigo-500/20'} shadow-2xl disabled:opacity-50`}
                >
                  <span className="text-white">{isSubmitting ? 'Validating Signature...' : isVerifyingOtp ? 'Authenticate OTP' : loginMethod === 'phone' ? 'Send Secure OTP' : 'Open Medical Vault'}</span>
                  {!isSubmitting && <i className={`fas ${isVerifyingOtp ? 'fa-fingerprint' : 'fa-arrow-right'} text-sm group-hover:translate-x-1 transition-transform`}></i>}
                </button>
              </form>
            ) : (
              <form onSubmit={handleRegister} className="space-y-4 animate-slide-in">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Full Name</label>
                    <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="John Doe" onChange={e => setRegForm({...regForm, name: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Age</label>
                    <input required type="number" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="25" onChange={e => setRegForm({...regForm, age: parseInt(e.target.value)})} />
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Phone Number</label>
                  <input required type="tel" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="+91 99999 99999" onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Aadhaar Mapping</label>
                  <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="XXXX XXXX XXXX" onChange={e => setRegForm({...regForm, aadhaar: e.target.value})} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Gender</label>
                    <select className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500 appearance-none" onChange={e => setRegForm({...regForm, gender: e.target.value})}>
                      <option className="bg-slate-900">Male</option>
                      <option className="bg-slate-900">Female</option>
                      <option className="bg-slate-900">Other</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Blood Group</label>
                    <input className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="O+" onChange={e => setRegForm({...regForm, bloodGroup: e.target.value})} />
                  </div>
                </div>
                <button type="submit" disabled={isSubmitting} className="w-full bg-emerald-600 hover:bg-emerald-500 text-white py-5 rounded-2xl font-black uppercase tracking-widest transition-all shadow-xl shadow-emerald-500/20 mt-4 disabled:opacity-50">
                  {isSubmitting ? 'Registering...' : 'Initialize Secure Vault'}
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      userName={currentUser?.profile.name || ''} 
      isPremium={currentUser?.profile.isPremium}
      onLogout={handleLogout}
    >
      <div className="max-w-7xl mx-auto space-y-8 animate-pop-in">
        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-8">
              <div className="relative group">
                <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-[2.5rem] blur opacity-25 group-hover:opacity-40 transition duration-1000"></div>
                <div className="relative bg-indigo-950 rounded-[2.5rem] p-8 text-white overflow-hidden shadow-2xl">
                  <div className="absolute top-0 right-0 p-12 opacity-10 transform scale-150 rotate-12">
                    <i className="fas fa-microchip text-9xl"></i>
                  </div>
                  <div className="flex justify-between items-start mb-12">
                    <div>
                      <p className="text-indigo-300 text-[10px] font-black uppercase tracking-widest mb-1">Vault Carrier</p>
                      <h3 className="text-2xl font-bold tracking-tight">{currentUser?.profile.name}</h3>
                    </div>
                    <div className="text-right">
                      <p className="text-indigo-300 text-[10px] font-black uppercase tracking-widest mb-1">ID Issued By</p>
                      <p className="font-bold">{APP_NAME}</p>
                    </div>
                  </div>
                  <div className="flex items-end justify-between">
                    <div>
                      <p className="text-indigo-300 text-[10px] font-black uppercase tracking-widest mb-1">Secure Health ID</p>
                      <p className="text-2xl font-mono font-bold tracking-[0.2em]">{currentUser?.profile.healthId}</p>
                    </div>
                    <div className="flex space-x-4 text-xs font-bold">
                      <div className="bg-white/10 px-3 py-1.5 rounded-lg">Blood: {currentUser?.profile.bloodGroup}</div>
                      <div className="bg-white/10 px-3 py-1.5 rounded-lg">Age: {currentUser?.profile.age}</div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <RecordCard title="Active Treatments" icon={ICONS.MEDS}>
                  <div className="space-y-4">
                    {currentUser?.medications.filter(m => m.status === 'active').map(med => (
                      <div key={med.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                        <div className="flex items-center space-x-3">
                          <div className="text-indigo-600 text-xl">{ICONS.MEDS}</div>
                          <div>
                            <p className="font-bold text-slate-800">{med.name}</p>
                            <p className="text-xs text-slate-500">{med.dosage} • {med.frequency}</p>
                          </div>
                        </div>
                        <span className="text-[10px] font-black bg-emerald-100 text-emerald-700 px-2 py-1 rounded-md uppercase">Active</span>
                      </div>
                    ))}
                    {currentUser?.medications.filter(m => m.status === 'active').length === 0 && (
                      <p className="text-slate-400 text-sm text-center py-4 italic">No active medications reported.</p>
                    )}
                  </div>
                </RecordCard>

                <RecordCard title="Critical Allergies" icon={ICONS.ALLERGY}>
                  <div className="flex flex-wrap gap-2">
                    {currentUser?.allergies.map(allergy => (
                      <span key={allergy.id} className={`px-4 py-2 rounded-xl text-xs font-bold border ${allergy.severity === 'high' ? 'bg-red-50 text-red-600 border-red-100' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>
                        {allergy.substance} ({allergy.severity.toUpperCase()})
                      </span>
                    ))}
                    {currentUser?.allergies.length === 0 && (
                      <p className="text-slate-400 text-sm italic w-full text-center py-4">No allergies recorded.</p>
                    )}
                  </div>
                </RecordCard>
              </div>
            </div>

            <div className="space-y-8">
              <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6">Security Overview</h3>
                <div className="space-y-6">
                  <div className="flex items-center space-x-4">
                    <div className="w-10 h-10 rounded-full bg-emerald-100 flex items-center justify-center text-emerald-600">{ICONS.CHECK}</div>
                    <div>
                      <p className="text-sm font-bold text-slate-800">Biometric Sync</p>
                      <p className="text-xs text-slate-500">Last verified 12m ago</p>
                    </div>
                  </div>
                  <div className="flex items-center space-x-4">
                    <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600">{ICONS.SHIELD_CHECK}</div>
                    <div>
                      <p className="text-sm font-bold text-slate-800">Quantum Encrypted</p>
                      <p className="text-xs text-slate-500">AES-256-GCM Protocol</p>
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-indigo-600 rounded-[2.5rem] p-8 text-white shadow-xl shadow-indigo-600/20">
                <h4 className="font-bold mb-2">Emergency Access</h4>
                <p className="text-indigo-100 text-xs mb-4">In case of emergency, provide your Health ID or Phone Number to any authorized medical professional for instant record retrieval.</p>
                <div className="bg-white/10 p-4 rounded-2xl flex items-center space-x-3">
                  <div className="text-xl">{ICONS.EMERGENCY}</div>
                  <div>
                    <p className="text-[10px] font-black uppercase opacity-60">Primary Contact</p>
                    <p className="font-bold">{currentUser?.profile.phone}</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'records' && (
          <div className="space-y-8">
             <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h3 className="text-2xl font-black text-slate-800">Medical Vault</h3>
                <p className="text-slate-500 text-sm">Organized history of all medical conditions.</p>
              </div>
              <div className="flex bg-slate-200/50 p-1.5 rounded-2xl w-fit">
                <button 
                  onClick={() => setRecordFilter('present')}
                  className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${recordFilter === 'present' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  Active Conditions
                </button>
                <button 
                  onClick={() => setRecordFilter('past')}
                  className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${recordFilter === 'past' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  Medical History
                </button>
              </div>
            </div>

            <RecordCard 
              title={recordFilter === 'present' ? "Current Medical Challenges" : "Resolved Conditions & History"} 
              icon={ICONS.MEDICAL}
              onAdd={() => setShowAddModal('problem')}
            >
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {filteredProblems.map(p => (
                  <div key={p.id} className={`group relative p-6 rounded-3xl border transition-all hover:scale-[1.02] ${recordFilter === 'present' ? 'bg-white border-slate-100 shadow-sm hover:shadow-xl' : 'bg-slate-50/50 border-slate-200 grayscale-[0.5] opacity-80'}`}>
                    <div className="flex justify-between items-start mb-4">
                      <div>
                        <span className={`text-[9px] font-black uppercase px-2 py-1 rounded-md mb-2 inline-block ${p.severity === 'severe' ? 'bg-red-100 text-red-700' : p.severity === 'moderate' ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700'}`}>
                          {p.severity} {p.isChronic ? '• Chronic' : ''}
                        </span>
                        <h4 className="text-lg font-bold text-slate-800">{p.condition}</h4>
                        {p.treatmentProvider && <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-tight mt-1">{p.treatmentProvider}</p>}
                      </div>
                      <div className="text-slate-300 group-hover:text-indigo-500 transition-colors">
                        {ICONS.HISTORY}
                      </div>
                    </div>
                    <div className="space-y-3">
                      <div className="flex items-center text-xs text-slate-500">
                        <span className="w-16 font-bold uppercase tracking-tighter">Onset:</span>
                        <span>{new Date(p.onsetDate).toLocaleDateString()}</span>
                      </div>
                      {p.endDate && (
                        <div className="flex items-center text-xs text-slate-500">
                          <span className="w-16 font-bold uppercase tracking-tighter">End Date:</span>
                          <span>{new Date(p.endDate).toLocaleDateString()}</span>
                        </div>
                      )}
                      {p.prescriptionDetails && (
                        <div className="flex items-start text-xs text-slate-500">
                          <span className="w-16 font-bold uppercase tracking-tighter">Prescr:</span>
                          <span className="flex-1 italic">{p.prescriptionDetails}</span>
                        </div>
                      )}
                      {p.treatment && (
                        <div className="flex items-start text-xs text-slate-500">
                          <span className="w-16 font-bold uppercase tracking-tighter">Plan:</span>
                          <span className="flex-1">{p.treatment}</span>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
                {filteredProblems.length === 0 && (
                  <div className="col-span-full py-20 text-center">
