import { GoogleGenAI, Type } from "@google/genai";
import { HealthRecord, MedicalProblem, GovernmentScheme } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeHealthRecord = async (record: HealthRecord, query: string): Promise<string> => {
  const systemInstruction = `
    You are Shield AI, a professional medical records analyst and healthcare navigator. 
    Analyze the provided health history: ${JSON.stringify(record)}.

    CRITICAL MISSION:
    Identify and suggest specific Indian Government Health Schemes (like Ayushman Bharat - PM-JAY, RSBY, state-specific schemes like CMCHIS in TN or Aarogyasri in Telangana) that the user might be eligible for.

    Guidelines:
    1. DISCLAIMER: "I am Shield AI, a guidance assistant. I am not a substitute for professional medical advice or official government eligibility verification."
    2. Check for drug-drug interactions between ${record.medications.map(m => m.name).join(', ')}.
    3. Mask sensitive IDs in your response.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: query,
      config: {
        systemInstruction,
        temperature: 0.6,
        thinkingConfig: { thinkingBudget: 4000 }
      },
    });

    return response.text || "I'm sorry, I couldn't process your request.";
  } catch (error) {
    console.error("Gemini AI error:", error);
    return "I encountered an error while analyzing your health data.";
  }
};

export const findApplicableSchemes = async (problem: MedicalProblem, userAge: number): Promise<GovernmentScheme[]> => {
  const prompt = `
    Find specific Indian Government Health Schemes for a patient with this diagnosis: "${problem.condition}".
    Patient Age: ${userAge}
    Severity: ${problem.severity}
    Is Chronic: ${problem.isChronic ? 'Yes' : 'No'}

    Focus on schemes like:
    - PM-JAY (Ayushman Bharat)
    - CGHS / ECHS
    - State schemes (e.g., Aarogyasri, Mahatma Jyotirao Phule Jan Arogya Yojana, etc.)
    - RAN (Rashtriya Arogya Nidhi)
    - Health Minister's Discretionary Grant
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              name: { type: Type.STRING },
              benefits: { type: Type.STRING },
              eligibility: { type: Type.STRING },
              officialLink: { type: Type.STRING }
            },
            required: ["id", "name", "benefits", "eligibility"]
          }
        }
      }
    });

    const jsonStr = response.text;
    return JSON.parse(jsonStr);
  } catch (error) {
    console.error("Error finding schemes:", error);
    return [];
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  UserProfile, 
  HealthRecord, 
  ChatMessage, 
  Interaction, 
  MedicalProblem, 
  Medication, 
  Surgery, 
  Allergy, 
  TreatmentNote, 
  FamilyHistory,
  GovernmentScheme
} from './types';
