const SESSION_KEY = 'health_shield_active_session';

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | 'family' | null;
type LoginMethod = 'healthid' | 'phone';

const UNIVERSAL_SCHEMES = [
  { id: 'pmjay', name: 'Ayushman Bharat (PM-JAY)', benefits: 'Cashless cover of up to ₹5 lakh per family per year for secondary and tertiary care hospitalization.', eligibility: 'Identified through SECC data or RSBY cards.' },
  { id: 'cghs', name: 'Central Govt Health Scheme', benefits: 'Comprehensive medical care facilities for Central Government employees, pensioners, and their dependents.', eligibility: 'Central government employees and pensioners.' },
  { id: 'state-ma', name: 'State Specific (MA / Aarogyasri)', benefits: 'Varies by state (e.g. up to ₹2.5-5 Lakhs cover for specific surgical procedures).', eligibility: 'Low-income households as defined by state ration cards.' }
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [loginMethod, setLoginMethod] = useState<LoginMethod>('healthid');
  const [loginId, setLoginId] = useState('');
  const [phoneInput, setPhoneInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isAnalyzingRecord, setIsAnalyzingRecord] = useState<string | null>(null);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');

  // Registration form state
  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', isPremium: false
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const newHealthId = `HS-${Math.floor(1000 + Math.random() * 9000)}-${Math.floor(1000 + Math.random() * 9000)}`;
    const newRecord: HealthRecord = {
      profile: { ...regForm, healthId: newHealthId },
      problems: [], medications: [], surgeries: [], allergies: [], notes: [], familyHistory: [], interactions: []
    };
    await dbService.saveRecord(newRecord);

    setTimeout(() => {
      setCurrentUser(newRecord);
      setIsAuth(true);
      setIsSubmitting(false);
      localStorage.setItem(SESSION_KEY, newHealthId);
    }, 1500);
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    setIsSubmitting(true);

    if (loginMethod === 'phone' && !isVerifyingOtp) {
      const record = await dbService.getRecordByPhone(phoneInput);
      if (record) {
        setTimeout(() => {
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
        }, 1000);
      } else {
        setAuthError('No record found with this phone number.');
        setIsSubmitting(false);
      }
      return;
    }

    let record: HealthRecord | null = null;
    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
    } else {
      if (otpInput === '123456') {
        record = await dbService.getRecordByPhone(phoneInput);
      } else {
        setAuthError('Invalid OTP code. Try 123456 for demo.');
        setIsSubmitting(false);
        return;
      }
    }

    if (record) {
      setTimeout(() => {
        setCurrentUser(record);
        setIsAuth(true);
        setIsSubmitting(false);
        localStorage.setItem(SESSION_KEY, record!.profile.healthId);
      }, 1200);
    } else {
      setAuthError('Invalid credentials. Access Denied.');
      setIsSubmitting(false);
    }
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    localStorage.removeItem(SESSION_KEY);
  };

  const handleAskAi = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);

    try {
      const response = await analyzeHealthRecord(currentUser, userQuery);
      const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
      setChatHistory(prev => [...prev, aiMsg]);

      const updatedUser = { ...currentUser, interactions: [...(currentUser.interactions || []), { id: Date.now().toString(), query: userQuery, response, timestamp: Date.now() }] };
      setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAiLoading(false);
    }
  };

  const addProblem = async (problem: MedicalProblem) => {
    if (!currentUser) return;

    // Optimistically add the problem first
    const initialUpdated = { ...currentUser, problems: [...currentUser.problems, problem] };
    setCurrentUser(initialUpdated);
    setShowAddModal(null);

    // Automatically Trigger AI Scheme Analysis
    setIsAnalyzingRecord(problem.id);
    try {
      const matchedSchemes = await findApplicableSchemes(problem, currentUser.profile.age);
      const updatedProblem = { ...problem, applicableSchemes: matchedSchemes };

      const finalUpdated = { 
        ...currentUser, 
        problems: initialUpdated.problems.map(p => p.id === problem.id ? updatedProblem : p) 
      };

      setCurrentUser(finalUpdated);
      await dbService.saveRecord(finalUpdated);
    } catch (err) {
      console.error("Auto-analysis failed:", err);
      await dbService.saveRecord(initialUpdated);
    } finally {
      setIsAnalyzingRecord(null);
    }
  };

  const filteredProblems = useMemo(() => {
    if (!currentUser) return [];
    return currentUser.problems.filter(p => 
      recordFilter === 'present' ? p.status === 'present' : (p.status === 'past' || p.status === 'recovered')
    );
  }, [currentUser, recordFilter]);

  if (isLoading) return (
    <div className="min-h-screen flex items-center justify-center bg-[#0a0f1d] text-white">
      <div className="text-center">
        <div className="w-20 h-20 border-t-4 border-indigo-500 rounded-full animate-spin mx-auto mb-6"></div>
        <p className="font-black tracking-[0.3em] text-indigo-400 text-sm">ENCRYPTION ENGINE INITIALIZING</p>
      </div>
    </div>
  );

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-[#0a0f1d] overflow-hidden relative">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-600/10 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-emerald-600/10 blur-[120px] rounded-full"></div>

        <div className="w-full max-w-lg animate-pop-in relative z-10">
          <div className="bg-white/[0.03] backdrop-blur-3xl border border-white/10 rounded-[3rem] p-10 auth-card shadow-2xl">
            <div className="text-center mb-10">
              <div className="relative inline-block mb-6">
                <div className="absolute inset-0 bg-indigo-500 blur-2xl opacity-20 animate-pulse"></div>
                <div className="w-20 h-20 bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-3xl flex items-center justify-center text-4xl shadow-2xl relative border border-white/20">
                  {isSubmitting ? <i className="fas fa-circle-notch animate-spin text-white"></i> : ICONS.LOCK}
                </div>
              </div>
              <h1 className="text-3xl font-black text-white tracking-tight">{APP_NAME}</h1>
              <p className="text-indigo-300/60 text-xs font-bold uppercase tracking-widest mt-2">Personal Health Vault • Biometric Sync</p>
            </div>

            <div className="flex bg-white/5 p-1.5 rounded-[1.5rem] mb-10 border border-white/5">
              <button 
                onClick={() => { setAuthMode('login'); setAuthError(''); setIsVerifyingOtp(false); }}
                className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'login' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20' : 'text-slate-400 hover:text-white'}`}
              >
                Login
              </button>
              <button 
                onClick={() => { setAuthMode('register'); setAuthError(''); }}
                className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'register' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20' : 'text-slate-400 hover:text-white'}`}
              >
                Register
              </button>
            </div>

            {authMode === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-6">
                {!isVerifyingOtp && (
                  <div className="flex bg-white/5 p-1 rounded-xl mb-4 border border-white/5">
                    <button 
                      type="button"
                      onClick={() => {setLoginMethod('healthid'); setAuthError('');}}
                      className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'healthid' ? 'bg-white/10 text-white' : 'text-slate-500'}`}
                    >
