                  <i className="fas fa-ambulance"></i>
                </div>
                <h4 className="font-black text-[11px] uppercase tracking-[0.2em] mb-4 text-red-100">Emergency Protocol</h4>
                <p className="text-red-50 text-xs mb-6 opacity-80 leading-relaxed">Provide your Health ID or Phone Number to any authorized responder for instant critical access.</p>
                <div className="bg-white/10 backdrop-blur-md p-4 rounded-2xl border border-white/10 flex items-center space-x-3">
                  <div className="w-10 h-10 rounded-xl bg-white/10 flex items-center justify-center text-xl">
                    {ICONS.EMERGENCY}
