      // 1. Try Health ID search first
      if (historySearchQuery.toUpperCase().startsWith('HS-')) {
        const record = await dbService.getRecord(historySearchQuery);
        if (record) {
          setSearchedRecord(record);
          setIsSearchingHistory(false);
          return;
        }
      }

      // 2. Try Name search
      const results = await dbService.getRecordsByName(historySearchQuery);
      if (results.length === 1) {
        setSearchedRecord(results[0]);
      } else if (results.length > 1) {
        setPotentialMatches(results);
      } else {
        // 3. Fallback: Check if it was an ID that didn't match exactly or just wasn't found
        setHistorySearchError('No matching medical vault identified by ID or Name.');
      }
    } catch (err) {
      setHistorySearchError('System fault during vault interrogation.');
    } finally {
      setIsSearchingHistory(false);
    }
  };

  const addProblem = async (problem: MedicalProblem) => {
    if (!currentUser) return;
    const initialUpdated = { ...currentUser, problems: [...currentUser.problems, problem] };
    setCurrentUser(initialUpdated);
    setShowAddModal(null);

    // Auto-trigger analysis
    await runSchemeAnalysis(problem.id);
  };

  const addMedication = async (medication: Medication) => {
    if (!currentUser) return;
    const updated = { ...currentUser, medications: [...currentUser.medications, medication] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
