              <div className="space-y-2">
                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-[0.25em] ml-2">Prescribing Professional</label>
                <input name="prescribedBy" className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black text-slate-800 focus:ring-8 focus:ring-indigo-500/5 outline-none transition-all shadow-inner" placeholder="Dr. Sharma" />
