                <textarea name="instructions" className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-semibold text-slate-800 focus:ring-8 focus:ring-indigo-500/5 outline-none transition-all h-24 resize-none shadow-inner" placeholder="Take with food, avoid alcohol..."></textarea>
