                <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-[2.5rem] p-8 text-white shadow-xl shadow-indigo-600/20">
                  <h4 className="font-black text-[11px] uppercase tracking-[0.2em] mb-4">Upgrade to Pro</h4>
                  <p className="text-indigo-50 text-xs mb-6 opacity-80 leading-relaxed">Unlock advanced AI analysis and insurance mapping.</p>
                  <button onClick={() => setShowAddModal('premium')} className="w-full bg-white text-indigo-600 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest">Activate Shield Pro</button>
                </div>
