              <div className="flex bg-slate-100 p-1.5 rounded-2xl w-fit">
                <button onClick={() => setRecordFilter('present')} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.15em] transition-all ${recordFilter === 'present' ? 'bg-white text-indigo-600 shadow-lg' : 'text-slate-500'}`}>Active</button>
                <button onClick={() => setRecordFilter('past')} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.15em] transition-all ${recordFilter === 'past' ? 'bg-white text-indigo-600 shadow-lg' : 'text-slate-500'}`}>History</button>
              </div>
            </div>

            <RecordCard title={recordFilter === 'present' ? "Current Conditions" : "Medical History"} icon={ICONS.MEDICAL} onAdd={currentUser?.profile.role === 'patient' ? () => setShowAddModal('problem') : undefined}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {filteredProblems.map(p => (
                  <div key={p.id} className="p-8 rounded-[2.5rem] border bg-white border-slate-100 shadow-sm">
                    <h4 className="text-xl font-black text-slate-800 leading-tight mb-2">{p.condition}</h4>
                    <span className={`text-[8px] font-black uppercase px-2.5 py-1 rounded-full ${p.severity === 'severe' ? 'bg-red-100 text-red-700' : 'bg-emerald-100 text-emerald-700'}`}>{p.severity} Priority</span>
                    <p className="text-xs text-slate-500 mt-4 italic">{p.treatment}</p>
                  </div>
                ))}
              </div>
            </RecordCard>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="max-w-5xl mx-auto space-y-12 pb-20">
            <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm relative overflow-hidden group">
               <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:rotate-12 transition-transform duration-700">
                  <i className="fas fa-search-plus text-8xl"></i>
               </div>
               <div className="mb-10 text-center">
                  <h3 className="text-2xl font-black text-slate-800 tracking-tight">Vault Record Interrogation</h3>
                  <p className="text-slate-500 mt-2 text-sm">Enter a patient's unique Health ID to request temporary medical data access.</p>
               </div>
               <div className="flex flex-col md:flex-row gap-4 max-w-2xl mx-auto relative z-10">
                  <div className="flex-grow relative">
                    <div className="absolute left-6 top-1/2 -translate-y-1/2 text-indigo-400">{ICONS.SEARCH}</div>
                    <input 
                      type="text" placeholder="Search Patient ID or Name..." value={historySearchQuery}
                      onChange={(e) => setHistorySearchQuery(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleHistorySearch()}
                      className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-14 pr-6 py-4 text-slate-800 font-bold focus:ring-4 focus:ring-indigo-500/10 outline-none placeholder:text-slate-300"
                    />
                  </div>
                  <button onClick={handleHistorySearch} disabled={isSearchingHistory || !historySearchQuery.trim()} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl shadow-indigo-600/20 disabled:opacity-50 transition-all">
                    {isSearchingHistory ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-search"></i>} Interrogate
                  </button>
               </div>
               {historySearchError && <p className="text-red-500 text-xs font-bold text-center mt-4 bg-red-50 py-2 rounded-xl border border-red-100">{historySearchError}</p>}
            </div>

            {isAuthorizing && pendingRecord && (
               <div className="animate-pop-in bg-indigo-950 p-10 rounded-[3rem] text-white shadow-2xl relative overflow-hidden text-center">
                  <div className="w-16 h-16 bg-white/10 rounded-full flex items-center justify-center mx-auto mb-6"><i className="fas fa-fingerprint text-3xl text-emerald-400"></i></div>
                  <h4 className="text-xl font-black mb-2">Patient Consent Required</h4>
                  <p className="text-indigo-200 text-sm mb-8">Authorization code sent to <b>{pendingRecord.profile.name}</b>.</p>
                  <div className="max-w-xs mx-auto space-y-4">
