              </div>
            </div>
          </div>
        )}
      </div>

      {/* Entry Modals */}
      {showAddModal === 'problem' && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 overflow-y-auto">
