            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 w-12 h-12 rounded-full bg-slate-50 text-slate-400 hover:text-slate-800 transition-all">&times;</button>
            <h3 className="text-3xl font-black text-slate-800 tracking-tight mb-8">Vault Condition Entry</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const formData = new FormData(e.currentTarget);
              addProblem({
                id: Date.now().toString(),
                condition: formData.get('condition') as string,
                status: formData.get('status') as any,
                severity: formData.get('severity') as any,
                onsetDate: formData.get('onsetDate') as string,
                treatment: formData.get('treatment') as string
              }, searchedRecord || undefined);
            }} className="grid grid-cols-1 sm:grid-cols-2 gap-8">
              <div className="sm:col-span-2"><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Condition Descriptor</label><input name="condition" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black focus:ring-8 focus:ring-indigo-500/5 outline-none" placeholder="e.g. Stage II Hypertension" /></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Severity</label><select name="severity" className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black"><option value="mild">Low Priority</option><option value="moderate">Moderate</option><option value="severe">Critical</option></select></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Onset Date</label><input name="onsetDate" type="date" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black" /></div>
              <div className="sm:col-span-2"><label className="block text-[10px] font-black uppercase text-indigo-400 mb-2">Treatment Plan</label><textarea name="treatment" required className="w-full bg-white border border-indigo-100 rounded-[1.8rem] px-8 py-5 text-sm font-semibold h-24 resize-none"></textarea></div>
              <button type="submit" className="sm:col-span-2 w-full bg-indigo-600 text-white py-8 rounded-[2.5rem] font-black uppercase tracking-[0.3em] active:scale-[0.98] transition-all">Commit Condition</button>
            </form>
          </div>
        </div>
      )}
      {/* ... other modals ... */}
    </Layout>
  );
};

export default App;

