        )}

        {activeTab === 'shield' && (
          <div className="max-w-5xl mx-auto flex flex-col h-[calc(100vh-16rem)] bg-white rounded-[4rem] shadow-2xl border border-slate-100 overflow-hidden relative">
            <div className="p-8 border-b border-slate-100 bg-slate-50/80 flex items-center gap-5">
              <div className="w-12 h-12 rounded-2xl bg-indigo-600 text-white flex items-center justify-center shadow-2xl shadow-indigo-600/30">{ICONS.AI}</div>
              <div><h3 className="text-base font-black text-slate-800 uppercase tracking-widest">Shield Intelligence Terminal</h3><p className="text-[11px] font-black text-emerald-500 uppercase tracking-widest mt-1.5 flex items-center"><span className="w-2 h-2 bg-emerald-500 rounded-full mr-2 animate-pulse"></span>Neural Link Active</p></div>
            </div>
            <div className="flex-grow overflow-y-auto space-y-8 p-10 bg-slate-50/20">
              {chatHistory.map((chat, i) => (
                <div key={i} className={`flex ${chat.role === 'user' ? 'justify-end' : 'justify-start'} animate-pop-in`}>
                  <div className={`max-w-[85%] p-7 rounded-[2.5rem] shadow-sm ${chat.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-white border border-slate-100 text-slate-800 rounded-tl-none'}`}>
                    <p className="text-sm font-medium whitespace-pre-wrap">{chat.content}</p>
                  </div>
                </div>
              ))}
              {isAiLoading && <div className="flex justify-start animate-pulse"><div className="bg-white p-7 rounded-[2.5rem] border border-slate-100 flex items-center space-x-3"><div className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce"></div><div className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce delay-75"></div><div className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce delay-150"></div></div></div>}
            </div>
            <div className="p-10 border-t border-slate-100 bg-white">
              <div className="bg-slate-100 border border-slate-200 rounded-[3rem] flex items-center p-3">
                <input type="text" className="flex-grow bg-transparent outline-none text-sm px-6 py-4 font-bold" placeholder="Consult Shield AI..." value={userQuery} onChange={(e) => setUserQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleAskAi()} />
                <button onClick={handleAskAi} disabled={isAiLoading || !userQuery.trim()} className="w-14 h-14 bg-indigo-600 text-white rounded-full flex items-center justify-center transition-all disabled:opacity-20 active:scale-90"><i className="fas fa-paper-plane"></i></button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Shared Modals for Problems and Notes */}
      {showAddModal === 'problem' && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[4rem] w-full max-w-2xl p-12 animate-pop-in relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 w-12 h-12 rounded-full bg-slate-50 text-slate-400 hover:text-slate-800 transition-all">&times;</button>
            <h3 className="text-3xl font-black text-slate-800 tracking-tight mb-8">Vault Condition Entry</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const formData = new FormData(e.currentTarget);
              addProblem({
                id: Date.now().toString(),
                condition: formData.get('condition') as string,
                status: formData.get('status') as any,
                severity: formData.get('severity') as any,
                onsetDate: formData.get('onsetDate') as string,
                treatment: formData.get('treatment') as string
              }, searchedRecord || undefined);
            }} className="grid grid-cols-1 sm:grid-cols-2 gap-8">
              <div className="sm:col-span-2"><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Condition Descriptor</label><input name="condition" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black focus:ring-8 focus:ring-indigo-500/5 outline-none" placeholder="e.g. Stage II Hypertension" /></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Severity</label><select name="severity" className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black"><option value="mild">Low Priority</option><option value="moderate">Moderate</option><option value="severe">Critical</option></select></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Onset Date</label><input name="onsetDate" type="date" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black" /></div>
              <div className="sm:col-span-2"><label className="block text-[10px] font-black uppercase text-indigo-400 mb-2">Treatment Plan</label><textarea name="treatment" required className="w-full bg-white border border-indigo-100 rounded-[1.8rem] px-8 py-5 text-sm font-semibold h-24 resize-none"></textarea></div>
              <button type="submit" className="sm:col-span-2 w-full bg-indigo-600 text-white py-8 rounded-[2.5rem] font-black uppercase tracking-[0.3em] active:scale-[0.98] transition-all">Commit Condition</button>
            </form>
          </div>
        </div>
      )}

      {showAddModal === 'note' && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[4rem] w-full max-w-2xl p-12 animate-pop-in relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 w-12 h-12 rounded-full bg-slate-50 text-slate-400 hover:text-slate-800 transition-all">&times;</button>
            <h3 className="text-3xl font-black text-slate-800 tracking-tight mb-8">Consultation Note</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const formData = new FormData(e.currentTarget);
              addNote({
                id: Date.now().toString(),
                doctorName: currentUser?.profile.name || "Unknown",
                date: new Date().toISOString(),
                category: formData.get('category') as any,
                note: formData.get('note') as string
              }, searchedRecord || undefined);
            }} className="space-y-8">
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Category</label><select name="category" className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black"><option value="Consultation">Routine Consultation</option><option value="Follow-up">Follow-up</option><option value="Emergency">Emergency</option><option value="Surgery">Post-Surgical</option></select></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Clinical Findings & Advice</label><textarea name="note" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-semibold h-40 resize-none"></textarea></div>
              <button type="submit" className="w-full bg-indigo-600 text-white py-8 rounded-[2.5rem] font-black uppercase tracking-[0.3em] active:scale-[0.98] transition-all">Verify & Archive Note</button>
            </form>
          </div>
        </div>
      )}

      {showAddModal === 'premium' && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[4rem] w-full max-w-3xl p-12 animate-pop-in relative border border-white/20">
             <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 text-2xl text-slate-400 hover:text-slate-800">&times;</button>
             <div className="text-center mb-12">
                <div className="w-20 h-20 bg-indigo-600 text-white rounded-3xl flex items-center justify-center text-4xl mx-auto mb-6 shadow-2xl shadow-indigo-600/30"><i className="fas fa-crown"></i></div>
                <h3 className="text-3xl font-black text-slate-800 tracking-tight">Activate Shield Pro Intelligence</h3>
                <p className="text-slate-500 mt-2 font-medium">Access quantum-level health record analysis and insurance matching.</p>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
                <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 flex flex-col items-center group cursor-pointer hover:border-indigo-600 transition-all">
                   <h4 className="text-xl font-black text-slate-800 mb-2">Personal Shield</h4>
                   <p className="text-sm text-slate-500 mb-6 font-medium">For individual health tracking</p>
                   <div className="text-3xl font-black text-indigo-600 mb-8">₹499<span className="text-sm font-bold text-slate-400 tracking-normal">/yr</span></div>
                   <button onClick={() => handleUpgrade('pro')} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-indigo-600 transition-all">Select Plan</button>
                </div>
                <div className="bg-indigo-50 p-8 rounded-[2.5rem] border-2 border-indigo-600 flex flex-col items-center group cursor-pointer relative shadow-xl shadow-indigo-100">
                   <div className="absolute -top-3 bg-indigo-600 text-white text-[9px] font-black uppercase px-4 py-1.5 rounded-full tracking-widest">Most Popular</div>
                   <h4 className="text-xl font-black text-indigo-900 mb-2">Family Shield</h4>
                   <p className="text-sm text-indigo-500 mb-6 font-bold">Up to 5 family members</p>
                   <div className="text-3xl font-black text-indigo-600 mb-8">₹1299<span className="text-sm font-bold text-slate-400 tracking-normal">/yr</span></div>
                   <button onClick={() => handleUpgrade('family')} className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-indigo-700 transition-all">Activate Now</button>
                </div>
             </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  UserProfile, 
  HealthRecord, 
  ChatMessage, 
  Interaction, 
  MedicalProblem, 
  Medication, 
  Surgery, 
  Allergy, 
  TreatmentNote, 
  FamilyHistory,
  GovernmentScheme,
  DoctorAccessLog
} from './types';
import { ICONS, APP_NAME, STORAGE_KEY, MAX_LOGIN_ATTEMPTS, LOCKOUT_DURATION_MS, OTP_EXPIRY_MS } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord, findApplicableSchemes } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';
const ACCESS_TIMEOUT_MS = 15 * 60 * 1000; // 15 Minutes

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | 'family' | 'premium' | 'edit_patient' | null;
type LoginMethod = 'healthid' | 'phone';

const UNIVERSAL_SCHEMES = [
  { id: 'pmjay', name: 'Ayushman Bharat (PM-JAY)', benefits: 'Cashless cover of up to ₹5 lakh per family per year for secondary and tertiary care hospitalization.', eligibility: 'Identified through SECC data or RSBY cards.' },
  { id: 'cghs', name: 'Central Govt Health Scheme', benefits: 'Comprehensive medical care facilities for Central Government employees, pensioners, and their dependents.', eligibility: 'Central government employees and pensioners.' },
  { id: 'state-ma', name: 'State Specific (MA / Aarogyasri)', benefits: 'Varies by state (e.g. up to ₹2.5-5 Lakhs cover for specific surgical procedures).', eligibility: 'Low-income households as defined by state ration cards.' }
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [loginMethod, setLoginMethod] = useState<LoginMethod>('healthid');
  const [roleMode, setRoleMode] = useState<'patient' | 'doctor'>('patient');
  const [loginId, setLoginId] = useState('');
  const [phoneInput, setPhoneInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isAnalyzingRecord, setIsAnalyzingRecord] = useState<string | null>(null);
  const [selectedScheme, setSelectedScheme] = useState<GovernmentScheme | null>(null);

  // Rate Limiting & OTP States
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);
  const [activeOtp, setActiveOtp] = useState<{ code: string, expiresAt: number } | null>(null);
  const [otpTimeLeft, setOtpTimeLeft] = useState(0);

  // Search History Tab States
  const [historySearchQuery, setHistorySearchQuery] = useState('');
  const [searchedRecord, setSearchedRecord] = useState<HealthRecord | null>(null);
  const [potentialMatches, setPotentialMatches] = useState<HealthRecord[]>([]);
  const [isSearchingHistory, setIsSearchingHistory] = useState(false);
  const [historySearchError, setHistorySearchError] = useState('');

  // Secure Access States for external records
  const [pendingRecord, setPendingRecord] = useState<HealthRecord | null>(null);
  const [isAuthorizing, setIsAuthorizing] = useState(false);
  const [authOtp, setAuthOtp] = useState('');
  const [accessExpiry, setAccessExpiry] = useState<number | null>(null);
  const timerRef = useRef<number | null>(null);
  const lockoutTimerRef = useRef<number | null>(null);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');

  // Registration form state
  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', role: 'patient', isPremium: false
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
        }
      }
      setIsLoading(false);
    };
    init();

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      if (lockoutTimerRef.current) clearInterval(lockoutTimerRef.current);
    };
  }, []);

  // OTP Timer Logic
  useEffect(() => {
    let interval: number;
    if (activeOtp) {
      interval = setInterval(() => {
        const remaining = Math.max(0, activeOtp.expiresAt - Date.now());
        setOtpTimeLeft(Math.floor(remaining / 1000));
        if (remaining === 0) {
          setActiveOtp(null);
          clearInterval(interval);
        }
      }, 1000) as unknown as number;
    }
    return () => clearInterval(interval);
  }, [activeOtp]);

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const array = new Uint32Array(2);
    crypto.getRandomValues(array);
    const part1 = (array[0] % 9000 + 1000).toString();
    const part2 = (array[1] % 9000 + 1000).toString();

    const prefix = roleMode === 'doctor' ? 'DR' : 'HS';
    const newHealthId = `${prefix}-${part1}-${part2}`;

    const newRecord: HealthRecord = {
      profile: { ...regForm, role: roleMode, healthId: newHealthId },
      problems: [], medications: [], surgeries: [], allergies: [], notes: [], familyHistory: [], interactions: [], accessHistory: []
    };
    await dbService.saveRecord(newRecord);

    setTimeout(() => {
      setCurrentUser(newRecord);
      setIsAuth(true);
      setIsSubmitting(false);
      localStorage.setItem(SESSION_KEY, newHealthId);
    }, 1500);
  };

  const checkLockout = () => {
    if (lockoutUntil && Date.now() < lockoutUntil) {
      const remainingMinutes = Math.ceil((lockoutUntil - Date.now()) / 60000);
      setAuthError(`Too many failed attempts. Try again in ${remainingMinutes} minute(s).`);
      return true;
    }
    return false;
  };

  const handleLoginFailure = () => {
    const newAttempts = loginAttempts + 1;
    setLoginAttempts(newAttempts);
    if (newAttempts >= MAX_LOGIN_ATTEMPTS) {
      const until = Date.now() + LOCKOUT_DURATION_MS;
      setLockoutUntil(until);
      setAuthError(`Too many failed attempts. Locked out for 5 minutes.`);
    } else {
      setAuthError(`Invalid credentials. ${MAX_LOGIN_ATTEMPTS - newAttempts} attempts remaining.`);
    }
    setIsSubmitting(false);
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    if (checkLockout()) return;
    setIsSubmitting(true);

    if (loginMethod === 'phone' && !isVerifyingOtp) {
      const record = await dbService.getRecordByPhone(phoneInput);
      if (record) {
        if (record.profile.role !== roleMode) {
          setAuthError(`The requested account is registered as a ${record.profile.role}.`);
          setIsSubmitting(false);
          return;
        }
        const code = Math.floor(100000 + Math.random() * 900000).toString();
        const expiresAt = Date.now() + OTP_EXPIRY_MS;
        setActiveOtp({ code, expiresAt });
        console.log(`[SECURITY] SECURE OTP GENERATED: ${code}`);

        setTimeout(() => {
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
        }, 1000);
      } else {
        setAuthError('No record found with this phone number.');
        setIsSubmitting(false);
      }
      return;
    }

    let record: HealthRecord | null = null;
    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
      if (!record || record.profile.role !== roleMode) {
        handleLoginFailure();
        return;
      }
    } else {
      if (activeOtp && otpInput === activeOtp.code && Date.now() < activeOtp.expiresAt) {
        record = await dbService.getRecordByPhone(phoneInput);
        setActiveOtp(null);
      } else if (activeOtp && Date.now() >= activeOtp.expiresAt) {
        setAuthError('OTP has expired.');
        setIsSubmitting(false);
        return;
      } else {
        handleLoginFailure();
        return;
      }
    }

    if (record) {
      setTimeout(() => {
        setLoginAttempts(0);
        setLockoutUntil(null);
        setCurrentUser(record);
        setIsAuth(true);
        setIsSubmitting(false);
        localStorage.setItem(SESSION_KEY, record!.profile.healthId);
      }, 1200);
    }
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    localStorage.removeItem(SESSION_KEY);
    if (timerRef.current) clearInterval(timerRef.current);
  };

  const handleHistorySearch = async () => {
    if (!historySearchQuery.trim()) return;
    setIsSearchingHistory(true);
    setHistorySearchError('');
    setSearchedRecord(null);
    setPotentialMatches([]);
    setPendingRecord(null);
    setIsAuthorizing(false);

    try {
      if (historySearchQuery.toUpperCase().startsWith('HS-') || historySearchQuery.toUpperCase().startsWith('DR-')) {
        const record = await dbService.getRecord(historySearchQuery);
        if (record) {
          triggerAuthorization(record);
          setIsSearchingHistory(false);
          return;
        }
      }

      const results = await dbService.getRecordsByName(historySearchQuery);
      if (results.length === 1) {
        triggerAuthorization(results[0]);
      } else if (results.length > 1) {
        setPotentialMatches(results);
      } else {
        setHistorySearchError('No matching medical vault identified.');
      }
    } catch (err) {
      setHistorySearchError('System fault.');
    } finally {
      setIsSearchingHistory(false);
    }
  };

  const triggerAuthorization = (record: HealthRecord) => {
    if (currentUser && record.profile.healthId === currentUser.profile.healthId) {
      setSearchedRecord(record);
      return;
    }
    setPendingRecord(record);
    setIsAuthorizing(true);
  };

  const handleVerifyAccess = async () => {
    if (authOtp === '123456') {
      setSearchedRecord(pendingRecord);

      if (currentUser?.profile.role === 'doctor' && pendingRecord) {
        const logEntry: DoctorAccessLog = {
          patientHealthId: pendingRecord.profile.healthId,
          patientName: pendingRecord.profile.name,
          timestamp: Date.now()
        };
        const updatedDoctor = { 
          ...currentUser, 
          accessHistory: [logEntry, ...(currentUser.accessHistory || []).filter(l => l.patientHealthId !== logEntry.patientHealthId)].slice(0, 10) 
        };
        setCurrentUser(updatedDoctor);
        await dbService.saveRecord(updatedDoctor);
      }

      setPendingRecord(null);
      setIsAuthorizing(false);
      setAuthOtp('');
      const expiry = Date.now() + ACCESS_TIMEOUT_MS;
      setAccessExpiry(expiry);
      if (timerRef.current) clearInterval(timerRef.current);
      timerRef.current = setInterval(() => {
        if (Date.now() > expiry) {
          setSearchedRecord(null);
          setAccessExpiry(null);
          if (timerRef.current) clearInterval(timerRef.current);
        }
      }, 1000) as unknown as number;
    } else {
      setHistorySearchError('Invalid authorization token.');
    }
  };

  const addProblem = async (problem: MedicalProblem, targetRecord?: HealthRecord) => {
    const recordToUpdate = targetRecord || currentUser;
    if (!recordToUpdate) return;

    const updated = { ...recordToUpdate, problems: [...recordToUpdate.problems, problem] };
    if (targetRecord) {
      setSearchedRecord(updated);
      await dbService.saveRecord(updated);
    } else {
      setCurrentUser(updated);
      await dbService.saveRecord(updated);
    }
    setShowAddModal(null);
    if (!targetRecord) await runSchemeAnalysis(problem.id);
  };

  const addAllergy = async (allergy: Allergy, targetRecord?: HealthRecord) => {
    const recordToUpdate = targetRecord || currentUser;
    if (!recordToUpdate) return;

    const updated = { ...recordToUpdate, allergies: [...recordToUpdate.allergies, allergy] };
    if (targetRecord) {
      setSearchedRecord(updated);
      await dbService.saveRecord(updated);
    } else {
      setCurrentUser(updated);
      await dbService.saveRecord(updated);
    }
    setShowAddModal(null);
  };

  const addNote = async (note: TreatmentNote, targetRecord?: HealthRecord) => {
    const recordToUpdate = targetRecord || currentUser;
    if (!recordToUpdate) return;

    const updated = { ...recordToUpdate, notes: [note, ...recordToUpdate.notes] };
    if (targetRecord) {
      setSearchedRecord(updated);
      await dbService.saveRecord(updated);
    } else {
      setCurrentUser(updated);
      await dbService.saveRecord(updated);
    }
    setShowAddModal(null);
  };

  const runSchemeAnalysis = async (problemId: string) => {
    if (!currentUser) return;
    const problem = currentUser.problems.find(p => p.id === problemId);
    if (!problem) return;

    setIsAnalyzingRecord(problemId);
    try {
      const matchedSchemes = await findApplicableSchemes(problem, currentUser.profile.age);
      const updatedProblems = currentUser.problems.map(p => 
        p.id === problemId ? { ...p, applicableSchemes: matchedSchemes } : p
      );
      const updatedUser = { ...currentUser, problems: updatedProblems };
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } catch (err) {
      console.error("Analysis failed:", err);
    } finally {
      setIsAnalyzingRecord(null);
    }
  };

  const handleAskAi = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);

    try {
      const response = await analyzeHealthRecord(currentUser, userQuery);
      const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
      setChatHistory(prev => [...prev, aiMsg]);

      const updatedUser = { ...currentUser, interactions: [...(currentUser.interactions || []), { id: Date.now().toString(), query: userQuery, response, timestamp: Date.now() }] };
      setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleUpgrade = async (plan: string) => {
    if (!currentUser) return;
    setIsSubmitting(true);
    setTimeout(async () => {
      const updated = { 
        ...currentUser, 
        profile: { ...currentUser.profile, isPremium: true, subscriptionPlan: plan as any } 
      };
      setCurrentUser(updated);
      await dbService.saveRecord(updated);
      setIsSubmitting(false);
      setShowAddModal(null);
    }, 2000);
  };

  const filteredProblems = useMemo(() => {
    if (!currentUser) return [];
    return currentUser.problems.filter(p => 
      recordFilter === 'present' ? p.status === 'present' : (p.status === 'past' || p.status === 'recovered')
