              e.preventDefault();
              const formData = new FormData(e.currentTarget);
              addAllergy({
                id: Date.now().toString(),
                substance: formData.get('substance') as string,
                severity: formData.get('severity') as any,
                reaction: formData.get('reaction') as string,
                firstObserved: formData.get('firstObserved') as string
              }, searchedRecord || undefined);
            }} className="grid grid-cols-1 sm:grid-cols-2 gap-8">
              <div className="sm:col-span-2"><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Substance / Trigger Agent</label><input name="substance" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black focus:ring-8 focus:ring-indigo-500/5 outline-none" placeholder="e.g. Peanuts, Penicillin, Latex" /></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Clinical Severity</label><select name="severity" className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black"><option value="low">Low</option><option value="moderate">Moderate</option><option value="high">High (Critical)</option></select></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Approx. Date First Observed</label><input name="firstObserved" type="date" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black" /></div>
              <div className="sm:col-span-2"><label className="block text-[10px] font-black uppercase text-indigo-400 mb-2">Reaction Details & Clinical Presentation</label><textarea name="reaction" required className="w-full bg-white border border-indigo-100 rounded-[1.8rem] px-8 py-5 text-sm font-semibold h-24 resize-none" placeholder="e.g. Anaphylaxis, Rash, Hives..."></textarea></div>
