        {activeTab === 'shield' && (
          <div className="max-w-5xl mx-auto flex flex-col h-[calc(100vh-16rem)] bg-white rounded-[4rem] shadow-2xl border border-slate-100 overflow-hidden relative">
            <div className="p-8 border-b border-slate-100 bg-slate-50/80 flex items-center gap-5">
