                             <div key={type} className="flex items-center justify-between p-6 bg-slate-50 border border-slate-100 rounded-[2rem] hover:border-indigo-200 transition-all cursor-pointer group" onClick={() => {
                                const newSettings = { ...currentUser?.profile.notificationSettings!, [type]: !currentUser?.profile.notificationSettings![type] };
                                updateProfile({ notificationSettings: newSettings });
                             }}>
                                <div><p className="font-bold text-slate-800 uppercase text-[10px] tracking-wider mb-1">{type} Alerts</p><p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">{currentUser?.profile.notificationSettings?.[type] ? 'Active' : 'Muted'}</p></div>
                                <div className={`w-12 h-6 rounded-full relative transition-colors ${currentUser?.profile.notificationSettings?.[type] ? 'bg-indigo-600' : 'bg-slate-300'}`}>
                                   <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${currentUser?.profile.notificationSettings?.[type] ? 'right-1' : 'left-1'}`}></div>
                                </div>
                             </div>
                          ))}
                       </div>
                    </div>

                    {currentUser?.profile.role === 'doctor' && (
                       <div>
                          <h4 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-6">Workday Management</h4>
                          <div className="bg-slate-50 p-8 rounded-[3rem] border border-slate-100">
                             <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                                <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-3">Shift Commencement</label><input type="time" value={currentUser.profile.visitingHours?.start} onChange={e => updateProfile({ visitingHours: { ...currentUser.profile.visitingHours!, start: e.target.value }})} className="w-full bg-white border border-slate-200 rounded-2xl px-6 py-4 font-black text-lg outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all" /></div>
                                <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-3">Shift Conclusion</label><input type="time" value={currentUser.profile.visitingHours?.end} onChange={e => updateProfile({ visitingHours: { ...currentUser.profile.visitingHours!, end: e.target.value }})} className="w-full bg-white border border-slate-200 rounded-2xl px-6 py-4 font-black text-lg outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all" /></div>
                             </div>
                             <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 mb-4">Active Consultation Days</label>
                                <div className="flex flex-wrap gap-3">
                                   {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(day => {
                                      const isActive = currentUser.profile.visitingHours?.days.includes(day);
                                      return (
                                         <button key={day} onClick={() => {
                                            const currentDays = currentUser.profile.visitingHours?.days || [];
                                            const newDays = isActive ? currentDays.filter(d => d !== day) : [...currentDays, day];
                                            updateProfile({ visitingHours: { ...currentUser.profile.visitingHours!, days: newDays }});
                                         }} className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${isActive ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-100'}`}>{day}</button>
                                      );
                                   })}
                                </div>
                             </div>
                          </div>
                       </div>
                    )}
                 </div>
              </RecordCard>
           </div>
        )}

        {activeTab === 'records' && (
          <div className="space-y-12 pb-24">
             <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
