              <div className="flex bg-slate-100 p-1.5 rounded-2xl w-fit border border-slate-200/50">
                <button onClick={() => setRecordFilter('present')} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.15em] transition-all ${recordFilter === 'present' ? 'bg-white text-indigo-600 shadow-lg' : 'text-slate-500 hover:text-slate-700'}`}>Active</button>
                <button onClick={() => setRecordFilter('past')} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.15em] transition-all ${recordFilter === 'past' ? 'bg-white text-indigo-600 shadow-lg' : 'text-slate-500 hover:text-slate-700'}`}>History</button>
              </div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <RecordCard title={recordFilter === 'present' ? "Current Conditions" : "Medical History Log"} icon={ICONS.MEDICAL} onAdd={currentUser?.profile.role === 'patient' ? () => setShowAddModal('problem') : undefined}>
                <div className="space-y-6">
                  {filteredProblems.map(p => (
                    <div key={p.id} className="p-8 rounded-[2.5rem] border bg-white border-slate-100 shadow-sm">
                      <h4 className="text-xl font-black text-slate-800 leading-tight mb-2">{p.condition}</h4>
