                    <div key={med.id} className="p-8 rounded-[2.5rem] border bg-white border-slate-100 shadow-sm relative overflow-hidden group">
                      <div className={`absolute top-0 right-0 w-1.5 h-full ${med.status === 'active' ? 'bg-emerald-500' : 'bg-slate-300'}`}></div>
