                      </div>
                    </div>
                  ))}
                  {currentUser?.medications.length === 0 && <p className="text-center text-slate-400 py-8 italic">No medications documented.</p>}
                </div>
              </RecordCard>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="max-w-7xl mx-auto space-y-12 pb-20">
            <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm relative overflow-hidden group">
               <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:rotate-12 transition-transform duration-700"><i className="fas fa-search-plus text-8xl"></i></div>
               <div className="mb-10 text-center">
                  <h3 className="text-2xl font-black text-slate-800 tracking-tight">Vault Record Interrogation</h3>
                  <p className="text-slate-500 mt-2 text-sm">Enter a patient's unique Health ID to request temporary medical data access.</p>
               </div>
               <div className="flex flex-col md:flex-row gap-4 max-w-2xl mx-auto relative z-10">
                  <div className="flex-grow relative">
                    <div className="absolute left-6 top-1/2 -translate-y-1/2 text-indigo-400">{ICONS.SEARCH}</div>
                    <input type="text" placeholder="Search Patient ID or Name..." value={historySearchQuery} onChange={(e) => setHistorySearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleHistorySearch()} className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-14 pr-6 py-4 text-slate-800 font-bold focus:ring-4 focus:ring-indigo-500/10 outline-none placeholder:text-slate-300" />
                  </div>
                  <button onClick={handleHistorySearch} disabled={isSearchingHistory || !historySearchQuery.trim()} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl shadow-indigo-600/20 disabled:opacity-50 transition-all">{isSearchingHistory ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-search"></i>} Interrogate</button>
               </div>
            </div>
            {isAuthorizing && pendingRecord && (
               <div className="animate-pop-in bg-indigo-950 p-10 rounded-[3rem] text-white shadow-2xl relative overflow-hidden text-center max-w-2xl mx-auto">
                  <div className="w-16 h-16 bg-white/10 rounded-full flex items-center justify-center mx-auto mb-6"><i className="fas fa-fingerprint text-3xl text-emerald-400"></i></div>
                  <h4 className="text-xl font-black mb-2">Patient Consent Required</h4>
                  <div className="max-w-xs mx-auto space-y-4">
                    <input type="text" maxLength={6} placeholder="123456" value={authOtp} onChange={(e) => setAuthOtp(e.target.value)} className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 text-center text-3xl font-black tracking-[0.5em] focus:ring-2 focus:ring-emerald-500 outline-none placeholder:text-slate-800" />
                    <button onClick={handleVerifyAccess} className="w-full bg-emerald-600 hover:bg-emerald-500 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest transition-all">Grant Clinical Access</button>
                  </div>
               </div>
            )}
            {searchedRecord && (
               <div className="animate-pop-in space-y-8">
                  <RecordCard title="Clinical Identity" icon={ICONS.USER}>
                    <div className="space-y-4">
                       <div className="flex justify-between border-b border-slate-50 pb-2"><span className="text-[10px] uppercase font-black text-slate-400">Legal Name</span><span className="text-sm font-bold">{searchedRecord.profile.name}</span></div>
