              <button type="submit" className="sm:col-span-2 w-full bg-indigo-600 text-white py-8 rounded-[2.5rem] font-black uppercase tracking-[0.3em] active:scale-[0.98] transition-all shadow-xl shadow-indigo-600/20">Archiving to Vault</button>
            </form>
          </div>
        </div>
      )}

      {showAddModal === 'surgery' && (
