              <div>
                <label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Medical Center / Hospital</label>
                <input name="hospital" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none" placeholder="e.g. Apollo Hospital" />
