import { GoogleGenAI, Type } from "@google/genai";
import { HealthRecord, MedicalProblem, GovernmentScheme, Reminder } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeHealthRecord = async (record: HealthRecord, query: string): Promise<string> => {
  const systemInstruction = `
    You are Shield AI, a professional medical records analyst and healthcare navigator. 
    Analyze the provided health history: ${JSON.stringify(record)}.

    CRITICAL MISSION:
    Identify and suggest specific Indian Government Health Schemes (like Ayushman Bharat - PM-JAY, RSBY, state-specific schemes like CMCHIS in TN or Aarogyasri in Telangana) that the user might be eligible for.

    Guidelines:
    1. DISCLAIMER: "I am Shield AI, a guidance assistant. I am not a substitute for professional medical advice or official government eligibility verification."
    2. Check for drug-drug interactions between ${record.medications.map(m => m.name).join(', ')}.
    3. Use the severity and status of conditions to prioritize advice. Severe/Present conditions need immediate scheme mapping.
    4. Mask sensitive IDs in your response.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: query,
      config: {
        systemInstruction,
        temperature: 0.6,
        thinkingConfig: { thinkingBudget: 4000 }
      },
    });

    return response.text || "I'm sorry, I couldn't process your request.";
  } catch (error) {
    console.error("Gemini AI error:", error);
    return "I encountered an error while analyzing your health data.";
  }
};

export const generateSmartReminders = async (record: HealthRecord): Promise<Reminder[]> => {
  const prompt = `
    Analyze this health record and generate a set of smart reminders:
    Medications: ${JSON.stringify(record.medications)}
    Recent Surgeries: ${JSON.stringify(record.surgeries)}
    Active Problems: ${JSON.stringify(record.problems)}

    TASK:
    1. Create specific medication reminders based on frequency (e.g., "Twice Daily" should result in morning and evening entries).
    2. Create follow-up reminders for recent surgeries (usually 7 days, 15 days, and 30 days post-op).
    3. Suggest lifestyle reminders based on active conditions (e.g., "Check blood sugar" for diabetics).

    Output a JSON array of Reminder objects.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              time: { type: Type.STRING, description: "Format HH:mm" },
              date: { type: Type.STRING, description: "Format YYYY-MM-DD" },
              type: { type: Type.STRING, enum: ['medication', 'followup', 'lifestyle'] },
              status: { type: Type.STRING, enum: ['pending'] }
            },
            required: ["id", "title", "description", "type", "status"]
          }
        }
      }
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Reminder generation failed:", error);
    return [];
  }
};

export const findApplicableSchemes = async (problem: MedicalProblem, userAge: number): Promise<GovernmentScheme[]> => {
  const prompt = `
    Analyze this medical condition for Indian Government health benefits:
    Diagnosis: "${problem.condition}"
    Condition Status: ${problem.status} (present/past/recovered)
    Clinical Severity: ${problem.severity} (mild/moderate/severe)
    Patient Age: ${userAge}
    Chronic Designation: ${problem.isChronic ? 'Yes' : 'No'}

    CRITICAL TAILORING INSTRUCTIONS: 
    1. Use Google Search to find specific Central (e.g., Ayushman Bharat PM-JAY) and State-specific (e.g., Aarogyasri, CMCHIS, West Bengal Health Scheme, Swasthya Sathi) schemes.
    2. MATCHING LOGIC:
       - If Status is 'PRESENT' and Severity is 'SEVERE', prioritize schemes with Cashless Tertiary Care, High-Value Surgical Packages, and Critical Illness coverage.
       - If Status is 'PRESENT' and Condition is 'CHRONIC', focus on schemes offering recurring outpatient benefits, free diagnostics, or subsidized long-term medication (e.g., PMBJP or state-specific chronic care programs).
       - If Status is 'PAST' or 'RECOVERED', identify schemes for post-operative rehabilitation, secondary complications, or check if the patient is eligible for reimbursement under employment-linked schemes like ESIC or CGHS.
    3. Identify the EXACT financial coverage limits or package rates (INR) where possible.
    4. Define detailed eligibility (income limits, specific social categories, ration card requirements).
    5. Provide required documents and application steps.

    Format the response as a JSON array.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              name: { type: Type.STRING },
              benefits: { type: Type.STRING, description: "Detailed description of benefits tailored to the condition's status and severity." },
              coverageAmount: { type: Type.STRING, description: "Estimated coverage in INR (e.g. ₹5 Lakhs)." },
              eligibility: { type: Type.STRING, description: "Detailed eligibility criteria." },
              requiredDocuments: { 
                type: Type.ARRAY, 
                items: { type: Type.STRING },
                description: "List of documents needed."
              },
              applicationSteps: { 
                type: Type.ARRAY, 
                items: { type: Type.STRING },
                description: "Step-by-step enrollment process."
              },
              officialLink: { type: Type.STRING }
            },
            required: ["id", "name", "benefits", "eligibility", "coverageAmount"]
          }
        }
      }
    });

    const jsonStr = response.text || "[]";
    const schemes: GovernmentScheme[] = JSON.parse(jsonStr);

    // Extract grounding URLs if available
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks && schemes.length > 0) {
      const sources = groundingChunks
        .filter((chunk: any) => chunk.web)
        .map((chunk: any) => ({
          title: chunk.web.title,
          uri: chunk.web.uri
        }));

      schemes.forEach(s => {
        s.officialSources = sources.slice(0, 3);
      });
    }

    return schemes;
  } catch (error) {
    console.error("Error finding schemes with grounding:", error);
    return [];
  }
};

