const SESSION_KEY = 'health_shield_active_session';
const ACCESS_TIMEOUT_MS = 15 * 60 * 1000; // 15 Minutes

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | 'family' | 'premium' | 'edit_patient' | 'add_treatment_note' | null;
type LoginMethod = 'healthid' | 'phone';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [loginMethod, setLoginMethod] = useState<LoginMethod>('healthid');
  const [roleMode, setRoleMode] = useState<'patient' | 'doctor'>('patient');
  const [loginId, setLoginId] = useState('');
  const [phoneInput, setPhoneInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isAnalyzingRecord, setIsAnalyzingRecord] = useState<string | null>(null);
  const [isSyncingReminders, setIsSyncingReminders] = useState(false);

  // Rate Limiting & OTP States
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);
  const [activeOtp, setActiveOtp] = useState<{ code: string, expiresAt: number } | null>(null);
  const [otpTimeLeft, setOtpTimeLeft] = useState(0);

  // Search History Tab States
  const [historySearchQuery, setHistorySearchQuery] = useState('');
  const [searchedRecord, setSearchedRecord] = useState<HealthRecord | null>(null);
  const [potentialMatches, setPotentialMatches] = useState<HealthRecord[]>([]);
  const [isSearchingHistory, setIsSearchingHistory] = useState(false);
  const [historySearchError, setHistorySearchError] = useState('');

  // Secure Access States for external records
  const [pendingRecord, setPendingRecord] = useState<HealthRecord | null>(null);
  const [isAuthorizing, setIsAuthorizing] = useState(false);
  const [authOtp, setAuthOtp] = useState('');
  const [accessExpiry, setAccessExpiry] = useState<number | null>(null);
  const timerRef = useRef<number | null>(null);
  const lockoutTimerRef = useRef<number | null>(null);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');

  // Registration form state
  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', role: 'patient', isPremium: false,
    notificationSettings: { email: true, sms: true, push: true, sound: true },
    visitingHours: { start: '09:00', end: '17:00', days: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'] }
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
          if (record.profile.role === 'doctor') setRoleMode('doctor');
        }
      }
      setIsLoading(false);
    };
    init();

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      if (lockoutTimerRef.current) clearInterval(lockoutTimerRef.current);
    };
  }, []);

  // Audio Notification Engine
  const playNotificationSound = () => {
    try {
      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const oscillator = audioContext.createOscillator();
      const gainNode = audioContext.createGain();
      oscillator.type = 'sine';
      oscillator.frequency.setValueAtTime(880, audioContext.currentTime);
      oscillator.frequency.exponentialRampToValueAtTime(440, audioContext.currentTime + 0.5);
      gainNode.gain.setValueAtTime(0, audioContext.currentTime);
      gainNode.gain.linearRampToValueAtTime(0.2, audioContext.currentTime + 0.05);
      gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.5);
      oscillator.connect(gainNode);
      gainNode.connect(audioContext.destination);
      oscillator.start();
      oscillator.stop(audioContext.currentTime + 0.5);
    } catch (e) {
      console.warn("Audio Context blocked or unsupported");
    }
  };

  // OTP Timer Logic
  useEffect(() => {
    let interval: number;
    if (activeOtp) {
      interval = setInterval(() => {
        const remaining = Math.max(0, activeOtp.expiresAt - Date.now());
        setOtpTimeLeft(Math.floor(remaining / 1000));
        if (remaining === 0) {
          setActiveOtp(null);
          clearInterval(interval);
        }
      }, 1000) as unknown as number;
    }
    return () => clearInterval(interval);
  }, [activeOtp]);

  const handleSyncReminders = async () => {
    if (!currentUser) return;
    setIsSyncingReminders(true);
    try {
      const newReminders = await generateSmartReminders(currentUser);
      const updatedUser = { ...currentUser, reminders: newReminders };
      setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
      if (currentUser.profile.notificationSettings?.sound) {
        playNotificationSound();
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsSyncingReminders(false);
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const array = new Uint32Array(2);
    crypto.getRandomValues(array);
    const part1 = (array[0] % 9000 + 1000).toString();
    const part2 = (array[1] % 9000 + 1000).toString();
    const prefix = roleMode === 'doctor' ? 'DR' : 'HS';
    const newHealthId = `${prefix}-${part1}-${part2}`;
    const newRecord: HealthRecord = {
      profile: { ...regForm, role: roleMode, healthId: newHealthId },
      problems: [], medications: [], surgeries: [], allergies: [], notes: [], familyHistory: [], interactions: [], accessHistory: [], reminders: []
    };
    await dbService.saveRecord(newRecord);
    setTimeout(() => {
      setCurrentUser(newRecord);
      setIsAuth(true);
      setIsSubmitting(false);
      localStorage.setItem(SESSION_KEY, newHealthId);
    }, 1500);
  };

  const checkLockout = () => {
    if (lockoutUntil && Date.now() < lockoutUntil) {
      const remainingMinutes = Math.ceil((lockoutUntil - Date.now()) / 60000);
      setAuthError(`Too many failed attempts. Try again in ${remainingMinutes} minute(s).`);
      return true;
    }
    return false;
  };

  const handleLoginFailure = () => {
    const newAttempts = loginAttempts + 1;
    setLoginAttempts(newAttempts);
    if (newAttempts >= MAX_LOGIN_ATTEMPTS) {
      const until = Date.now() + LOCKOUT_DURATION_MS;
      setLockoutUntil(until);
      setAuthError(`Too many failed attempts. Locked out for 5 minutes.`);
    } else {
      setAuthError(`Invalid credentials. ${MAX_LOGIN_ATTEMPTS - newAttempts} attempts remaining.`);
    }
    setIsSubmitting(false);
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    if (checkLockout()) return;
    setIsSubmitting(true);
    if (loginMethod === 'phone' && !isVerifyingOtp) {
      const record = await dbService.getRecordByPhone(phoneInput);
      if (record) {
        if (record.profile.role !== roleMode) {
          setAuthError(`The requested account is registered as a ${record.profile.role}.`);
          setIsSubmitting(false);
          return;
        }
        const code = Math.floor(100000 + Math.random() * 900000).toString();
        const expiresAt = Date.now() + OTP_EXPIRY_MS;
        setActiveOtp({ code, expiresAt });
        setTimeout(() => {
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
        }, 1000);
      } else {
        setAuthError('No record found with this phone number.');
        setIsSubmitting(false);
      }
      return;
    }
    let record: HealthRecord | null = null;
    if (loginId.toUpperCase().startsWith('DR-')) setRoleMode('doctor');
    else if (loginId.toUpperCase().startsWith('HS-')) setRoleMode('patient');
    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
      if (!record || record.profile.role !== roleMode) {
        handleLoginFailure();
        return;
      }
    } else {
      if (activeOtp && otpInput === activeOtp.code && Date.now() < activeOtp.expiresAt) {
        record = await dbService.getRecordByPhone(phoneInput);
        setActiveOtp(null);
      } else if (activeOtp && Date.now() >= activeOtp.expiresAt) {
        setAuthError('OTP has expired.');
        setIsSubmitting(false);
        return;
      } else {
        handleLoginFailure();
        return;
      }
    }
    if (record) {
      setTimeout(() => {
        setLoginAttempts(0);
        setLockoutUntil(null);
        setCurrentUser(record);
        setIsAuth(true);
        setIsSubmitting(false);
        localStorage.setItem(SESSION_KEY, record!.profile.healthId);
      }, 1200);
    }
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    setSearchedRecord(null);
    localStorage.removeItem(SESSION_KEY);
    if (timerRef.current) clearInterval(timerRef.current);
  };

  const handleHistorySearch = async () => {
    if (!historySearchQuery.trim()) return;
    setIsSearchingHistory(true);
    setHistorySearchError('');
    setSearchedRecord(null);
    setPotentialMatches([]);
    setPendingRecord(null);
    setIsAuthorizing(false);
    try {
      if (historySearchQuery.toUpperCase().startsWith('HS-') || historySearchQuery.toUpperCase().startsWith('DR-')) {
        const record = await dbService.getRecord(historySearchQuery);
        if (record) {
          triggerAuthorization(record);
          setIsSearchingHistory(false);
          return;
        }
      }
      const results = await dbService.getRecordsByName(historySearchQuery);
      if (results.length === 1) triggerAuthorization(results[0]);
      else if (results.length > 1) setPotentialMatches(results);
      else setHistorySearchError('No matching medical vault identified.');
    } catch (err) {
      setHistorySearchError('System fault.');
    } finally {
      setIsSearchingHistory(false);
    }
  };

  const triggerAuthorization = (record: HealthRecord) => {
    if (currentUser && record.profile.healthId === currentUser.profile.healthId) {
      setSearchedRecord(record);
      return;
    }
    setPendingRecord(record);
    setIsAuthorizing(true);
  };

  const handleVerifyAccess = async () => {
    if (authOtp === '123456') {
      setSearchedRecord(pendingRecord);
      if (currentUser?.profile.role === 'doctor' && pendingRecord) {
        const logEntry: DoctorAccessLog = {
          patientHealthId: pendingRecord.profile.healthId,
          patientName: pendingRecord.profile.name,
          timestamp: Date.now()
        };
        const updatedDoctor = { 
          ...currentUser, 
          accessHistory: [logEntry, ...(currentUser.accessHistory || []).filter(l => l.patientHealthId !== logEntry.patientHealthId)].slice(0, 10) 
        };
        setCurrentUser(updatedDoctor);
        await dbService.saveRecord(updatedDoctor);
      }
      setPendingRecord(null);
      setIsAuthorizing(false);
      setAuthOtp('');
      const expiry = Date.now() + ACCESS_TIMEOUT_MS;
      setAccessExpiry(expiry);
      if (timerRef.current) clearInterval(timerRef.current);
      timerRef.current = setInterval(() => {
        if (Date.now() > expiry) {
          setSearchedRecord(null);
          setAccessExpiry(null);
          if (timerRef.current) clearInterval(timerRef.current);
        }
      }, 1000) as unknown as number;
    } else setHistorySearchError('Invalid authorization token.');
  };

  const updateProfile = async (updates: Partial<UserProfile>) => {
    if (!currentUser) return;
    const updatedUser = { ...currentUser, profile: { ...currentUser.profile, ...updates } };
    setCurrentUser(updatedUser);
    await dbService.saveRecord(updatedUser);
  };

  const addTreatmentNote = async (note: string) => {
    if (!searchedRecord) return;
    const newNote: TreatmentNote = {
      id: Date.now().toString(),
      doctorName: currentUser?.profile.name || 'Dr. System',
      date: new Date().toISOString(),
      note,
      clinicName: currentUser?.profile.role === 'doctor' ? currentUser.profile.specialization : 'General Clinic'
    };
    const updated = { ...searchedRecord, notes: [newNote, ...(searchedRecord.notes || [])] };
    setSearchedRecord(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  // Fix: Added missing addProblem function
  const addProblem = async (problem: MedicalProblem, _unused?: any) => {
    if (!currentUser) return;
    const updated = { ...currentUser, problems: [problem, ...(currentUser.problems || [])] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  // Fix: Added missing addMedication function
  const addMedication = async (medication: Medication, _unused?: any) => {
    if (!currentUser) return;
    const updated = { ...currentUser, medications: [medication, ...(currentUser.medications || [])] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  const runSchemeAnalysis = async (problemId: string) => {
    if (!currentUser) return;
    const problem = currentUser.problems.find(p => p.id === problemId);
    if (!problem) return;
    setIsAnalyzingRecord(problemId);
    try {
      const matchedSchemes = await findApplicableSchemes(problem, currentUser.profile.age);
      const updatedProblems = currentUser.problems.map(p => p.id === problemId ? { ...p, applicableSchemes: matchedSchemes } : p);
      const updatedUser = { ...currentUser, problems: updatedProblems };
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } catch (err) { console.error("Analysis failed:", err); } finally { setIsAnalyzingRecord(null); }
  };

  const handleAskAi = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    try {
      const response = await analyzeHealthRecord(currentUser, userQuery);
      const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
      setChatHistory(prev => [...prev, aiMsg]);
      const updatedUser = { ...currentUser, interactions: [...(currentUser.interactions || []), { id: Date.now().toString(), query: userQuery, response, timestamp: Date.now() }] };
      setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
    } catch (err) { console.error(err); } finally { setIsAiLoading(false); }
  };

  const filteredProblems = useMemo(() => {
    if (!currentUser) return [];
    return currentUser.problems.filter(p => recordFilter === 'present' ? p.status === 'present' : (p.status === 'past' || p.status === 'recovered'));
  }, [currentUser, recordFilter]);

  const remainingAccessTime = useMemo(() => {
    if (!accessExpiry) return null;
    const diff = accessExpiry - Date.now();
    if (diff <= 0) return "Expired";
    const mins = Math.floor(diff / 60000);
    const secs = Math.floor((diff % 60000) / 1000);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  }, [accessExpiry, Date.now()]);

  if (isLoading) return (
    <div className="min-h-screen flex items-center justify-center bg-[#0a0f1d] text-white">
      <div className="text-center">
        <div className="w-20 h-20 border-t-4 border-indigo-500 rounded-full animate-spin mx-auto mb-6"></div>
        <p className="font-black tracking-[0.3em] text-indigo-400 text-sm uppercase">Secure Engine Initializing</p>
      </div>
    </div>
  );

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-[#0a0f1d] overflow-hidden relative">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-600/10 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-emerald-600/10 blur-[120px] rounded-full"></div>
        <div className="w-full max-w-lg animate-pop-in relative z-10">
          <div className="bg-white/[0.03] backdrop-blur-3xl border border-white/10 rounded-[3rem] p-10 auth-card shadow-2xl">
            <div className="text-center mb-10">
              <div className="relative inline-block mb-6">
                <div className="absolute inset-0 bg-indigo-500 blur-2xl opacity-20 animate-pulse"></div>
                <div className="w-20 h-20 bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-3xl flex items-center justify-center text-4xl shadow-2xl relative border border-white/20">
                  {isSubmitting ? <i className="fas fa-circle-notch animate-spin text-white"></i> : ICONS.LOCK}
                </div>
              </div>
              <h1 className="text-3xl font-black text-white tracking-tight">{APP_NAME}</h1>
              <p className="text-indigo-300/60 text-xs font-bold uppercase tracking-widest mt-2">Biometric Health Vault • Secure Auth</p>
            </div>
            <div className="flex bg-white/5 p-1.5 rounded-[1.5rem] mb-6 border border-white/5">
              <button onClick={() => { setAuthMode('login'); setAuthError(''); setIsVerifyingOtp(false); }} className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'login' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20' : 'text-slate-400 hover:text-white'}`}>Login</button>
              <button onClick={() => { setAuthMode('register'); setAuthError(''); }} className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'register' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20' : 'text-slate-400 hover:text-white'}`}>Register</button>
            </div>
            <div className="flex bg-white/5 p-1 rounded-xl mb-8 border border-white/5">
              <button onClick={() => setRoleMode('patient')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${roleMode === 'patient' ? 'bg-indigo-500/20 text-indigo-400' : 'text-slate-500'}`}>Patient</button>
              <button onClick={() => setRoleMode('doctor')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${roleMode === 'doctor' ? 'bg-teal-500/20 text-teal-400' : 'text-slate-500'}`}>Doctor</button>
            </div>
            {authMode === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-6">
                {!isVerifyingOtp && (
                  <div className="flex bg-white/5 p-1 rounded-xl mb-4 border border-white/5">
                    <button type="button" onClick={() => {setLoginMethod('healthid'); setAuthError('');}} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'healthid' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Health ID</button>
                    <button type="button" onClick={() => {setLoginMethod('phone'); setAuthError('');}} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'phone' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Phone Number</button>
                  </div>
                )}
                {loginMethod === 'healthid' ? (
                  <div className="animate-slide-in">
                    <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-indigo-400/80 mb-3">Vault Health ID</label>
                    <div className="relative">
                      <div className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-500/50">{ICONS.HEALTH_ID}</div>
                      <input type="text" placeholder={roleMode === 'doctor' ? "DR-XXXX-XXXX" : "HS-XXXX-XXXX"} disabled={isSubmitting || !!lockoutUntil} className="w-full bg-white/5 border border-white/10 rounded-2xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all placeholder:text-slate-600" value={loginId} onChange={(e) => setLoginId(e.target.value.toUpperCase())} />
                    </div>
                  </div>
                ) : (
                  <div className="animate-slide-in">
                    {!isVerifyingOtp ? (
                      <div>
                        <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-indigo-400/80 mb-3">Linked Phone Number</label>
                        <div className="relative">
                          <div className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-500/50">{ICONS.EMERGENCY}</div>
                          <input type="tel" placeholder="+91 00000 00000" disabled={isSubmitting || !!lockoutUntil} className="w-full bg-white/5 border border-white/10 rounded-2xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all placeholder:text-slate-600" value={phoneInput} onChange={(e) => setPhoneInput(e.target.value)} />
                        </div>
                      </div>
                    ) : (
                      <div className="animate-pop-in">
                        <div className="flex items-center justify-between mb-3">
                          <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-emerald-400">Enter Secure OTP</label>
                          <span className={`text-[10px] font-black uppercase tracking-widest ${otpTimeLeft < 30 ? 'text-red-400 animate-pulse' : 'text-slate-500'}`}>{Math.floor(otpTimeLeft / 60)}:{(otpTimeLeft % 60).toString().padStart(2, '0')}</span>
                        </div>
                        <input type="text" maxLength={6} placeholder="······" autoFocus disabled={isSubmitting || !!lockoutUntil} className="w-full bg-white/5 border border-white/10 rounded-2xl px-4 py-4 text-center text-2xl font-black tracking-[1em] text-white focus:ring-2 focus:ring-emerald-500 outline-none transition-all placeholder:text-slate-800" value={otpInput} onChange={(e) => setOtpInput(e.target.value)} />
                      </div>
                    )}
                  </div>
                )}
                {authError && <p className="text-red-400 text-xs mt-2 font-bold text-center bg-red-400/10 py-2 rounded-lg border border-red-400/20">{authError}</p>}
                <button type="submit" disabled={isSubmitting || !!(lockoutUntil && Date.now() < lockoutUntil)} className={`w-full py-5 rounded-[1.5rem] font-black uppercase tracking-widest transition-all flex items-center justify-center space-x-3 group ${isVerifyingOtp ? 'bg-emerald-600 hover:bg-emerald-500 shadow-emerald-500/20' : 'bg-indigo-600 hover:bg-indigo-500 shadow-indigo-500/20'} shadow-2xl disabled:opacity-50`}>
                  <span className="text-white">{isSubmitting ? 'Authenticating...' : (lockoutUntil && Date.now() < lockoutUntil) ? 'Locked Out' : isVerifyingOtp ? 'Verify OTP' : loginMethod === 'phone' ? 'Request OTP' : 'Open Medical Vault'}</span>
                  {!isSubmitting && <i className={`fas ${isVerifyingOtp ? 'fa-fingerprint' : 'fa-arrow-right'} text-sm group-hover:translate-x-1 transition-transform`}></i>}
                </button>
              </form>
            ) : (
              <form onSubmit={handleRegister} className="space-y-4 animate-slide-in">
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Full Name</label>
                    <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="John Doe" onChange={e => setRegForm({...regForm, name: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Age</label>
                    <input required type="number" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="25" onChange={e => setRegForm({...regForm, age: parseInt(e.target.value)})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Gender</label>
                    <select className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500 appearance-none" onChange={e => setRegForm({...regForm, gender: e.target.value})}>
                      <option className="bg-slate-900">Male</option>
                      <option className="bg-slate-900">Female</option>
                      <option className="bg-slate-900">Other</option>
                    </select>
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Phone Number</label>
                  <input required type="tel" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="+91 99999 99999" onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                </div>
                {roleMode === 'doctor' && (
                  <div className="space-y-4 animate-slide-in">
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">License Number</label>
                        <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="MCI-XXXXX" onChange={e => setRegForm({...regForm, licenseNumber: e.target.value})} />
                      </div>
                      <div>
                        <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Specialization</label>
                        <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Cardiology" onChange={e => setRegForm({...regForm, specialization: e.target.value})} />
                      </div>
                    </div>
                  </div>
                )}
                <button type="submit" disabled={isSubmitting} className="w-full bg-emerald-600 hover:bg-emerald-500 text-white py-5 rounded-2xl font-black uppercase tracking-widest transition-all shadow-xl shadow-emerald-500/20 mt-4 disabled:opacity-50">
                  {isSubmitting ? 'Registering...' : `Initialize ${roleMode === 'doctor' ? 'Professional' : 'Medical'} Vault`}
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile.name || ''} isPremium={currentUser?.profile.isPremium} onLogout={handleLogout}>
      <div className="max-w-7xl mx-auto space-y-8 animate-pop-in pb-20 md:pb-8">
        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-8">
              <div className="relative group">
                <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-[2.5rem] blur opacity-25 group-hover:opacity-40 transition duration-1000"></div>
                <div className="relative bg-indigo-950 rounded-[2.5rem] p-8 text-white overflow-hidden shadow-2xl">
                  <div className="absolute top-0 right-0 p-12 opacity-10 transform scale-150 rotate-12"><i className="fas fa-microchip text-9xl"></i></div>
                  <div className="flex justify-between items-start mb-12">
                    <div>
                      <p className="text-indigo-300 text-[10px] font-black uppercase tracking-widest mb-1">{currentUser?.profile.role === 'doctor' ? 'PRO LICENSE' : 'Universal Health ID'}</p>
                      <h3 className="text-2xl font-bold tracking-tight">{currentUser?.profile.role === 'doctor' && 'Dr. '}{currentUser?.profile.name}</h3>
                      {currentUser?.profile.role === 'doctor' && <p className="text-xs text-indigo-300 font-bold uppercase tracking-widest mt-1">{currentUser.profile.specialization}</p>}
                    </div>
                    <div className="text-right">
                      <p className="text-indigo-300 text-[10px] font-black uppercase tracking-widest mb-1">Status</p>
                      <p className="font-bold">{currentUser?.profile.isPremium ? 'PREMIUM' : 'ACTIVE'}</p>
                    </div>
                  </div>
                  <div className="flex items-end justify-between">
                    <div>
                      <p className="text-indigo-300 text-[10px] font-black uppercase tracking-widest mb-1">System Identification</p>
                      <p className="text-2xl font-mono font-bold tracking-[0.2em]">{currentUser?.profile.healthId}</p>
                    </div>
                    <div className="flex space-x-4 text-xs font-bold">
                      {currentUser?.profile.role === 'patient' && <div className="bg-white/10 px-3 py-1.5 rounded-lg border border-white/5 uppercase tracking-tighter">Blood: {currentUser?.profile.bloodGroup}</div>}
                      <div className="bg-white/10 px-3 py-1.5 rounded-lg border border-white/5 uppercase tracking-tighter">Age: {currentUser?.profile.age}</div>
                    </div>
                  </div>
                </div>
              </div>
              {currentUser?.profile.role === 'doctor' ? (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <RecordCard title="Current Schedule" icon={<i className="fas fa-calendar-check"></i>}>
                     <div className="p-4 bg-indigo-50 rounded-2xl border border-indigo-100">
                        <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">Visiting Hours</p>
                        <div className="flex items-center justify-between">
                           <span className="text-xl font-black text-slate-800 tracking-tight">{currentUser.profile.visitingHours?.start} — {currentUser.profile.visitingHours?.end}</span>
                           <i className="fas fa-clock text-indigo-300"></i>
                        </div>
                        <div className="flex flex-wrap gap-2 mt-4 pt-4 border-t border-indigo-100">
                           {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(day => {
                             const isActive = currentUser.profile.visitingHours?.days.includes(day);
                             return <span key={day} className={`text-[9px] font-black uppercase px-2 py-1 rounded ${isActive ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-400'}`}>{day}</span>;
                           })}
                        </div>
                     </div>
                  </RecordCard>
                  <RecordCard title="Recent Patient Access" icon={ICONS.HISTORY}>
                    <div className="space-y-4">
                      {currentUser?.accessHistory?.length ? currentUser.accessHistory.map((log, i) => (
                        <div key={i} className="flex items-center justify-between p-4 bg-white rounded-2xl border border-slate-100 shadow-sm hover:border-indigo-200 cursor-pointer transition-all" onClick={() => { setHistorySearchQuery(log.patientHealthId); handleHistorySearch(); setActiveTab('history'); }}>
                          <div className="flex items-center space-x-3">
                            <div className="w-10 h-10 rounded-full bg-slate-50 flex items-center justify-center text-indigo-600">{ICONS.USER}</div>
                            <div><p className="font-bold text-slate-800">{log.patientName}</p><p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{log.patientHealthId}</p></div>
                          </div>
                          <div className="text-right"><p className="text-[9px] text-slate-400 font-black uppercase">{new Date(log.timestamp).toLocaleDateString()}</p></div>
                        </div>
                      )) : <p className="text-center text-slate-400 text-xs py-10 italic">No recent lookups recorded.</p>}
                    </div>
                  </RecordCard>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <RecordCard title="Smart Reminders" icon={<i className="fas fa-bell"></i>}>
                    <div className="space-y-4">
                      <div className="space-y-3 max-h-[300px] overflow-y-auto custom-scrollbar pr-2">
                        {currentUser?.reminders?.length ? currentUser.reminders.map(reminder => (
                          <div key={reminder.id} className="p-4 bg-white border border-slate-100 rounded-2xl shadow-sm flex items-center justify-between group hover:border-indigo-200 transition-all">
                            <div className="flex items-center gap-4">
                              <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${reminder.type === 'medication' ? 'bg-blue-50 text-blue-600' : reminder.type === 'followup' ? 'bg-purple-50 text-purple-600' : 'bg-green-50 text-green-600'}`}>
                                {reminder.type === 'medication' ? ICONS.MEDS : reminder.type === 'followup' ? ICONS.SURGERY : <i className="fas fa-heartbeat"></i>}
                              </div>
                              <div><p className="text-sm font-bold text-slate-800">{reminder.title}</p><p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{reminder.time} {reminder.date && `• ${new Date(reminder.date).toLocaleDateString()}`}</p></div>
                            </div>
                            <button className="w-6 h-6 rounded-full border-2 border-slate-200 hover:border-indigo-500 transition-all flex items-center justify-center text-transparent hover:text-indigo-500"><i className="fas fa-check text-[10px]"></i></button>
                          </div>
                        )) : <div className="text-center py-8"><i className="fas fa-magic text-3xl text-indigo-100 mb-3"></i><p className="text-xs text-slate-400 italic">No automated reminders yet. Visit Settings to sync with Shield AI.</p></div>}
                      </div>
                    </div>
                  </RecordCard>
                  <RecordCard title="Active Medications" icon={ICONS.MEDS} onAdd={() => setShowAddModal('medication')}>
                    <div className="space-y-4">
                      {currentUser?.medications.filter(m => m.status === 'active').map(med => (
                        <div key={med.id} className="flex items-center justify-between p-4 bg-white rounded-2xl border border-slate-100 shadow-sm">
                          <div className="flex items-center space-x-3">
                            <div className="text-indigo-600 text-xl">{ICONS.MEDS}</div>
                            <div><p className="font-bold text-slate-800">{med.name}</p><p className="text-xs text-slate-500">{med.dosage} • {med.frequency}</p></div>
                          </div>
                        </div>
                      ))}
                      {currentUser?.medications.filter(m => m.status === 'active').length === 0 && <p className="text-center text-slate-400 text-xs italic">No active medications logged.</p>}
                    </div>
                  </RecordCard>
                </div>
              )}
            </div>
            <div className="space-y-8">
              <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6">Security Protocol</h3>
