import { GoogleGenAI, Type } from "@google/genai";
import { HealthRecord, MedicalProblem, GovernmentScheme, Reminder } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeHealthRecord = async (record: HealthRecord, query: string): Promise<string> => {
  const systemInstruction = `
    You are Shield AI, a professional medical records analyst and healthcare navigator. 
    Analyze the provided health history: ${JSON.stringify(record)}.

    CRITICAL MISSION:
    Identify and suggest specific Indian Government Health Schemes (like Ayushman Bharat - PM-JAY, RSBY, state-specific schemes like CMCHIS in TN or Aarogyasri in Telangana) that the user might be eligible for.

    Guidelines:
    1. DISCLAIMER: "I am Shield AI, a guidance assistant. I am not a substitute for professional medical advice or official government eligibility verification."
    2. Check for drug-drug interactions between ${record.medications.map(m => m.name).join(', ')}.
    3. Use the severity and status of conditions to prioritize advice. Severe/Present conditions need immediate scheme mapping.
    4. Mask sensitive IDs in your response.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: query,
      config: {
        systemInstruction,
        temperature: 0.6,
        thinkingConfig: { thinkingBudget: 4000 }
      },
    });

    return response.text || "I'm sorry, I couldn't process your request.";
  } catch (error) {
    console.error("Gemini AI error:", error);
    return "I encountered an error while analyzing your health data.";
  }
};

export const generateSmartReminders = async (record: HealthRecord): Promise<Reminder[]> => {
  const prompt = `
    Analyze this health record and generate a set of smart reminders:
    Medications: ${JSON.stringify(record.medications)}
    Recent Surgeries: ${JSON.stringify(record.surgeries)}
    Active Problems: ${JSON.stringify(record.problems)}

    TASK:
    1. Create specific medication reminders based on frequency (e.g., "Twice Daily" should result in morning and evening entries).
    2. Create follow-up reminders for recent surgeries (usually 7 days, 15 days, and 30 days post-op).
    3. Suggest lifestyle reminders based on active conditions (e.g., "Check blood sugar" for diabetics).

    Output a JSON array of Reminder objects.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              time: { type: Type.STRING, description: "Format HH:mm" },
              date: { type: Type.STRING, description: "Format YYYY-MM-DD" },
              type: { type: Type.STRING, enum: ['medication', 'followup', 'lifestyle'] },
              status: { type: Type.STRING, enum: ['pending'] }
            },
            required: ["id", "title", "description", "type", "status"]
          }
        }
      }
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Reminder generation failed:", error);
    return [];
  }
};

export const findApplicableSchemes = async (problem: MedicalProblem, userAge: number): Promise<GovernmentScheme[]> => {
  const searchPrompt = `
    Use Google Search to find specific Central and State-specific Indian Government health schemes (e.g. PM-JAY, Aarogyasri, Swasthya Sathi, CMCHIS) applicable to:
    Condition: "${problem.condition}"
    Severity: "${problem.severity}" (Crucial for high-priority schemes)
    Status: "${problem.status}" (e.g., active conditions might qualify for secondary/tertiary care)
    Patient Age: ${userAge}

    Specifically look for schemes that cover specialized treatment for ${problem.severity} cases of ${problem.condition}.
  `;

  try {
    const searchResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: searchPrompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const infoText = searchResponse.text;
    const groundingChunks = searchResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
    const sources = groundingChunks
      ? groundingChunks
          .filter((chunk: any) => chunk.web)
          .map((chunk: any) => ({
            title: chunk.web.title,
            uri: chunk.web.uri
          }))
      : [];

    const parsePrompt = `
      Convert the following information into a JSON array of GovernmentScheme objects.
      Information: ${infoText}

      IMPORTANT: In the 'benefits' field, explicitly mention how this scheme helps with a "${problem.severity}" condition that is currently "${problem.status}".

      Required schema for each object:
      {
        "id": "unique-id",
        "name": "Scheme Name",
        "benefits": "Description of coverage specifically for this case",
        "coverageAmount": "e.g., ₹5 Lakhs",
        "eligibility": "Criteria",
        "matchReason": "Explanation of why this is a good match based on ${problem.severity} severity and ${problem.status} status"
      }
    `;

    const parseResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: parsePrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              name: { type: Type.STRING },
              benefits: { type: Type.STRING },
              coverageAmount: { type: Type.STRING },
              eligibility: { type: Type.STRING },
              matchReason: { type: Type.STRING }
            },
            required: ["id", "name", "benefits", "eligibility", "coverageAmount", "matchReason"]
          }
        }
      }
    });

    const schemes: any[] = JSON.parse(parseResponse.text || "[]");
    return schemes.map(s => ({
      ...s,
      officialSources: sources.slice(0, 3)
    }));
  } catch (error) {
    console.error("Scheme identification failed:", error);
    return [];
  }
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  UserProfile, 
  HealthRecord, 
  ChatMessage, 
  Interaction, 
  MedicalProblem, 
  Medication, 
  Surgery, 
