type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | 'family' | 'premium' | 'edit_patient' | 'add_treatment_note' | 'add_insurance' | null;
type LoginMethod = 'healthid' | 'phone';

const App: React.FC = () => {
