import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  UserProfile, 
  HealthRecord, 
  ChatMessage, 
  Interaction, 
  MedicalProblem, 
  Medication, 
  Surgery, 
  Allergy, 
  TreatmentNote, 
  FamilyHistory,
  GovernmentScheme,
  DoctorAccessLog,
  NotificationSettings,
  VisitingHours,
  Reminder,
  Insurance
} from './types';
import { ICONS, APP_NAME, STORAGE_KEY, MAX_LOGIN_ATTEMPTS, LOCKOUT_DURATION_MS, OTP_EXPIRY_MS } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord, findApplicableSchemes, generateSmartReminders } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';
const ACCESS_TIMEOUT_MS = 15 * 60 * 1000; // 15 Minutes

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | 'family' | 'premium' | 'edit_patient' | 'add_treatment_note' | 'add_insurance' | null;
type LoginMethod = 'healthid' | 'phone';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [loginMethod, setLoginMethod] = useState<LoginMethod>('healthid');
  const [roleMode, setRoleMode] = useState<'patient' | 'doctor'>('patient');
  const [loginId, setLoginId] = useState('');
  const [phoneInput, setPhoneInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isAnalyzingRecord, setIsAnalyzingRecord] = useState<string | null>(null);
  const [isSyncingReminders, setIsSyncingReminders] = useState(false);

  // Enhanced Security States
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);
  const [activeOtp, setActiveOtp] = useState<{ code: string, expiresAt: number } | null>(null);
  const [otpTimeLeft, setOtpTimeLeft] = useState(0);

  // Search History Tab States
  const [historySearchQuery, setHistorySearchQuery] = useState('');
  const [searchedRecord, setSearchedRecord] = useState<HealthRecord | null>(null);
  const [isSearchingHistory, setIsSearchingHistory] = useState(false);
  const [historySearchError, setHistorySearchError] = useState('');

  // Secure Access States
  const [pendingRecord, setPendingRecord] = useState<HealthRecord | null>(null);
  const [isAuthorizing, setIsAuthorizing] = useState(false);
  const [authOtp, setAuthOtp] = useState('');
  const [accessExpiry, setAccessExpiry] = useState<number | null>(null);
  const timerRef = useRef<number | null>(null);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');

  // Registration form state
  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', role: 'patient', isPremium: false,
    notificationSettings: { email: true, sms: true, push: true, sound: true },
    visitingHours: { start: '09:00', end: '17:00', days: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'] }
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
          if (record.profile.role === 'doctor') setRoleMode('doctor');
        }
      }
      setIsLoading(false);
    };
    init();

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);

  // OTP Expiry Countdown
  useEffect(() => {
    let interval: number | undefined;
    if (activeOtp) {
      interval = window.setInterval(() => {
        const remaining = Math.max(0, activeOtp.expiresAt - Date.now());
        setOtpTimeLeft(Math.floor(remaining / 1000));
        if (remaining === 0) {
          setActiveOtp(null);
          setAuthError('OTP has expired. Please request a new one.');
          clearInterval(interval);
        }
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [activeOtp]);

  // Lockout Checker
  useEffect(() => {
    let interval: number | undefined;
    if (lockoutUntil) {
      interval = window.setInterval(() => {
        if (Date.now() >= lockoutUntil) {
          setLockoutUntil(null);
          setLoginAttempts(0);
          setAuthError('');
          clearInterval(interval);
        }
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [lockoutUntil]);

  const handleLoginFailure = () => {
    const newAttempts = loginAttempts + 1;
    setLoginAttempts(newAttempts);
    if (newAttempts >= MAX_LOGIN_ATTEMPTS) {
      setLockoutUntil(Date.now() + LOCKOUT_DURATION_MS);
      setAuthError(`Maximum attempts reached. Locked out for 5 minutes.`);
    } else {
      setAuthError(`Invalid credentials. ${MAX_LOGIN_ATTEMPTS - newAttempts} attempts remaining.`);
    }
    setIsSubmitting(false);
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (lockoutUntil && Date.now() < lockoutUntil) return;

    setAuthError('');
    setIsSubmitting(true);
    let record: HealthRecord | null = null;

    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
      if (!record) {
        handleLoginFailure();
        return;
      }
    } else {
      // Phone Method
      if (!isVerifyingOtp) {
        record = await dbService.getRecordByPhone(phoneInput);
        if (record) {
          // Generate secure 6-digit random code
          const code = Math.floor(100000 + Math.random() * 900000).toString();
          console.log(`[SECURE DEBUG] OTP for ${phoneInput}: ${code}`);
          setActiveOtp({ code, expiresAt: Date.now() + OTP_EXPIRY_MS });
          setOtpTimeLeft(OTP_EXPIRY_MS / 1000);
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
        } else {
          handleLoginFailure();
        }
        return;
      } else {
        // Validating OTP
        if (activeOtp && otpInput === activeOtp.code && Date.now() < activeOtp.expiresAt) {
          record = await dbService.getRecordByPhone(phoneInput);
          setActiveOtp(null);
        } else {
          handleLoginFailure();
          return;
        }
      }
    }

    if (record) {
      setLoginAttempts(0);
      setCurrentUser(record);
      setIsAuth(true);
      setIsSubmitting(false);
      localStorage.setItem(SESSION_KEY, record.profile.healthId);
    }
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    setSearchedRecord(null);
    localStorage.removeItem(SESSION_KEY);
  };

  const addInsurance = async (insurance: Insurance) => {
    if (!currentUser) return;
    const updated = { ...currentUser, insurances: [insurance, ...(currentUser.insurances || [])] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  const addProblem = async (problem: MedicalProblem) => {
    if (!currentUser) return;
    const updated = { ...currentUser, problems: [problem, ...(currentUser.problems || [])] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  const runSchemeAnalysis = async (problemId: string) => {
    if (!currentUser) return;
    const problem = currentUser.problems.find(p => p.id === problemId);
    if (!problem) return;
    setIsAnalyzingRecord(problemId);
    try {
      const matchedSchemes = await findApplicableSchemes(problem, currentUser.profile.age);
      const updatedProblems = currentUser.problems.map(p => p.id === problemId ? { ...p, applicableSchemes: matchedSchemes } : p);
      const updatedUser = { ...currentUser, problems: updatedProblems };
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } catch (err) {
      console.error("Analysis failed:", err);
    } finally {
      setIsAnalyzingRecord(null);
    }
  };

  const handleAskAi = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    try {
      const response = await analyzeHealthRecord(currentUser, userQuery);
      const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
      setChatHistory(prev => [...prev, aiMsg]);
    } catch (err) { console.error(err); } finally { setIsAiLoading(false); }
  };

  const filteredProblems = useMemo(() => {
    if (!currentUser) return [];
    return currentUser.problems.filter(p => recordFilter === 'present' ? p.status === 'present' : (p.status === 'past' || p.status === 'recovered'));
  }, [currentUser, recordFilter]);

  if (isLoading) return <div className="min-h-screen flex items-center justify-center bg-[#0a0f1d] text-white">Loading Secure Vault...</div>;

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-[#0a0f1d] overflow-hidden relative">
        <div className="w-full max-w-lg animate-pop-in relative z-10">
          <div className="bg-white/[0.03] backdrop-blur-3xl border border-white/10 rounded-[3rem] p-10 auth-card shadow-2xl relative">
            {lockoutUntil && (
              <div className="absolute inset-0 bg-slate-900/90 z-50 rounded-[3rem] flex flex-col items-center justify-center p-10 text-center backdrop-blur-sm">
                <i className="fas fa-user-lock text-5xl text-red-500 mb-6"></i>
                <h2 className="text-2xl font-black text-white mb-2 uppercase tracking-tight">Security Lockout</h2>
                <p className="text-slate-400 text-sm mb-6 leading-relaxed">Multiple failed attempts detected. Access is restricted for security. Please wait before trying again.</p>
                <div className="px-6 py-3 bg-red-500/10 border border-red-500/20 rounded-2xl text-red-400 font-mono text-xl">
                  {Math.floor((lockoutUntil - Date.now()) / 60000)}m {Math.floor(((lockoutUntil - Date.now()) % 60000) / 1000)}s
                </div>
              </div>
            )}

            <div className="text-center mb-10">
              <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center text-4xl mx-auto mb-6 shadow-2xl">
                {ICONS.LOCK}
              </div>
              <h1 className="text-3xl font-black text-white tracking-tight">{APP_NAME}</h1>
            </div>

            <div className="flex bg-white/5 p-1.5 rounded-[1.5rem] mb-8 border border-white/5">
              <button onClick={() => { setAuthMode('login'); setAuthError(''); setIsVerifyingOtp(false); }} className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'login' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>Login</button>
              <button onClick={() => { setAuthMode('register'); setAuthError(''); }} className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'register' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>Register</button>
            </div>

            {authMode === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-6">
                <div className="flex bg-white/5 p-1 rounded-xl mb-4 border border-white/5">
                  <button type="button" onClick={() => {setLoginMethod('healthid'); setAuthError(''); setIsVerifyingOtp(false);}} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'healthid' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Health ID</button>
                  <button type="button" onClick={() => {setLoginMethod('phone'); setAuthError(''); setIsVerifyingOtp(false);}} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'phone' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Phone Number</button>
                </div>

                {loginMethod === 'healthid' ? (
                  <input type="text" placeholder="HS-XXXX-XXXX" className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:ring-2 focus:ring-indigo-500 uppercase font-mono" value={loginId} onChange={(e) => setLoginId(e.target.value)} />
                ) : (
                  <div className="space-y-4">
                    {!isVerifyingOtp ? (
                      <input type="tel" placeholder="+91 9XXXX XXXXX" className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:ring-2 focus:ring-indigo-500" value={phoneInput} onChange={(e) => setPhoneInput(e.target.value)} />
                    ) : (
                      <div className="animate-pop-in">
                        <div className="flex justify-between items-center mb-2">
                          <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Verify Secure OTP</label>
                          <span className={`text-[10px] font-mono ${otpTimeLeft < 30 ? 'text-red-400' : 'text-indigo-300'}`}>
                            {Math.floor(otpTimeLeft / 60)}:{(otpTimeLeft % 60).toString().padStart(2, '0')}
                          </span>
                        </div>
                        <input type="text" maxLength={6} placeholder="······" autoFocus className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-center text-3xl font-black tracking-[0.5em] text-white outline-none focus:ring-2 focus:ring-emerald-500" value={otpInput} onChange={(e) => setOtpInput(e.target.value)} />
                      </div>
                    )}
                  </div>
                )}

                {authError && <p className="text-red-400 text-xs font-bold text-center bg-red-400/10 py-3 rounded-xl border border-red-400/20">{authError}</p>}

                <button type="submit" disabled={isSubmitting || (isVerifyingOtp && otpTimeLeft <= 0)} className={`w-full py-5 rounded-2xl font-black uppercase tracking-widest transition-all shadow-xl disabled:opacity-50 ${isVerifyingOtp ? 'bg-emerald-600 hover:bg-emerald-500 shadow-emerald-600/20' : 'bg-indigo-600 hover:bg-indigo-500 shadow-indigo-600/20'}`}>
                  {isSubmitting ? 'Verifying...' : isVerifyingOtp ? 'Grant Vault Access' : 'Secure Entry'}
                </button>
              </form>
            ) : (
              <form onSubmit={handleRegister} className="space-y-4">
                 <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Full Name</label>
                    <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="John Doe" onChange={e => setRegForm({...regForm, name: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Age</label>
                    <input required type="number" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="25" onChange={e => setRegForm({...regForm, age: parseInt(e.target.value)})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Gender</label>
                    <select className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500 appearance-none" onChange={e => setRegForm({...regForm, gender: e.target.value})}>
                      <option className="bg-slate-900">Male</option>
                      <option className="bg-slate-900">Female</option>
                      <option className="bg-slate-900">Other</option>
                    </select>
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Phone Number</label>
                  <input required type="tel" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="+91 99999 99999" onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                </div>
                <button type="submit" disabled={isSubmitting} className="w-full bg-emerald-600 hover:bg-emerald-500 text-white py-5 rounded-2xl font-black uppercase tracking-widest transition-all shadow-xl shadow-emerald-500/20 mt-4 disabled:opacity-50">
                  Initialize Health Vault
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile.name || ''} isPremium={currentUser?.profile.isPremium} onLogout={handleLogout}>
      <div className="max-w-7xl mx-auto space-y-8 animate-pop-in pb-20 md:pb-8">
        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-8">
              <div className="bg-indigo-950 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-12 opacity-5"><i className="fas fa-microchip text-9xl"></i></div>
                <div className="flex justify-between items-start mb-12">
                  <div>
                    <p className="text-indigo-300 text-[10px] font-black uppercase tracking-widest">Universal Health ID</p>
                    <h3 className="text-3xl font-bold tracking-tight">{currentUser?.profile.name}</h3>
                  </div>
                  <div className="text-right"><p className="text-3xl font-mono font-bold">{currentUser?.profile.healthId}</p></div>
                </div>
                <div className="flex gap-4">
                   <div className="bg-white/10 px-4 py-2 rounded-xl text-xs font-bold uppercase">Blood: {currentUser?.profile.bloodGroup}</div>
                   <div className="bg-white/10 px-4 py-2 rounded-xl text-xs font-bold uppercase">Age: {currentUser?.profile.age}</div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <RecordCard title="Smart Reminders" icon={<i className="fas fa-bell"></i>}>
                  <div className="space-y-4">
                    {currentUser?.reminders?.slice(0, 3).map(r => (
                      <div key={r.id} className="p-4 bg-white border border-slate-100 rounded-2xl flex justify-between">
                        <div><p className="font-bold text-slate-800">{r.title}</p><p className="text-[10px] uppercase font-bold text-slate-400">{r.time}</p></div>
                        <i className="fas fa-clock text-indigo-300"></i>
                      </div>
                    ))}
                    <button onClick={handleSyncReminders} className="w-full py-3 bg-indigo-50 text-indigo-600 rounded-xl text-[10px] font-black uppercase tracking-widest">Sync AI Schedule</button>
                  </div>
                </RecordCard>

                <RecordCard title="Private Insurance" icon={ICONS.CREDIT_CARD} onAdd={() => setShowAddModal('add_insurance')}>
                  <div className="space-y-4">
                    {currentUser?.insurances?.map(ins => (
                      <div key={ins.id} className="p-5 bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-2xl text-white shadow-lg relative group">
                        <div className="flex justify-between items-start mb-2">
                           <p className="text-[10px] font-black uppercase tracking-widest text-indigo-200">{ins.provider}</p>
                           <span className="text-[8px] font-black uppercase px-2 py-0.5 bg-emerald-500/20 text-emerald-300 rounded-full">{ins.status}</span>
                        </div>
                        <p className="font-bold text-lg">₹{ins.coverageAmount}</p>
                        <p className="text-[9px] font-mono opacity-60 mt-2">{ins.policyNumber}</p>
                      </div>
                    ))}
                    {!currentUser?.insurances?.length && <p className="text-center text-slate-400 italic py-8">No insurance logged.</p>}
                  </div>
                </RecordCard>
              </div>
            </div>

            <div className="space-y-8">
               <div className="bg-white rounded-[2.5rem] p-8 border border-slate-100 shadow-sm">
                  <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6">Vault Health Metrics</h3>
                  <div className="space-y-6">
                    <div className="flex items-center justify-between"><span className="text-sm font-bold text-slate-800">Records Secure</span><span className="text-emerald-500 font-black">100%</span></div>
                    <div className="flex items-center justify-between"><span className="text-sm font-bold text-slate-800">AI Sync Status</span><span className="text-indigo-500 font-black">Stable</span></div>
                  </div>
               </div>
            </div>
          </div>
        )}

        {activeTab === 'schemes' && (
          <div className="max-w-7xl mx-auto space-y-12 pb-24">
            <div className="bg-indigo-950 p-12 rounded-[3.5rem] text-white relative overflow-hidden group shadow-2xl">
              <div className="absolute top-0 right-0 p-12 opacity-[0.05] group-hover:rotate-12 transition-transform duration-700"><i className="fas fa-landmark text-9xl"></i></div>
              <div className="relative z-10 max-w-2xl">
                <h3 className="text-4xl font-black tracking-tight mb-4">Welfare Discovery Hub</h3>
                <p className="text-indigo-200 text-lg leading-relaxed opacity-80">Tailored Indian health schemes discovered through Shield AI based on your unique clinical severity and status.</p>
                <div className="mt-8 flex items-center gap-3">
                   <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse"></div>
                   <span className="text-[10px] font-black uppercase tracking-widest">Grounding Search Active</span>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-8">
                {currentUser?.problems.filter(p => p.applicableSchemes?.length).map(p => (
                   <div key={p.id} className="space-y-6 animate-pop-in">
                      <div className="flex items-center gap-3 px-4">
                         <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Condition:</span>
                         <span className="text-sm font-bold text-slate-800 uppercase">{p.condition}</span>
                         <span className={`text-[8px] font-black px-2 py-0.5 rounded-full ${p.severity === 'severe' ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                           {p.severity} Match Required
                         </span>
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {p.applicableSchemes?.map(s => (
                          <div key={s.id} className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all group">
                             <div className="flex justify-between items-start mb-6">
                                <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white transition-all duration-500 shadow-sm">{ICONS.SCHEME}</div>
                                <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full">{s.coverageAmount}</span>
                             </div>
                             <h5 className="text-lg font-black text-slate-800 mb-2 uppercase tracking-tight leading-tight">{s.name}</h5>
                             <p className="text-xs text-slate-500 leading-relaxed font-medium italic mb-6">"{s.benefits}"</p>

                             <div className="pt-6 border-t border-slate-50 space-y-4">
                                <div className="p-4 bg-indigo-50/50 rounded-2xl">
                                   <p className="text-[9px] font-black uppercase text-indigo-600 mb-1">AI Match Insight:</p>
                                   <p className="text-[10px] text-slate-600 leading-relaxed">{s.matchReason || `Recommended for active ${p.condition} cases.`}</p>
                                </div>
                                <div className="flex flex-wrap gap-2">
                                  {s.officialSources?.map((src, idx) => (
                                    <a key={idx} href={src.uri} target="_blank" rel="noopener noreferrer" className="px-3 py-1.5 bg-slate-100 rounded-lg text-[9px] font-bold text-slate-600 hover:bg-indigo-600 hover:text-white transition-all truncate max-w-[140px]"><i className="fas fa-link mr-1 opacity-50"></i> Source</a>
                                  ))}
                                </div>
                             </div>
                          </div>
                        ))}
                      </div>
                   </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'records' && (
          <div className="space-y-12 pb-24">
             <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
              <h3 className="text-2xl font-black text-slate-800 tracking-tight">Personal Medical Archive</h3>
              <div className="flex bg-slate-100 p-1.5 rounded-2xl w-fit border border-slate-200/50">
                <button onClick={() => setRecordFilter('present')} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.15em] transition-all ${recordFilter === 'present' ? 'bg-white text-indigo-600 shadow-lg' : 'text-slate-500 hover:text-slate-700'}`}>Active</button>
                <button onClick={() => setRecordFilter('past')} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.15em] transition-all ${recordFilter === 'past' ? 'bg-white text-indigo-600 shadow-lg' : 'text-slate-500 hover:text-slate-700'}`}>History</button>
              </div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
               <RecordCard title="Medical Conditions" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
                  <div className="space-y-6">
                    {filteredProblems.map(p => (
                       <div key={p.id} className="p-8 rounded-[2.5rem] bg-white border border-slate-100 shadow-sm relative overflow-hidden">
                          <h4 className="text-xl font-black text-slate-800 leading-tight mb-2">{p.condition}</h4>
                          <div className="flex items-center gap-3 mb-6">
                             <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-full ${p.severity === 'severe' ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>{p.severity} Severity</span>
                             <span className="text-[8px] font-black uppercase px-2 py-0.5 bg-slate-100 text-slate-500 rounded-full">{p.status}</span>
                          </div>
                          <button onClick={() => runSchemeAnalysis(p.id)} disabled={isAnalyzingRecord === p.id} className="w-full py-4 border-2 border-dashed border-slate-200 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-400 hover:border-indigo-500 hover:text-indigo-600 hover:bg-indigo-50 transition-all flex items-center justify-center gap-2">
                             {isAnalyzingRecord === p.id ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-magic"></i>}
                             {isAnalyzingRecord === p.id ? 'Tapping Welfare API...' : (p.applicableSchemes?.length ? 'Re-run AI Analysis' : 'Identify Govt Benefits')}
                          </button>
                       </div>
                    ))}
                  </div>
               </RecordCard>
            </div>
          </div>
        )}
      </div>

      {showAddModal === 'add_insurance' && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[4rem] w-full max-w-2xl p-12 animate-pop-in relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 w-12 h-12 rounded-full bg-slate-50 text-slate-400 hover:text-slate-800 transition-all text-2xl">&times;</button>
            <h3 className="text-3xl font-black text-slate-800 tracking-tight mb-8">Archive Private Insurance</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const formData = new FormData(e.currentTarget);
              addInsurance({
                id: Date.now().toString(),
                provider: formData.get('provider') as string,
                policyNumber: formData.get('policyNumber') as string,
                coverageAmount: formData.get('coverageAmount') as string,
                expiryDate: formData.get('expiryDate') as string,
                policyType: formData.get('policyType') as any,
                contactPhone: formData.get('contactPhone') as string,
                status: 'active'
              });
            }} className="grid grid-cols-1 sm:grid-cols-2 gap-8">
              <div className="sm:col-span-2"><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Provider</label><input name="provider" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none" /></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Policy No.</label><input name="policyNumber" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none" /></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Coverage (INR)</label><input name="coverageAmount" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none" /></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Expiry</label><input name="expiryDate" type="date" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none" /></div>
              <button type="submit" className="sm:col-span-2 w-full bg-indigo-600 text-white py-8 rounded-[2.5rem] font-black uppercase tracking-[0.3em] transition-all">Archive Insurance</button>
            </form>
          </div>
        </div>
      )}

      {showAddModal === 'problem' && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[4rem] w-full max-w-2xl p-12 animate-pop-in relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 w-12 h-12 rounded-full bg-slate-50 text-slate-400 hover:text-slate-800 transition-all text-2xl">&times;</button>
            <h3 className="text-3xl font-black text-slate-800 tracking-tight mb-8">Condition Registry</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const formData = new FormData(e.currentTarget);
              addProblem({
                id: Date.now().toString(),
                condition: formData.get('condition') as string,
                status: 'present',
                severity: formData.get('severity') as any,
                onsetDate: new Date().toISOString()
              });
            }} className="grid grid-cols-1 sm:grid-cols-2 gap-8">
              <div className="sm:col-span-2"><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Descriptor</label><input name="condition" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none" /></div>
              <div className="sm:col-span-2"><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Severity</label><select name="severity" className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none"><option value="mild">Mild</option><option value="moderate">Moderate</option><option value="severe">Severe</option></select></div>
              <button type="submit" className="sm:col-span-2 w-full bg-indigo-600 text-white py-8 rounded-[2.5rem] font-black uppercase tracking-[0.3em] transition-all">Archive Condition</button>
            </form>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  UserProfile, 
  HealthRecord, 
  ChatMessage, 
  Interaction, 
  MedicalProblem, 
  Medication, 
  Surgery, 
  Allergy, 
  TreatmentNote, 
  FamilyHistory,
  GovernmentScheme,
  DoctorAccessLog,
  NotificationSettings,
  VisitingHours,
  Reminder,
  Insurance
} from './types';
import { ICONS, APP_NAME, STORAGE_KEY, MAX_LOGIN_ATTEMPTS, LOCKOUT_DURATION_MS, OTP_EXPIRY_MS } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord, findApplicableSchemes, generateSmartReminders } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';
const ACCESS_TIMEOUT_MS = 15 * 60 * 1000; // 15 Minutes

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | 'family' | 'premium' | 'edit_patient' | 'add_treatment_note' | 'add_insurance' | null;
type LoginMethod = 'healthid' | 'phone';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [loginMethod, setLoginMethod] = useState<LoginMethod>('healthid');
  const [roleMode, setRoleMode] = useState<'patient' | 'doctor'>('patient');
  const [loginId, setLoginId] = useState('');
  const [phoneInput, setPhoneInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isAnalyzingRecord, setIsAnalyzingRecord] = useState<string | null>(null);
  const [isSyncingReminders, setIsSyncingReminders] = useState(false);

  // Enhanced Security States
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);
  const [activeOtp, setActiveOtp] = useState<{ code: string, expiresAt: number } | null>(null);
  const [otpTimeLeft, setOtpTimeLeft] = useState(0);

  // Search History Tab States
  const [historySearchQuery, setHistorySearchQuery] = useState('');
  const [searchedRecord, setSearchedRecord] = useState<HealthRecord | null>(null);
  const [isSearchingHistory, setIsSearchingHistory] = useState(false);
  const [historySearchError, setHistorySearchError] = useState('');

  // Secure Access States
  const [pendingRecord, setPendingRecord] = useState<HealthRecord | null>(null);
  const [isAuthorizing, setIsAuthorizing] = useState(false);
  const [authOtp, setAuthOtp] = useState('');
  const [accessExpiry, setAccessExpiry] = useState<number | null>(null);
  const timerRef = useRef<number | null>(null);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');

  // Registration form state
  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', role: 'patient', isPremium: false,
    notificationSettings: { email: true, sms: true, push: true, sound: true },
    visitingHours: { start: '09:00', end: '17:00', days: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'] }
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
          if (record.profile.role === 'doctor') setRoleMode('doctor');
        }
      }
      setIsLoading(false);
    };
    init();

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);

  // OTP Expiry Countdown
  useEffect(() => {
    let interval: number | undefined;
    if (activeOtp) {
      interval = window.setInterval(() => {
        const remaining = Math.max(0, activeOtp.expiresAt - Date.now());
        setOtpTimeLeft(Math.floor(remaining / 1000));
        if (remaining === 0) {
          setActiveOtp(null);
          setAuthError('OTP has expired. Please request a new one.');
          clearInterval(interval);
        }
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [activeOtp]);

  // Lockout Checker
  useEffect(() => {
    let interval: number | undefined;
    if (lockoutUntil) {
      interval = window.setInterval(() => {
        if (Date.now() >= lockoutUntil) {
          setLockoutUntil(null);
          setLoginAttempts(0);
          setAuthError('');
          clearInterval(interval);
        }
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [lockoutUntil]);

  const handleLoginFailure = () => {
    const newAttempts = loginAttempts + 1;
    setLoginAttempts(newAttempts);
    if (newAttempts >= MAX_LOGIN_ATTEMPTS) {
      setLockoutUntil(Date.now() + LOCKOUT_DURATION_MS);
      setAuthError(`Maximum attempts reached. Locked out for 5 minutes.`);
    } else {
      setAuthError(`Invalid credentials. ${MAX_LOGIN_ATTEMPTS - newAttempts} attempts remaining.`);
    }
    setIsSubmitting(false);
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (lockoutUntil && Date.now() < lockoutUntil) return;

    setAuthError('');
    setIsSubmitting(true);
    let record: HealthRecord | null = null;

    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
      if (!record) {
        handleLoginFailure();
        return;
      }
    } else {
      // Phone Method
      if (!isVerifyingOtp) {
        record = await dbService.getRecordByPhone(phoneInput);
        if (record) {
          // Generate secure 6-digit random code
          const code = Math.floor(100000 + Math.random() * 900000).toString();
          console.log(`[SECURE DEBUG] OTP for ${phoneInput}: ${code}`);
          setActiveOtp({ code, expiresAt: Date.now() + OTP_EXPIRY_MS });
          setOtpTimeLeft(OTP_EXPIRY_MS / 1000);
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
        } else {
          handleLoginFailure();
        }
        return;
      } else {
        // Validating OTP
        if (activeOtp && otpInput === activeOtp.code && Date.now() < activeOtp.expiresAt) {
          record = await dbService.getRecordByPhone(phoneInput);
          setActiveOtp(null);
        } else {
          handleLoginFailure();
          return;
        }
      }
    }

    if (record) {
      setLoginAttempts(0);
      setCurrentUser(record);
      setIsAuth(true);
      setIsSubmitting(false);
      localStorage.setItem(SESSION_KEY, record.profile.healthId);
    }
  };

  // Fix for line 323: Implement handleRegister
  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setAuthError('');

    const randomStr = Math.random().toString(36).substring(2, 6).toUpperCase();
    const randomNum = Math.floor(1000 + Math.random() * 9000);
    const healthId = `HS-${randomStr}-${randomNum}`;

    const newRecord: HealthRecord = {
      profile: {
        ...regForm,
        healthId,
        role: 'patient',
        isPremium: false,
      },
      problems: [],
      medications: [],
      surgeries: [],
      allergies: [],
      notes: [],
      familyHistory: [],
      insurances: [],
      reminders: [],
      interactions: [],
      accessHistory: []
    };

    try {
      await dbService.saveRecord(newRecord);
      setCurrentUser(newRecord);
      setIsAuth(true);
      localStorage.setItem(SESSION_KEY, healthId);
    } catch (error) {
      setAuthError("Failed to initialize health vault. Please try again.");
      console.error(error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    setSearchedRecord(null);
    localStorage.removeItem(SESSION_KEY);
  };

  const addInsurance = async (insurance: Insurance) => {
    if (!currentUser) return;
    const updated = { ...currentUser, insurances: [insurance, ...(currentUser.insurances || [])] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  const addProblem = async (problem: MedicalProblem) => {
    if (!currentUser) return;
    const updated = { ...currentUser, problems: [problem, ...(currentUser.problems || [])] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  const runSchemeAnalysis = async (problemId: string) => {
    if (!currentUser) return;
    const problem = currentUser.problems.find(p => p.id === problemId);
    if (!problem) return;
    setIsAnalyzingRecord(problemId);
    try {
      const matchedSchemes = await findApplicableSchemes(problem, currentUser.profile.age);
      const updatedProblems = currentUser.problems.map(p => p.id === problemId ? { ...p, applicableSchemes: matchedSchemes } : p);
      const updatedUser = { ...currentUser, problems: updatedProblems };
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } catch (err) {
      console.error("Analysis failed:", err);
    } finally {
      setIsAnalyzingRecord(null);
    }
  };

  const handleAskAi = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    try {
      const response = await analyzeHealthRecord(currentUser, userQuery);
      const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
      setChatHistory(prev => [...prev, aiMsg]);
    } catch (err) { console.error(err); } finally { setIsAiLoading(false); }
  };

  // Fix for line 387: Implement handleSyncReminders
  const handleSyncReminders = async () => {
    if (!currentUser) return;
    setIsSyncingReminders(true);
    try {
      const reminders = await generateSmartReminders(currentUser);
      const updated = { ...currentUser, reminders };
      setCurrentUser(updated);
      await dbService.saveRecord(updated);
    } catch (err) {
      console.error("Failed to sync reminders:", err);
    } finally {
      setIsSyncingReminders(false);
    }
  };

  const filteredProblems = useMemo(() => {
    if (!currentUser) return [];
    return currentUser.problems.filter(p => recordFilter === 'present' ? p.status === 'present' : (p.status === 'past' || p.status === 'recovered'));
  }, [currentUser, recordFilter]);

  if (isLoading) return <div className="min-h-screen flex items-center justify-center bg-[#0a0f1d] text-white">Loading Secure Vault...</div>;

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-[#0a0f1d] overflow-hidden relative">
        <div className="w-full max-w-lg animate-pop-in relative z-10">
          <div className="bg-white/[0.03] backdrop-blur-3xl border border-white/10 rounded-[3rem] p-10 auth-card shadow-2xl relative">
            {lockoutUntil && (
              <div className="absolute inset-0 bg-slate-900/90 z-50 rounded-[3rem] flex flex-col items-center justify-center p-10 text-center backdrop-blur-sm">
                <i className="fas fa-user-lock text-5xl text-red-500 mb-6"></i>
                <h2 className="text-2xl font-black text-white mb-2 uppercase tracking-tight">Security Lockout</h2>
                <p className="text-slate-400 text-sm mb-6 leading-relaxed">Multiple failed attempts detected. Access is restricted for security. Please wait before trying again.</p>
                <div className="px-6 py-3 bg-red-500/10 border border-red-500/20 rounded-2xl text-red-400 font-mono text-xl">
                  {Math.floor((lockoutUntil - Date.now()) / 60000)}m {Math.floor(((lockoutUntil - Date.now()) % 60000) / 1000)}s
                </div>
              </div>
            )}

            <div className="text-center mb-10">
              <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center text-4xl mx-auto mb-6 shadow-2xl">
                {ICONS.LOCK}
              </div>
              <h1 className="text-3xl font-black text-white tracking-tight">{APP_NAME}</h1>
            </div>

            <div className="flex bg-white/5 p-1.5 rounded-[1.5rem] mb-8 border border-white/5">
              <button onClick={() => { setAuthMode('login'); setAuthError(''); setIsVerifyingOtp(false); }} className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'login' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>Login</button>
              <button onClick={() => { setAuthMode('register'); setAuthError(''); }} className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'register' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>Register</button>
            </div>

            {authMode === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-6">
                <div className="flex bg-white/5 p-1 rounded-xl mb-4 border border-white/5">
                  <button type="button" onClick={() => {setLoginMethod('healthid'); setAuthError(''); setIsVerifyingOtp(false);}} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'healthid' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Health ID</button>
                  <button type="button" onClick={() => {setLoginMethod('phone'); setAuthError(''); setIsVerifyingOtp(false);}} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'phone' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Phone Number</button>
                </div>

                {loginMethod === 'healthid' ? (
                  <input type="text" placeholder="HS-XXXX-XXXX" className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:ring-2 focus:ring-indigo-500 uppercase font-mono" value={loginId} onChange={(e) => setLoginId(e.target.value)} />
                ) : (
                  <div className="space-y-4">
                    {!isVerifyingOtp ? (
                      <input type="tel" placeholder="+91 9XXXX XXXXX" className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:ring-2 focus:ring-indigo-500" value={phoneInput} onChange={(e) => setPhoneInput(e.target.value)} />
                    ) : (
                      <div className="animate-pop-in">
                        <div className="flex justify-between items-center mb-2">
                          <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Verify Secure OTP</label>
                          <span className={`text-[10px] font-mono ${otpTimeLeft < 30 ? 'text-red-400' : 'text-indigo-300'}`}>
                            {Math.floor(otpTimeLeft / 60)}:{(otpTimeLeft % 60).toString().padStart(2, '0')}
                          </span>
                        </div>
                        <input type="text" maxLength={6} placeholder="······" autoFocus className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-center text-3xl font-black tracking-[0.5em] text-white outline-none focus:ring-2 focus:ring-emerald-500" value={otpInput} onChange={(e) => setOtpInput(e.target.value)} />
                      </div>
                    )}
                  </div>
                )}

                {authError && <p className="text-red-400 text-xs font-bold text-center bg-red-400/10 py-3 rounded-xl border border-red-400/20">{authError}</p>}

                <button type="submit" disabled={isSubmitting || (isVerifyingOtp && otpTimeLeft <= 0)} className={`w-full py-5 rounded-2xl font-black uppercase tracking-widest transition-all shadow-xl disabled:opacity-50 ${isVerifyingOtp ? 'bg-emerald-600 hover:bg-emerald-500 shadow-emerald-600/20' : 'bg-indigo-600 hover:bg-indigo-500 shadow-indigo-600/20'}`}>
                  {isSubmitting ? 'Verifying...' : isVerifyingOtp ? 'Grant Vault Access' : 'Secure Entry'}
                </button>
              </form>
            ) : (
              <form onSubmit={handleRegister} className="space-y-4">
                 <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Full Name</label>
                    <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="John Doe" onChange={e => setRegForm({...regForm, name: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Age</label>
                    <input required type="number" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="25" onChange={e => setRegForm({...regForm, age: parseInt(e.target.value)})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Gender</label>
                    <select className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500 appearance-none" onChange={e => setRegForm({...regForm, gender: e.target.value})}>
                      <option className="bg-slate-900">Male</option>
                      <option className="bg-slate-900">Female</option>
                      <option className="bg-slate-900">Other</option>
                    </select>
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Phone Number</label>
                  <input required type="tel" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="+91 99999 99999" onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                </div>
                <button type="submit" disabled={isSubmitting} className="w-full bg-emerald-600 hover:bg-emerald-500 text-white py-5 rounded-2xl font-black uppercase tracking-widest transition-all shadow-xl shadow-emerald-500/20 mt-4 disabled:opacity-50">
                  Initialize Health Vault
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile.name || ''} isPremium={currentUser?.profile.isPremium} onLogout={handleLogout}>
      <div className="max-w-7xl mx-auto space-y-8 animate-pop-in pb-20 md:pb-8">
        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-8">
              <div className="bg-indigo-950 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-12 opacity-5"><i className="fas fa-microchip text-9xl"></i></div>
                <div className="flex justify-between items-start mb-12">
                  <div>
                    <p className="text-indigo-300 text-[10px] font-black uppercase tracking-widest">Universal Health ID</p>
                    <h3 className="text-3xl font-bold tracking-tight">{currentUser?.profile.name}</h3>
                  </div>
                  <div className="text-right"><p className="text-3xl font-mono font-bold">{currentUser?.profile.healthId}</p></div>
                </div>
                <div className="flex gap-4">
                   <div className="bg-white/10 px-4 py-2 rounded-xl text-xs font-bold uppercase">Blood: {currentUser?.profile.bloodGroup}</div>
                   <div className="bg-white/10 px-4 py-2 rounded-xl text-xs font-bold uppercase">Age: {currentUser?.profile.age}</div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <RecordCard title="Smart Reminders" icon={<i className="fas fa-bell"></i>}>
                  <div className="space-y-4">
                    {currentUser?.reminders?.slice(0, 3).map(r => (
                      <div key={r.id} className="p-4 bg-white border border-slate-100 rounded-2xl flex justify-between">
                        <div><p className="font-bold text-slate-800">{r.title}</p><p className="text-[10px] uppercase font-bold text-slate-400">{r.time}</p></div>
                        <i className="fas fa-clock text-indigo-300"></i>
                      </div>
                    ))}
                    <button onClick={handleSyncReminders} className="w-full py-3 bg-indigo-50 text-indigo-600 rounded-xl text-[10px] font-black uppercase tracking-widest">Sync AI Schedule</button>
                  </div>
                </RecordCard>

                <RecordCard title="Private Insurance" icon={ICONS.CREDIT_CARD} onAdd={() => setShowAddModal('add_insurance')}>
                  <div className="space-y-4">
                    {currentUser?.insurances?.map(ins => (
                      <div key={ins.id} className="p-5 bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-2xl text-white shadow-lg relative group">
                        <div className="flex justify-between items-start mb-2">
                           <p className="text-[10px] font-black uppercase tracking-widest text-indigo-200">{ins.provider}</p>
                           <span className="text-[8px] font-black uppercase px-2 py-0.5 bg-emerald-500/20 text-emerald-300 rounded-full">{ins.status}</span>
                        </div>
                        <p className="font-bold text-lg">₹{ins.coverageAmount}</p>
                        <p className="text-[9px] font-mono opacity-60 mt-2">{ins.policyNumber}</p>
                      </div>
                    ))}
                    {!currentUser?.insurances?.length && <p className="text-center text-slate-400 italic py-8">No insurance logged.</p>}
                  </div>
                </RecordCard>
              </div>
            </div>

            <div className="space-y-8">
               <div className="bg-white rounded-[2.5rem] p-8 border border-slate-100 shadow-sm">
                  <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6">Vault Health Metrics</h3>
                  <div className="space-y-6">
                    <div className="flex items-center justify-between"><span className="text-sm font-bold text-slate-800">Records Secure</span><span className="text-emerald-500 font-black">100%</span></div>
                    <div className="flex items-center justify-between"><span className="text-sm font-bold text-slate-800">AI Sync Status</span><span className="text-indigo-500 font-black">Stable</span></div>
                  </div>
               </div>
            </div>
          </div>
        )}

        {activeTab === 'schemes' && (
          <div className="max-w-7xl mx-auto space-y-12 pb-24">
            <div className="bg-indigo-950 p-12 rounded-[3.5rem] text-white relative overflow-hidden group shadow-2xl">
              <div className="absolute top-0 right-0 p-12 opacity-[0.05] group-hover:rotate-12 transition-transform duration-700"><i className="fas fa-landmark text-9xl"></i></div>
              <div className="relative z-10 max-w-2xl">
                <h3 className="text-4xl font-black tracking-tight mb-4">Welfare Discovery Hub</h3>
                <p className="text-indigo-200 text-lg leading-relaxed opacity-80">Tailored Indian health schemes discovered through Shield AI based on your unique clinical severity and status.</p>
                <div className="mt-8 flex items-center gap-3">
                   <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse"></div>
                   <span className="text-[10px] font-black uppercase tracking-widest">Grounding Search Active</span>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-8">
                {currentUser?.problems.filter(p => p.applicableSchemes?.length).map(p => (
                   <div key={p.id} className="space-y-6 animate-pop-in">
                      <div className="flex items-center gap-3 px-4">
                         <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Condition:</span>
                         <span className="text-sm font-bold text-slate-800 uppercase">{p.condition}</span>
                         <span className={`text-[8px] font-black px-2 py-0.5 rounded-full ${p.severity === 'severe' ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                           {p.severity} Match Required
                         </span>
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {p.applicableSchemes?.map(s => (
                          <div key={s.id} className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all group">
                             <div className="flex justify-between items-start mb-6">
                                <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white transition-all duration-500 shadow-sm">{ICONS.SCHEME}</div>
                                <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full">{s.coverageAmount}</span>
                             </div>
                             <h5 className="text-lg font-black text-slate-800 mb-2 uppercase tracking-tight leading-tight">{s.name}</h5>
                             <p className="text-xs text-slate-500 leading-relaxed font-medium italic mb-6">"{s.benefits}"</p>

                             <div className="pt-6 border-t border-slate-50 space-y-4">
                                <div className="p-4 bg-indigo-50/50 rounded-2xl">
                                   <p className="text-[9px] font-black uppercase text-indigo-600 mb-1">AI Match Insight:</p>
                                   <p className="text-[10px] text-slate-600 leading-relaxed">{s.matchReason || `Recommended for active ${p.condition} cases.`}</p>
                                </div>
                                <div className="flex flex-wrap gap-2">
                                  {s.officialSources?.map((src, idx) => (
                                    <a key={idx} href={src.uri} target="_blank" rel="noopener noreferrer" className="px-3 py-1.5 bg-slate-100 rounded-lg text-[9px] font-bold text-slate-600 hover:bg-indigo-600 hover:text-white transition-all truncate max-w-[140px]"><i className="fas fa-link mr-1 opacity-50"></i> Source</a>
                                  ))}
                                </div>
                             </div>
                          </div>
                        ))}
                      </div>
                   </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'records' && (
          <div className="space-y-12 pb-24">
             <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
              <h3 className="text-2xl font-black text-slate-800 tracking-tight">Personal Medical Archive</h3>
              <div className="flex bg-slate-100 p-1.5 rounded-2xl w-fit border border-slate-200/50">
                <button onClick={() => setRecordFilter('present')} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.15em] transition-all ${recordFilter === 'present' ? 'bg-white text-indigo-600 shadow-lg' : 'text-slate-500 hover:text-slate-700'}`}>Active</button>
                <button onClick={() => setRecordFilter('past')} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.15em] transition-all ${recordFilter === 'past' ? 'bg-white text-indigo-600 shadow-lg' : 'text-slate-500 hover:text-slate-700'}`}>History</button>
              </div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
               <RecordCard title="Medical Conditions" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
                  <div className="space-y-6">
                    {filteredProblems.map(p => (
                       <div key={p.id} className="p-8 rounded-[2.5rem] bg-white border border-slate-100 shadow-sm relative overflow-hidden">
                          <h4 className="text-xl font-black text-slate-800 leading-tight mb-2">{p.condition}</h4>
                          <div className="flex items-center gap-3 mb-6">
                             <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-full ${p.severity === 'severe' ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>{p.severity} Severity</span>
                             <span className="text-[8px] font-black uppercase px-2 py-0.5 bg-slate-100 text-slate-500 rounded-full">{p.status}</span>
                          </div>
                          <button onClick={() => runSchemeAnalysis(p.id)} disabled={isAnalyzingRecord === p.id} className="w-full py-4 border-2 border-dashed border-slate-200 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-400 hover:border-indigo-500 hover:text-indigo-600 hover:bg-indigo-50 transition-all flex items-center justify-center gap-2">
                             {isAnalyzingRecord === p.id ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-magic"></i>}
                             {isAnalyzingRecord === p.id ? 'Tapping Welfare API...' : (p.applicableSchemes?.length ? 'Re-run AI Analysis' : 'Identify Govt Benefits')}
                          </button>
                       </div>
                    ))}
                  </div>
               </RecordCard>
            </div>
          </div>
        )}
      </div>

      {showAddModal === 'add_insurance' && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[4rem] w-full max-w-2xl p-12 animate-pop-in relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 w-12 h-12 rounded-full bg-slate-50 text-slate-400 hover:text-slate-800 transition-all text-2xl">&times;</button>
            <h3 className="text-3xl font-black text-slate-800 tracking-tight mb-8">Archive Private Insurance</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const formData = new FormData(e.currentTarget);
              addInsurance({
                id: Date.now().toString(),
                provider: formData.get('provider') as string,
                policyNumber: formData.get('policyNumber') as string,
                coverageAmount: formData.get('coverageAmount') as string,
                expiryDate: formData.get('expiryDate') as string,
                policyType: formData.get('policyType') as any,
                contactPhone: formData.get('contactPhone') as string,
                status: 'active'
              });
            }} className="grid grid-cols-1 sm:grid-cols-2 gap-8">
              <div className="sm:col-span-2"><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Provider</label><input name="provider" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none" /></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Policy No.</label><input name="policyNumber" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none" /></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Coverage (INR)</label><input name="coverageAmount" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none" /></div>
              <div><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Expiry</label><input name="expiryDate" type="date" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none" /></div>
              <button type="submit" className="sm:col-span-2 w-full bg-indigo-600 text-white py-8 rounded-[2.5rem] font-black uppercase tracking-[0.3em] transition-all">Archive Insurance</button>
            </form>
          </div>
        </div>
      )}

      {showAddModal === 'problem' && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[4rem] w-full max-w-2xl p-12 animate-pop-in relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 w-12 h-12 rounded-full bg-slate-50 text-slate-400 hover:text-slate-800 transition-all text-2xl">&times;</button>
            <h3 className="text-3xl font-black text-slate-800 tracking-tight mb-8">Condition Registry</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const formData = new FormData(e.currentTarget);
              addProblem({
                id: Date.now().toString(),
                condition: formData.get('condition') as string,
                status: 'present',
                severity: formData.get('severity') as any,
                onsetDate: new Date().toISOString()
              });
            }} className="grid grid-cols-1 sm:grid-cols-2 gap-8">
              <div className="sm:col-span-2"><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Descriptor</label><input name="condition" required className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none" /></div>
              <div className="sm:col-span-2"><label className="block text-[10px] font-black uppercase text-slate-400 mb-2">Severity</label><select name="severity" className="w-full bg-slate-50 border border-slate-200 rounded-[1.8rem] px-8 py-5 text-sm font-black outline-none"><option value="mild">Mild</option><option value="moderate">Moderate</option><option value="severe">Severe</option></select></div>
              <button type="submit" className="sm:col-span-2 w-full bg-indigo-600 text-white py-8 rounded-[2.5rem] font-black uppercase tracking-[0.3em] transition-all">Archive Condition</button>
            </form>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  UserProfile, 
  HealthRecord, 
  ChatMessage, 
  MedicalProblem, 
  Medication, 
  Insurance,
  Reminder,
  TreatmentNote,
  Interaction,
  DoctorAccessLog
} from './types';
import { ICONS, APP_NAME, MAX_LOGIN_ATTEMPTS, LOCKOUT_DURATION_MS, OTP_EXPIRY_MS } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord, findApplicableSchemes, generateSmartReminders } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';

type ModalType = 'problem' | 'medication' | 'add_insurance' | 'add_note' | null;

const App: React.FC = () => {
  // Authentication & User State
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [loginMethod, setLoginMethod] = useState<'healthid' | 'phone'>('healthid');
  const [roleMode, setRoleMode] = useState<'patient' | 'doctor'>('patient');

  // UI States
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');
  const [authError, setAuthError] = useState('');

  // Auth Form States
  const [loginId, setLoginId] = useState('');
  const [phoneInput, setPhoneInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);

  // Security States
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);
  const [activeOtp, setActiveOtp] = useState<{ code: string, expiresAt: number } | null>(null);
  const [otpTimeLeft, setOtpTimeLeft] = useState(0);

  // Feature States
  const [isAnalyzingRecord, setIsAnalyzingRecord] = useState<string | null>(null);
  const [isSyncingReminders, setIsSyncingReminders] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Registration state
  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', role: 'patient', isPremium: false,
    notificationSettings: { email: true, sms: true, push: true, sound: true },
    visitingHours: { start: '09:00', end: '17:00', days: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'] }
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
          setRoleMode(record.profile.role);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  // OTP Timer Logic
  useEffect(() => {
    let interval: number | undefined;
    if (activeOtp) {
      interval = window.setInterval(() => {
        const remaining = Math.max(0, activeOtp.expiresAt - Date.now());
        setOtpTimeLeft(Math.floor(remaining / 1000));
        if (remaining === 0) {
          setActiveOtp(null);
          setAuthError('OTP expired. Please try again.');
          clearInterval(interval);
        }
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [activeOtp]);

  // Handle Login Logic
  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (lockoutUntil && Date.now() < lockoutUntil) return;
    setAuthError('');
    setIsSubmitting(true);

    let record: HealthRecord | null = null;

    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
      if (!record || record.profile.role !== roleMode) {
        handleLoginFailure();
        return;
      }
    } else {
      if (!isVerifyingOtp) {
        record = await dbService.getRecordByPhone(phoneInput);
        if (record && record.profile.role === roleMode) {
          const code = Math.floor(100000 + Math.random() * 900000).toString();
          console.log(`[SECURE VAULT] Verification Code for ${phoneInput}: ${code}`);
          setActiveOtp({ code, expiresAt: Date.now() + OTP_EXPIRY_MS });
          setOtpTimeLeft(OTP_EXPIRY_MS / 1000);
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
          return;
        } else {
          handleLoginFailure();
          return;
        }
      } else {
        if (activeOtp && otpInput === activeOtp.code && Date.now() < activeOtp.expiresAt) {
          record = await dbService.getRecordByPhone(phoneInput);
        } else {
          handleLoginFailure();
          return;
        }
      }
    }

    if (record) {
      setLoginAttempts(0);
      setCurrentUser(record);
      setIsAuth(true);
      setIsSubmitting(false);
      localStorage.setItem(SESSION_KEY, record.profile.healthId);
    }
  };

  const handleLoginFailure = () => {
    const attempts = loginAttempts + 1;
    setLoginAttempts(attempts);
    if (attempts >= MAX_LOGIN_ATTEMPTS) {
      setLockoutUntil(Date.now() + LOCKOUT_DURATION_MS);
      setAuthError(`Maximum attempts reached. Locked out for 5 minutes.`);
    } else {
      setAuthError(`Authentication failed. ${MAX_LOGIN_ATTEMPTS - attempts} attempts remaining.`);
    }
    setIsSubmitting(false);
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setAuthError('');

    const healthId = `HS-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.floor(1000 + Math.random() * 9000)}`;
    const newRecord: HealthRecord = {
      profile: { ...regForm, healthId, role: roleMode },
      problems: [], medications: [], surgeries: [], allergies: [], notes: [],
      familyHistory: [], insurances: [], reminders: [], interactions: [], accessHistory: []
    };

    try {
      await dbService.saveRecord(newRecord);
      setCurrentUser(newRecord);
      setIsAuth(true);
      localStorage.setItem(SESSION_KEY, healthId);
    } catch (err) {
      setAuthError("Registration failed. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    localStorage.removeItem(SESSION_KEY);
    setActiveTab('dashboard');
  };

  // Feature Implementations
  const handleSyncReminders = async () => {
    if (!currentUser) return;
    setIsSyncingReminders(true);
    try {
      const reminders = await generateSmartReminders(currentUser);
      const updated = { ...currentUser, reminders };
      setCurrentUser(updated);
      await dbService.saveRecord(updated);
    } catch (err) { console.error(err); } finally { setIsSyncingReminders(false); }
  };

  const runSchemeAnalysis = async (problemId: string) => {
    if (!currentUser) return;
    const problem = currentUser.problems.find(p => p.id === problemId);
    if (!problem) return;
    setIsAnalyzingRecord(problemId);
    try {
      const schemes = await findApplicableSchemes(problem, currentUser.profile.age);
      const updatedProblems = currentUser.problems.map(p => 
        p.id === problemId ? { ...p, applicableSchemes: schemes } : p
      );
      const updatedUser = { ...currentUser, problems: updatedProblems };
      setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
    } catch (err) { console.error(err); } finally { setIsAnalyzingRecord(null); }
  };

  const addProblem = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!currentUser) return;
    const formData = new FormData(e.currentTarget);
    const problem: MedicalProblem = {
      id: Date.now().toString(),
      condition: formData.get('condition') as string,
      status: 'present',
      severity: formData.get('severity') as any,
      onsetDate: new Date().toISOString()
    };
    const updated = { ...currentUser, problems: [problem, ...currentUser.problems] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  const addInsurance = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!currentUser) return;
    const formData = new FormData(e.currentTarget);
    const ins: Insurance = {
      id: Date.now().toString(),
      provider: formData.get('provider') as string,
      policyNumber: formData.get('policyNumber') as string,
      coverageAmount: formData.get('coverage') as string,
      expiryDate: formData.get('expiry') as string,
      policyType: 'Individual',
      contactPhone: '',
      status: 'active'
    };
    const updated = { ...currentUser, insurances: [ins, ...(currentUser.insurances || [])] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  const handleAskAi = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const msg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, msg]);
    setUserQuery('');
    setIsAiLoading(true);
    try {
      const response = await analyzeHealthRecord(currentUser, userQuery);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    } catch (err) { console.error(err); } finally { setIsAiLoading(false); }
  };

  const filteredProblems = useMemo(() => {
    if (!currentUser) return [];
    return currentUser.problems.filter(p => recordFilter === 'present' ? p.status === 'present' : p.status !== 'present');
  }, [currentUser, recordFilter]);

  if (isLoading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-[#0a0f1d] text-white">
      <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-6"></div>
      <p className="font-black uppercase tracking-[0.3em] text-xs animate-pulse">Initializing Secure Vault</p>
    </div>
  );

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-[#0a0f1d] relative overflow-hidden">
        {/* Background blobs */}
        <div className="absolute top-0 left-0 w-96 h-96 bg-indigo-600/20 blur-[120px] rounded-full -translate-x-1/2 -translate-y-1/2"></div>
        <div className="absolute bottom-0 right-0 w-96 h-96 bg-purple-600/20 blur-[120px] rounded-full translate-x-1/2 translate-y-1/2"></div>

        <div className="w-full max-w-lg relative z-10">
          <div className="glass-dark rounded-[3rem] p-12 shadow-2xl animate-pop-in">
            {lockoutUntil && Date.now() < lockoutUntil ? (
              <div className="text-center py-10">
                <i className="fas fa-user-lock text-6xl text-red-500 mb-6 animate-bounce"></i>
                <h2 className="text-2xl font-black text-white mb-4">VAULT LOCKED</h2>
                <p className="text-slate-400 text-sm mb-6">Security threshold exceeded. Protocol restriction active.</p>
                <div className="text-3xl font-mono font-bold text-red-400 bg-red-400/10 py-4 rounded-2xl">
                  {Math.floor((lockoutUntil - Date.now()) / 60000)}m {Math.floor(((lockoutUntil - Date.now()) % 60000) / 1000)}s
                </div>
              </div>
            ) : (
              <>
                <div className="text-center mb-10">
                  <div className="w-20 h-20 bg-gradient-to-br from-indigo-500 to-indigo-700 rounded-3xl flex items-center justify-center text-4xl text-white mx-auto mb-6 shadow-2xl">
                    {ICONS.LOCK}
                  </div>
                  <h1 className="text-3xl font-black text-white tracking-tight">{APP_NAME}</h1>
                  <p className="text-indigo-300/60 text-[10px] font-black uppercase tracking-widest mt-2">Personal Medical Ledger</p>
                </div>

                <div className="flex bg-white/5 p-1 rounded-2xl mb-8">
                  <button onClick={() => setAuthMode('login')} className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'login' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}>Login</button>
                  <button onClick={() => setAuthMode('register')} className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'register' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}>Register</button>
                </div>

                {authMode === 'login' ? (
                  <form onSubmit={handleLogin} className="space-y-6">
                    <div className="flex bg-white/5 p-1 rounded-xl mb-4 border border-white/5">
                      <button type="button" onClick={() => {setLoginMethod('healthid'); setAuthError(''); setIsVerifyingOtp(false);}} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'healthid' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Health ID</button>
                      <button type="button" onClick={() => {setLoginMethod('phone'); setAuthError(''); setIsVerifyingOtp(false);}} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'phone' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Phone Number</button>
                    </div>

                    {loginMethod === 'healthid' ? (
                      <div className="space-y-2">
