import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  UserProfile, 
  HealthRecord, 
  ChatMessage, 
  MedicalProblem, 
  Medication, 
  Insurance,
  Reminder,
  TreatmentNote,
  Interaction,
  DoctorAccessLog
} from './types';
import { ICONS, APP_NAME, MAX_LOGIN_ATTEMPTS, LOCKOUT_DURATION_MS, OTP_EXPIRY_MS } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord, findApplicableSchemes, generateSmartReminders } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';

type ModalType = 'problem' | 'medication' | 'add_insurance' | 'add_note' | 'doctor_auth' | null;

const App: React.FC = () => {
  // Authentication & User State
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [loginMethod, setLoginMethod] = useState<'healthid' | 'phone'>('healthid');
  const [roleMode, setRoleMode] = useState<'patient' | 'doctor'>('patient');

  // UI States
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');
  const [authError, setAuthError] = useState('');

  // Auth Form States
  const [loginId, setLoginId] = useState('');
  const [phoneInput, setPhoneInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);

  // Security States
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);
  const [activeOtp, setActiveOtp] = useState<{ code: string, expiresAt: number } | null>(null);
  const [otpTimeLeft, setOtpTimeLeft] = useState(0);

  // Doctor Specific States
  const [patientSearchQuery, setPatientSearchQuery] = useState('');
  const [patientSearchResults, setPatientSearchResults] = useState<HealthRecord[]>([]);
  const [searchedPatient, setSearchedPatient] = useState<HealthRecord | null>(null);
  const [isSearchingPatient, setIsSearchingPatient] = useState(false);
  const [patientSearchError, setPatientSearchError] = useState('');
  const [authorizedPatientId, setAuthorizedPatientId] = useState<string | null>(null);
  const [accessOtpInput, setAccessOtpInput] = useState('');
  const [activeAccessOtp, setActiveAccessOtp] = useState<string | null>(null);

  // Feature States
  const [isAnalyzingRecord, setIsAnalyzingRecord] = useState<string | null>(null);
  const [isSyncingReminders, setIsSyncingReminders] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [copiedId, setCopiedId] = useState(false);

  // Registration state
  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', role: 'patient', isPremium: false,
    specialization: '', licenseNumber: '',
    notificationSettings: { email: true, sms: true, push: true, sound: true },
    visitingHours: { start: '09:00', end: '17:00', days: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'] }
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
          setRoleMode(record.profile.role);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  // OTP Timer Logic
  useEffect(() => {
    let interval: number | undefined;
    if (activeOtp) {
      interval = window.setInterval(() => {
        const remaining = Math.max(0, activeOtp.expiresAt - Date.now());
        setOtpTimeLeft(Math.floor(remaining / 1000));
        if (remaining === 0) {
          setActiveOtp(null);
          setAuthError('OTP expired. Please try again.');
          clearInterval(interval);
        }
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [activeOtp]);

  const handleCopyId = (id: string) => {
    navigator.clipboard.writeText(id);
    setCopiedId(true);
    setTimeout(() => setCopiedId(false), 2000);
  };

  // Handle Login Logic
  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (lockoutUntil && Date.now() < lockoutUntil) return;
    setAuthError('');
    setIsSubmitting(true);

    let record: HealthRecord | null = null;

    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
      if (!record || record.profile.role !== roleMode) {
        handleLoginFailure();
        return;
      }
    } else {
      if (!isVerifyingOtp) {
        record = await dbService.getRecordByPhone(phoneInput);
        if (record && record.profile.role === roleMode) {
          const code = Math.floor(100000 + Math.random() * 900000).toString();
          console.log(`[SECURE VAULT] Verification Code for ${phoneInput}: ${code}`);
          setActiveOtp({ code, expiresAt: Date.now() + OTP_EXPIRY_MS });
          setOtpTimeLeft(OTP_EXPIRY_MS / 1000);
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
          return;
        } else {
          handleLoginFailure();
          return;
        }
      } else {
        if (activeOtp && otpInput === activeOtp.code && Date.now() < activeOtp.expiresAt) {
          record = await dbService.getRecordByPhone(phoneInput);
        } else {
          handleLoginFailure();
          return;
        }
      }
    }

    if (record) {
      setLoginAttempts(0);
      setCurrentUser(record);
      setIsAuth(true);
      setIsSubmitting(false);
      localStorage.setItem(SESSION_KEY, record.profile.healthId);
    }
  };

  const handleLoginFailure = () => {
    const attempts = loginAttempts + 1;
    setLoginAttempts(attempts);
    if (attempts >= MAX_LOGIN_ATTEMPTS) {
      setLockoutUntil(Date.now() + LOCKOUT_DURATION_MS);
      setAuthError(`Maximum attempts reached. Locked out for 5 minutes.`);
    } else {
      setAuthError(`Authentication failed. ${MAX_LOGIN_ATTEMPTS - attempts} attempts remaining.`);
    }
    setIsSubmitting(false);
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setAuthError('');

    const prefix = roleMode === 'doctor' ? 'DR' : 'HS';
    const healthId = `${prefix}-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.floor(1000 + Math.random() * 9000)}`;
    const newRecord: HealthRecord = {
      profile: { ...regForm, healthId, role: roleMode },
      problems: [], medications: [], surgeries: [], allergies: [], notes: [],
      familyHistory: [], insurances: [], reminders: [], interactions: [], accessHistory: []
    };

    try {
      await dbService.saveRecord(newRecord);
      setCurrentUser(newRecord);
      setIsAuth(true);
      localStorage.setItem(SESSION_KEY, healthId);
    } catch (err) {
      setAuthError("Registration failed. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    setSearchedPatient(null);
    setAuthorizedPatientId(null);
    setPatientSearchResults([]);
    localStorage.removeItem(SESSION_KEY);
    setActiveTab('dashboard');
  };

  // Doctor Portal Logic
  const handleSearchPatient = async (e: React.FormEvent) => {
    e.preventDefault();
    setPatientSearchError('');
    setIsSearchingPatient(true);
    setSearchedPatient(null);
    setAuthorizedPatientId(null);
    setPatientSearchResults([]);

    const query = patientSearchQuery.trim();
    if (!query) {
      setIsSearchingPatient(false);
      return;
    }

    // Try Health ID first (starts with HS-)
    if (query.toUpperCase().startsWith('HS-')) {
      const record = await dbService.getRecord(query);
      if (record && record.profile.role === 'patient') {
        setSearchedPatient(record);
      } else {
        setPatientSearchError('No patient found with this Health ID.');
      }
    } else {
      // Search by Name
      const results = await dbService.getRecordsByName(query);
      const filtered = results.filter(r => r.profile.role === 'patient');
      if (filtered.length === 1) {
        setSearchedPatient(filtered[0]);
      } else if (filtered.length > 1) {
        setPatientSearchResults(filtered);
      } else {
        setPatientSearchError('No patients found matching that name.');
      }
    }
    setIsSearchingPatient(false);
  };

  const requestPatientAccess = () => {
    if (!searchedPatient) return;
    const otp = Math.floor(1000 + Math.random() * 9000).toString();
    console.log(`[PATIENT AUTH] Request code for ${searchedPatient.profile.name}: ${otp}`);
    setActiveAccessOtp(otp);
    setShowAddModal('doctor_auth');
  };

  const verifyPatientAccess = async () => {
    if (accessOtpInput === activeAccessOtp && searchedPatient) {
      setAuthorizedPatientId(searchedPatient.profile.healthId);
      setShowAddModal(null);
      setAccessOtpInput('');
      setActiveAccessOtp(null);

      // Log access in patient's history
      const log: DoctorAccessLog = {
        patientHealthId: searchedPatient.profile.healthId,
        patientName: searchedPatient.profile.name,
        timestamp: Date.now()
      };
      const updatedPatient = { 
        ...searchedPatient, 
        accessHistory: [log, ...(searchedPatient.accessHistory || [])] 
      };
      await dbService.saveRecord(updatedPatient);
      setSearchedPatient(updatedPatient);
    } else {
      alert('Invalid authorization code.');
    }
  };

  // Patient Edit Logic (By Doctor)
  const addTreatmentNoteToPatient = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!searchedPatient || !currentUser) return;
    const formData = new FormData(e.currentTarget);
    const note: TreatmentNote = {
      id: Date.now().toString(),
      doctorName: currentUser.profile.name,
      date: new Date().toISOString(),
      note: formData.get('note') as string,
      category: formData.get('category') as any
    };
    const updated = { ...searchedPatient, notes: [note, ...(searchedPatient.notes || [])] };
    setSearchedPatient(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  const addProblemToPatient = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!searchedPatient) return;
    const formData = new FormData(e.currentTarget);
    const problemId = Date.now().toString();
    const problem: MedicalProblem = {
      id: problemId,
      condition: formData.get('condition') as string,
      status: 'present',
      severity: formData.get('severity') as any,
      onsetDate: new Date().toISOString()
    };
    const updated = { ...searchedPatient, problems: [problem, ...searchedPatient.problems] };
    setSearchedPatient(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);

    // AUTOMATIC SCHEME ANALYSIS
    runSchemeAnalysis(problemId, updated);
  };

  // Feature Implementations
  const handleSyncReminders = async () => {
    if (!currentUser) return;
    setIsSyncingReminders(true);
    try {
      const reminders = await generateSmartReminders(currentUser);
      const updated = { ...currentUser, reminders };
      setCurrentUser(updated);
      await dbService.saveRecord(updated);
    } catch (err) { console.error(err); } finally { setIsSyncingReminders(false); }
  };

  const runSchemeAnalysis = async (problemId: string, customTarget?: HealthRecord) => {
    const target = customTarget || searchedPatient || currentUser;
    if (!target) return;
    const problem = target.problems.find(p => p.id === problemId);
    if (!problem) return;
    setIsAnalyzingRecord(problemId);
    try {
      const schemes = await findApplicableSchemes(problem, target.profile.age);
      const updatedProblems = target.problems.map(p => 
        p.id === problemId ? { ...p, applicableSchemes: schemes } : p
      );
      const updatedUser = { ...target, problems: updatedProblems };
      if (searchedPatient || (customTarget && customTarget.profile.role === 'patient' && roleMode === 'doctor')) {
        setSearchedPatient(updatedUser);
      } else {
        setCurrentUser(updatedUser);
      }
      await dbService.saveRecord(updatedUser);
    } catch (err) { console.error(err); } finally { setIsAnalyzingRecord(null); }
  };

  const addProblem = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!currentUser) return;
    const formData = new FormData(e.currentTarget);
    const problemId = Date.now().toString();
    const problem: MedicalProblem = {
      id: problemId,
      condition: formData.get('condition') as string,
      status: 'present',
      severity: formData.get('severity') as any,
      onsetDate: new Date().toISOString()
    };
    const updated = { ...currentUser, problems: [problem, ...currentUser.problems] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);

    // AUTOMATIC SCHEME ANALYSIS
    runSchemeAnalysis(problemId, updated);
  };

  const addInsurance = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!currentUser) return;
    const formData = new FormData(e.currentTarget);
    const ins: Insurance = {
      id: Date.now().toString(),
      provider: formData.get('provider') as string,
      policyNumber: formData.get('policyNumber') as string,
      coverageAmount: formData.get('coverage') as string,
      expiryDate: formData.get('expiry') as string,
      policyType: 'Individual',
      contactPhone: '',
      status: 'active'
    };
    const updated = { ...currentUser, insurances: [ins, ...(currentUser.insurances || [])] };
    setCurrentUser(updated);
    await dbService.saveRecord(updated);
    setShowAddModal(null);
  };

  const handleAskAi = async () => {
    const target = searchedPatient || currentUser;
    if (!userQuery.trim() || !target) return;
    const msg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, msg]);
    setUserQuery('');
    setIsAiLoading(true);
    try {
      const response = await analyzeHealthRecord(target, userQuery);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    } catch (err) { console.error(err); } finally { setIsAiLoading(false); }
  };

  const filteredProblems = useMemo(() => {
    const target = searchedPatient || currentUser;
    if (!target) return [];
    return target.problems.filter(p => recordFilter === 'present' ? p.status === 'present' : p.status !== 'present');
  }, [currentUser, searchedPatient, recordFilter]);

  if (isLoading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-[#0a0f1d] text-white">
      <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-6"></div>
      <p className="font-black uppercase tracking-[0.3em] text-xs animate-pulse">Initializing Secure Vault</p>
    </div>
  );

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-[#0a0f1d] relative overflow-hidden">
        <div className="absolute top-0 left-0 w-96 h-96 bg-indigo-600/20 blur-[120px] rounded-full -translate-x-1/2 -translate-y-1/2"></div>
        <div className="absolute bottom-0 right-0 w-96 h-96 bg-purple-600/20 blur-[120px] rounded-full translate-x-1/2 translate-y-1/2"></div>

        <div className="w-full max-w-lg relative z-10">
          <div className="glass-dark rounded-[3rem] p-12 shadow-2xl animate-pop-in">
            {lockoutUntil && Date.now() < lockoutUntil ? (
              <div className="text-center py-10">
                <i className="fas fa-user-lock text-6xl text-red-500 mb-6 animate-bounce"></i>
                <h2 className="text-2xl font-black text-white mb-4">VAULT LOCKED</h2>
                <p className="text-slate-400 text-sm mb-6">Security threshold exceeded. Protocol restriction active.</p>
                <div className="text-3xl font-mono font-bold text-red-400 bg-red-400/10 py-4 rounded-2xl">
                  {Math.floor((lockoutUntil - Date.now()) / 60000)}m {Math.floor(((lockoutUntil - Date.now()) % 60000) / 1000)}s
                </div>
              </div>
            ) : (
              <>
                <div className="text-center mb-10">
                  <div className="w-20 h-20 bg-gradient-to-br from-indigo-500 to-indigo-700 rounded-3xl flex items-center justify-center text-4xl text-white mx-auto mb-6 shadow-2xl">
                    {ICONS.LOCK}
                  </div>
                  <h1 className="text-3xl font-black text-white tracking-tight">{APP_NAME}</h1>
                </div>

                <div className="flex bg-white/5 p-1 rounded-2xl mb-8">
                  <button onClick={() => setAuthMode('login')} className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'login' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}>Login</button>
                  <button onClick={() => setAuthMode('register')} className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${authMode === 'register' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}>Register</button>
                </div>

                <div className="flex bg-white/5 p-1 rounded-xl mb-6 border border-white/5">
                  <button type="button" onClick={() => {setRoleMode('patient'); setAuthError('');}} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${roleMode === 'patient' ? 'bg-indigo-500/20 text-indigo-300' : 'text-slate-500'}`}>Patient Portal</button>
                  <button type="button" onClick={() => {setRoleMode('doctor'); setAuthError('');}} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${roleMode === 'doctor' ? 'bg-teal-500/20 text-teal-300' : 'text-slate-500'}`}>Medical Professional</button>
                </div>

                {authMode === 'login' ? (
                  <form onSubmit={handleLogin} className="space-y-6">
                    <div className="flex bg-white/5 p-1 rounded-xl mb-4 border border-white/5">
                      <button type="button" onClick={() => {setLoginMethod('healthid'); setAuthError(''); setIsVerifyingOtp(false);}} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'healthid' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Vault ID</button>
                      <button type="button" onClick={() => {setLoginMethod('phone'); setAuthError(''); setIsVerifyingOtp(false);}} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${loginMethod === 'phone' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Phone</button>
                    </div>

                    {loginMethod === 'healthid' ? (
                      <input type="text" placeholder={roleMode === 'doctor' ? "DR-XXXX-XXXX" : "HS-XXXX-XXXX"} className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white font-mono uppercase focus:ring-2 focus:ring-indigo-500 outline-none transition-all" value={loginId} onChange={(e) => setLoginId(e.target.value)} />
                    ) : (
                      <div className="space-y-4">
                        {!isVerifyingOtp ? (
                          <input type="tel" placeholder="+91 XXXXX XXXXX" className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all" value={phoneInput} onChange={(e) => setPhoneInput(e.target.value)} />
                        ) : (
                          <input type="text" maxLength={6} placeholder="••••••" className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-center text-3xl font-black tracking-[0.5em] text-white focus:ring-2 focus:ring-emerald-500 outline-none transition-all" value={otpInput} onChange={(e) => setOtpInput(e.target.value)} />
                        )}
                      </div>
                    )}

                    {authError && <p className="text-red-400 text-xs font-bold text-center bg-red-400/10 py-3 rounded-xl border border-red-400/20">{authError}</p>}

                    <button type="submit" disabled={isSubmitting} className={`w-full py-5 rounded-2xl font-black uppercase tracking-[0.2em] transition-all shadow-xl ${isVerifyingOtp ? 'bg-emerald-600 hover:bg-emerald-500' : 'bg-indigo-600 hover:bg-indigo-500'} text-white`}>
                      {isSubmitting ? 'Verifying...' : 'Access Portal'}
                    </button>
                  </form>
                ) : (
                  <form onSubmit={handleRegister} className="space-y-4 animate-slide-in">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="col-span-2">
                        <label className="text-[10px] font-black uppercase text-slate-500 tracking-widest mb-1 block">Legal Name</label>
                        <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Dr. Jane Smith" onChange={e => setRegForm({...regForm, name: e.target.value})} />
                      </div>
                      {roleMode === 'doctor' && (
                        <>
                          <div className="col-span-2">
                            <label className="text-[10px] font-black uppercase text-slate-500 tracking-widest mb-1 block">Specialization</label>
                            <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Cardiologist" onChange={e => setRegForm({...regForm, specialization: e.target.value})} />
                          </div>
                          <div className="col-span-2">
                            <label className="text-[10px] font-black uppercase text-slate-500 tracking-widest mb-1 block">Medical License No.</label>
                            <input required className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="MCI-12345" onChange={e => setRegForm({...regForm, licenseNumber: e.target.value})} />
                          </div>
                        </>
                      )}
                      <div>
                        <label className="text-[10px] font-black uppercase text-slate-500 tracking-widest mb-1 block">Age</label>
                        <input required type="number" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" onChange={e => setRegForm({...regForm, age: parseInt(e.target.value)})} />
                      </div>
                      <div>
                        <label className="text-[10px] font-black uppercase text-slate-500 tracking-widest mb-1 block">Blood Type</label>
                        <select className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500 appearance-none" onChange={e => setRegForm({...regForm, bloodGroup: e.target.value})}>
                          {['A+', 'B+', 'O+', 'AB+', 'A-', 'B-', 'O-', 'AB-'].map(bg => <option key={bg} className="bg-slate-900">{bg}</option>)}
                        </select>
                      </div>
                    </div>
                    <div>
                      <label className="text-[10px] font-black uppercase text-slate-500 tracking-widest mb-1 block">Contact Number</label>
                      <input required type="tel" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-sm outline-none focus:ring-2 focus:ring-indigo-500" placeholder="+91 XXXXX XXXXX" onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                    </div>
                    <button type="submit" disabled={isSubmitting} className="w-full bg-emerald-600 hover:bg-emerald-500 text-white py-5 rounded-2xl font-black uppercase tracking-[0.2em] transition-all shadow-xl mt-4">
                      Create Vault
                    </button>
                  </form>
                )}
              </>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      userName={currentUser?.profile.name || ''} 
      healthId={currentUser?.profile.healthId || ''}
      isPremium={currentUser?.profile.isPremium} 
      onLogout={handleLogout}
    >
      <div className="max-w-7xl mx-auto space-y-8 animate-pop-in pb-20">
        {activeTab === 'dashboard' && roleMode === 'patient' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-8">
              <div className="bg-indigo-950 rounded-[3rem] p-10 text-white shadow-2xl relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-12 opacity-[0.03] group-hover:scale-110 transition-transform duration-1000"><i className="fas fa-fingerprint text-[15rem]"></i></div>
                <div className="relative z-10 flex flex-col md:flex-row justify-between md:items-end gap-8">
                  <div>
                    <p className="text-indigo-400 text-[10px] font-black uppercase tracking-[0.3em] mb-2">Authenticated Patient</p>
                    <h3 className="text-4xl font-black tracking-tight">{currentUser?.profile.name}</h3>
                    <div className="flex items-center gap-3 mt-1">
                      <p className="text-indigo-300/60 font-mono text-xs">{currentUser?.profile.healthId}</p>
                      <button 
                        onClick={() => handleCopyId(currentUser?.profile.healthId || '')}
                        className="p-1.5 hover:bg-white/10 rounded-lg text-indigo-300/40 hover:text-white transition-all"
                        title="Copy Health ID"
                      >
                        <i className={`fas ${copiedId ? 'fa-check text-emerald-400' : 'fa-copy'} text-[10px]`}></i>
                      </button>
                    </div>
                  </div>
                  <div className="flex flex-wrap gap-4">
                    <div className="bg-white/5 px-4 py-2 rounded-xl border border-white/10"><span className="text-[8px] font-black text-indigo-400 uppercase tracking-widest">Age</span><p className="text-sm font-bold">{currentUser?.profile.age} Yrs</p></div>
                    <div className="bg-white/5 px-4 py-2 rounded-xl border border-white/10"><span className="text-[8px] font-black text-indigo-400 uppercase tracking-widest">Blood</span><p className="text-sm font-bold">{currentUser?.profile.bloodGroup}</p></div>
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <RecordCard title="Smart Reminders" icon={<i className="fas fa-clock"></i>}>
                   <div className="space-y-4">
                    {currentUser?.reminders?.slice(0, 3).map(r => (
                      <div key={r.id} className="p-4 bg-white border border-slate-100 rounded-2xl flex items-center justify-between">
                        <div><p className="text-sm font-bold">{r.title}</p><p className="text-[9px] font-black text-slate-400 uppercase">{r.time}</p></div>
                        <i className={`fas fa-check-circle ${r.status === 'completed' ? 'text-emerald-500' : 'text-slate-200'}`}></i>
                      </div>
                    ))}
                    <button onClick={handleSyncReminders} className="w-full py-4 bg-indigo-50 text-indigo-600 rounded-2xl text-[10px] font-black uppercase tracking-widest">Refresh AI Schedule</button>
                  </div>
                </RecordCard>
                <RecordCard title="Private Insurance" icon={ICONS.CREDIT_CARD} onAdd={() => setShowAddModal('add_insurance')}>
                  <div className="space-y-4">
                    {currentUser?.insurances?.map(ins => (
                      <div key={ins.id} className="p-5 bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-3xl text-white shadow-lg">
                        <p className="text-[9px] font-black uppercase text-indigo-300 mb-2">{ins.provider}</p>
                        <p className="text-xl font-black">₹{ins.coverageAmount}</p>
                        <p className="text-xs font-mono opacity-60 mt-2">{ins.policyNumber}</p>
                      </div>
                    ))}
                  </div>
                </RecordCard>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'dashboard' && roleMode === 'doctor' && (
          <div className="space-y-8">
            <div className="bg-teal-950 p-12 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-12 opacity-[0.05] group-hover:scale-110 transition-transform duration-1000"><i className="fas fa-user-md text-[15rem]"></i></div>
              <div className="relative z-10 flex flex-col md:flex-row justify-between md:items-center gap-8">
                <div>
                  <p className="text-teal-400 text-[10px] font-black uppercase tracking-[0.3em] mb-2">Medical Professional Portal</p>
                  <h3 className="text-4xl font-black tracking-tight">{currentUser?.profile.name}</h3>
                  <div className="flex gap-4 mt-4">
                    <span className="px-4 py-2 bg-white/5 rounded-xl text-xs font-bold border border-white/10">{currentUser?.profile.specialization}</span>
                    <span className="px-4 py-2 bg-white/5 rounded-xl text-xs font-mono border border-white/10">{currentUser?.profile.licenseNumber}</span>
                  </div>
                </div>
                <div className="text-right flex flex-col items-end">
                  <div className="flex items-center gap-3">
                    <p className="text-3xl font-mono font-bold text-teal-400">{currentUser?.profile.healthId}</p>
                    <button 
                      onClick={() => handleCopyId(currentUser?.profile.healthId || '')}
                      className="p-2 hover:bg-white/10 rounded-xl text-teal-400/40 hover:text-teal-400 transition-all"
                      title="Copy Health ID"
                    >
                      <i className={`fas ${copiedId ? 'fa-check text-emerald-400' : 'fa-copy'}`}></i>
                    </button>
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-xl">
               <h3 className="text-xl font-black text-slate-800 mb-8 uppercase tracking-tight">Patient Search & Secure Access</h3>
               <form onSubmit={handleSearchPatient} className="flex gap-4">
                  <input type="text" placeholder="Enter Patient Name or Health ID (HS-XXXX-XXXX)" className="flex-grow bg-slate-50 border border-slate-200 rounded-[1.5rem] px-8 py-5 text-sm font-bold uppercase tracking-widest outline-none focus:ring-2 focus:ring-teal-500 transition-all" value={patientSearchQuery} onChange={(e) => setPatientSearchQuery(e.target.value)} />
                  <button type="submit" disabled={isSearchingPatient} className="bg-teal-600 text-white px-10 py-5 rounded-[1.5rem] font-black uppercase tracking-widest shadow-xl shadow-teal-600/20 hover:bg-teal-500 transition-all">
                    {isSearchingPatient ? <i className="fas fa-spinner animate-spin"></i> : 'Search Patients'}
                  </button>
               </form>
               {patientSearchError && <p className="text-red-500 text-xs font-bold mt-4 px-4">{patientSearchError}</p>}

               {/* Search Results List */}
               {patientSearchResults.length > 0 && (
                 <div className="mt-8 space-y-4 animate-pop-in">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-4">Multiple Matches Found ({patientSearchResults.length})</p>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                      {patientSearchResults.map(patient => (
                        <div key={patient.profile.healthId} className="p-6 bg-slate-50 border border-slate-200 rounded-[2rem] hover:border-teal-400 transition-all group flex flex-col justify-between">
