                      {currentUser?.surgeries?.map(s => (
                        <div key={s.id} className="p-6 bg-white border border-slate-100 rounded-[2.5rem] shadow-sm relative overflow-hidden group">
                          <div className="flex justify-between items-start mb-4">
                            <h4 className="text-lg font-black text-slate-800 uppercase tracking-tight leading-tight">{s.type}</h4>
