                          <h5 className="text-lg font-black text-slate-800 mb-2 uppercase tracking-tight leading-tight">{s.name}</h5>
                          <p className="text-xs text-slate-500 leading-relaxed font-medium italic mb-4">"{s.benefits}"</p>

                          <div className="pt-6 border-t border-slate-50 space-y-4">
                             <div>
                                <p className="text-[9px] font-black uppercase text-slate-400 mb-1 tracking-widest">Eligibility Criteria:</p>
                                <p className="text-[10px] text-slate-600 font-semibold leading-relaxed">{s.eligibility}</p>
