                                </div>
                              </div>
                            ))}
                            {!searchedPatient.surgeries?.length && <p className="text-center text-slate-300 py-10 font-bold uppercase text-xs">No surgeries recorded.</p>}
                          </div>
                       </RecordCard>

                       <RecordCard title="Professional Consult Notes" icon={ICONS.NOTE} onAdd={() => setShowAddModal('add_note')}>
