                <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Personal Medical Archive</h3>
                <div className="flex bg-slate-100 p-1.5 rounded-2xl">
                   <button onClick={() => setRecordFilter('present')} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${recordFilter === 'present' ? 'bg-white text-indigo-600 shadow-lg' : 'text-slate-500'}`}>Present</button>
