                        <h4 className="text-2xl font-black text-slate-800 tracking-tight mb-1">{searchedPatient.profile.name}</h4>
                        <div className="flex gap-3 text-[10px] font-black uppercase text-slate-400">
                          <span>{searchedPatient.profile.gender}</span>
                          <span>•</span>
                          <span>{searchedPatient.profile.age} Yrs</span>
                          <span>•</span>
                          <span>Blood: {searchedPatient.profile.bloodGroup}</span>
                        </div>
                      </div>
                    </div>
                    {authorizedPatientId !== searchedPatient.profile.healthId ? (
                      <button onClick={requestPatientAccess} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest shadow-lg shadow-indigo-600/20 hover:bg-indigo-500 transition-all">Request Secure Access</button>
