                            <div className="flex items-center gap-4">
                               <span className={`text-[8px] font-black uppercase px-2 py-1 rounded-full ${p.severity === 'severe' ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>{p.severity} Priority</span>
