                          <div className="flex flex-col gap-2">
                             <p className="text-[10px] font-black uppercase text-indigo-600 tracking-widest flex items-center gap-2"><i className="fas fa-hospital"></i> {s.hospital}</p>
                             <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-2"><i className="fas fa-user-md"></i> Dr. {s.surgeon}</p>
                          </div>
                        </div>
                      ))}
                      {!currentUser?.surgeries?.length && <p className="text-center text-slate-300 py-10 font-bold uppercase text-xs">No records archived.</p>}
                    </div>
                 </RecordCard>
              </div>
           </div>
