  const [loginMethod, setLoginMethod] = useState<'healthid' | 'phone'>('healthid');
  const [roleMode, setRoleMode] = useState<'patient' | 'doctor'>('patient');

  const [activeTab, setActiveTab] = useState('dashboard');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');
  const [authError, setAuthError] = useState('');

  const [loginId, setLoginId] = useState('');
  const [phoneInput, setPhoneInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);

  const [loginAttempts, setLoginAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);
  const [activeOtp, setActiveOtp] = useState<{ code: string, expiresAt: number } | null>(null);

  const [patientSearchQuery, setPatientSearchQuery] = useState('');
  const [patientSearchResults, setPatientSearchResults] = useState<HealthRecord[]>([]);
  const [searchedPatient, setSearchedPatient] = useState<HealthRecord | null>(null);
  const [isSearchingPatient, setIsSearchingPatient] = useState(false);
  const [authorizedPatientId, setAuthorizedPatientId] = useState<string | null>(null);
  const [accessOtpInput, setAccessOtpInput] = useState('');
  const [activeAccessOtp, setActiveAccessOtp] = useState<string | null>(null);

  const [isAnalyzingRecord, setIsAnalyzingRecord] = useState<string | null>(null);
  const [isSyncingReminders, setIsSyncingReminders] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', role: 'patient'
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
          setRoleMode(record.profile.role);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (lockoutUntil && Date.now() < lockoutUntil) return;
    setAuthError('');
    setIsSubmitting(true);

    let record: HealthRecord | null = null;
    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
      if (!record || record.profile.role !== roleMode) {
        handleLoginFailure();
        return;
      }
    } else {
      if (!isVerifyingOtp) {
        record = await dbService.getRecordByPhone(phoneInput);
        if (record && record.profile.role === roleMode) {
          const code = Math.floor(1000 + Math.random() * 9000).toString();
          console.log(`[SECURE AUTH] CODE FOR ${phoneInput}: ${code}`);
          setActiveOtp({ code, expiresAt: Date.now() + OTP_EXPIRY_MS });
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
          return;
        } else {
          handleLoginFailure();
          return;
        }
      } else {
        if (activeOtp && otpInput === activeOtp.code) {
          record = await dbService.getRecordByPhone(phoneInput);
        } else {
          handleLoginFailure();
          return;
        }
      }
    }

    if (record) {
      setCurrentUser(record);
      setIsAuth(true);
      localStorage.setItem(SESSION_KEY, record.profile.healthId);
    }
    setIsSubmitting(false);
  };

  const handleLoginFailure = () => {
    const attempts = loginAttempts + 1;
    setLoginAttempts(attempts);
    if (attempts >= MAX_LOGIN_ATTEMPTS) setLockoutUntil(Date.now() + LOCKOUT_DURATION_MS);
    setAuthError(`Verification failed. ${MAX_LOGIN_ATTEMPTS - attempts} attempts left.`);
    setIsSubmitting(false);
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const prefix = roleMode === 'doctor' ? 'DR' : 'HS';
    const healthId = `${prefix}-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.floor(1000 + Math.random() * 9000)}`;
    const newRecord: HealthRecord = {
      profile: { ...regForm, healthId, role: roleMode },
      problems: [], medications: [], surgeries: [], allergies: [], notes: [],
      familyHistory: [], insurances: [], reminders: [], interactions: [], accessHistory: [],
      lastUpdated: Date.now()
    };
    await dbService.saveRecord(newRecord);
    setCurrentUser(newRecord);
    setIsAuth(true);
    localStorage.setItem(SESSION_KEY, healthId);
    setIsSubmitting(false);
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    localStorage.removeItem(SESSION_KEY);
    setActiveTab('dashboard');
  };

  const handleSearchPatient = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSearchingPatient(true);
    const allRecords = await dbService.getAllRecords();
    const results = allRecords.filter(r => 
      r.profile.role === 'patient' && 
      (r.profile.name.toLowerCase().includes(patientSearchQuery.toLowerCase()) || 
       r.profile.healthId.includes(patientSearchQuery.toUpperCase()))
    );
    setPatientSearchResults(results);
    setIsSearchingPatient(false);
  };

  const runSchemeAnalysis = async (problemId: string) => {
    const target = searchedPatient || currentUser;
    if (!target) return;
    const problem = target.problems.find(p => p.id === problemId);
    if (!problem) return;
    setIsAnalyzingRecord(problemId);
    try {
      const schemes = await findApplicableSchemes(problem, target.profile.age);
      const updatedUser = { ...target, problems: target.problems.map(p => p.id === problemId ? { ...p, applicableSchemes: schemes } : p) };
      if (searchedPatient) setSearchedPatient(updatedUser);
      else setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
    } finally { setIsAnalyzingRecord(null); }
  };

  const handleAskAi = async () => {
    const target = searchedPatient || currentUser;
    if (!userQuery.trim() || !target) return;
    setChatHistory(prev => [...prev, { role: 'user', content: userQuery, timestamp: Date.now() }]);
    setIsAiLoading(true);
    try {
      const response = await analyzeHealthRecord(target, userQuery);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    } finally { setIsAiLoading(false); setUserQuery(''); }
  };

  if (isLoading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-slate-950 text-white">
      <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-6"></div>
      <p className="font-black uppercase tracking-[0.4em] text-[10px] animate-pulse">Initializing Security Protocol</p>
    </div>
  );

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-950 relative overflow-hidden">
        {/* Abstract Background */}
        <div className="absolute top-0 left-0 w-[50vw] h-[50vw] bg-indigo-600/10 blur-[150px] rounded-full -translate-x-1/2 -translate-y-1/2"></div>
        <div className="absolute bottom-0 right-0 w-[50vw] h-[50vw] bg-purple-600/10 blur-[150px] rounded-full translate-x-1/2 translate-y-1/2"></div>

        <div className="w-full max-w-xl relative z-10">
          <div className="glass-dark rounded-[4rem] p-16 shadow-2xl animate-pop-in">
            <div className="text-center mb-12">
              <div className="w-24 h-24 bg-gradient-to-br from-indigo-500 to-indigo-700 rounded-[2.5rem] flex items-center justify-center text-4xl text-white mx-auto mb-8 shadow-2xl">
                {ICONS.LOCK}
              </div>
              <h1 className="text-4xl font-black text-white tracking-tight">{APP_NAME}</h1>
              <p className="text-slate-400 mt-2 text-sm font-medium">Securing clinical data with Shield Intelligence</p>
            </div>

            <div className="flex bg-white/5 p-1.5 rounded-[2rem] mb-10">
              <button onClick={() => setRoleMode('patient')} className={`flex-1 py-4 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${roleMode === 'patient' ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:text-slate-300'}`}>Patient Portal</button>
              <button onClick={() => setRoleMode('doctor')} className={`flex-1 py-4 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${roleMode === 'doctor' ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:text-slate-300'}`}>Medical Pro</button>
            </div>

            <div className="flex bg-white/5 p-1.5 rounded-2xl mb-8">
              <button onClick={() => setAuthMode('login')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${authMode === 'login' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Login</button>
              <button onClick={() => setAuthMode('register')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${authMode === 'register' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Sign Up</button>
            </div>

            {authMode === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-6">
                <div className="flex bg-white/5 p-1.5 rounded-2xl mb-6">
                  <button type="button" onClick={() => setLoginMethod('healthid')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${loginMethod === 'healthid' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Health ID</button>
                  <button type="button" onClick={() => setLoginMethod('phone')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${loginMethod === 'phone' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Phone</button>
                </div>

                {loginMethod === 'healthid' ? (
                  <input required placeholder={roleMode === 'doctor' ? "DR-XXXX-XXXX" : "HS-XXXX-XXXX"} className="w-full bg-white/5 border border-white/10 rounded-[2rem] px-8 py-5 text-white font-mono uppercase focus:ring-2 focus:ring-indigo-500 outline-none" value={loginId} onChange={e => setLoginId(e.target.value)} />
                ) : (
                  <div className="space-y-6">
                    {!isVerifyingOtp ? (
                      <input required type="tel" placeholder="+91 XXXXX XXXXX" className="w-full bg-white/5 border border-white/10 rounded-[2rem] px-8 py-5 text-white outline-none focus:ring-2 focus:ring-indigo-500" value={phoneInput} onChange={e => setPhoneInput(e.target.value)} />
                    ) : (
                      <div className="space-y-6 animate-slide-in">
                        <p className="text-center text-[10px] font-black uppercase text-indigo-400 tracking-[0.2em]">Enter 4-Digit Access Code</p>
                        <input required maxLength={4} className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] py-8 text-6xl font-black tracking-[1em] text-center text-white outline-none focus:ring-2 focus:ring-indigo-500" value={otpInput} onChange={e => setOtpInput(e.target.value.replace(/\D/g, ''))} />
                      </div>
                    )}
                  </div>
                )}
                {authError && <p className="text-red-400 text-[10px] font-black uppercase tracking-widest text-center">{authError}</p>}
                <button type="submit" disabled={isSubmitting} className="w-full py-6 rounded-full bg-indigo-600 hover:bg-indigo-500 text-white font-black uppercase tracking-[0.25em] text-xs shadow-2xl transition-all">
                  {isSubmitting ? 'Authenticating...' : 'Access Vault'}
                </button>
              </form>
            ) : (
              <form onSubmit={handleRegister} className="space-y-5 animate-slide-in">
                <input required placeholder="Legal Full Name" className="w-full bg-white/5 border border-white/10 rounded-[1.5rem] px-6 py-4 text-white text-sm outline-none" onChange={e => setRegForm({...regForm, name: e.target.value})} />
                <div className="grid grid-cols-2 gap-4">
                  <input required type="number" placeholder="Age" className="w-full bg-white/5 border border-white/10 rounded-[1.5rem] px-6 py-4 text-white text-sm outline-none" onChange={e => setRegForm({...regForm, age: parseInt(e.target.value)})} />
                  <select className="w-full bg-slate-900 border border-white/10 rounded-[1.5rem] px-6 py-4 text-white text-sm outline-none" onChange={e => setRegForm({...regForm, bloodGroup: e.target.value})}>
                    {['A+', 'B+', 'O+', 'AB+', 'A-', 'B-', 'O-', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                  </select>
                </div>
                <input required type="tel" placeholder="Phone Number" className="w-full bg-white/5 border border-white/10 rounded-[1.5rem] px-6 py-4 text-white text-sm outline-none" onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                <button type="submit" disabled={isSubmitting} className="w-full py-6 rounded-full bg-indigo-600 hover:bg-indigo-500 text-white font-black uppercase tracking-[0.25em] text-xs shadow-2xl transition-all">Initialize Vault</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      userName={currentUser?.profile.name || ''} 
      healthId={currentUser?.profile.healthId || ''}
      role={roleMode}
      profilePicture={currentUser?.profile.profilePicture}
      onLogout={handleLogout}
    >
      <div className="max-w-7xl mx-auto space-y-12 animate-pop-in pb-20">
        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
            <div className="lg:col-span-2 space-y-12">
              <div className="bg-slate-950 rounded-[4rem] p-12 text-white shadow-2xl relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-12 opacity-[0.03] group-hover:scale-110 transition-transform duration-1000"><i className="fas fa-fingerprint text-[18rem]"></i></div>
                <div className="relative z-10 flex flex-col md:flex-row justify-between md:items-end gap-10">
                  <div className="flex items-center gap-10">
                    <div className="w-32 h-32 rounded-[3.5rem] bg-white/5 border border-white/10 flex items-center justify-center shrink-0 overflow-hidden shadow-2xl">
                       {currentUser?.profile.profilePicture ? (
                         <img src={currentUser.profile.profilePicture} alt="" className="w-full h-full object-cover" />
                       ) : (
                         <i className="fas fa-user text-5xl text-indigo-400"></i>
                       )}
                    </div>
                    <div>
                      <p className="text-indigo-400 text-[10px] font-black uppercase tracking-[0.4em] mb-3">Active Identity Profile</p>
                      <h3 className="text-5xl font-black tracking-tight leading-none">{currentUser?.profile.name}</h3>
                      <p className="text-white/40 font-mono text-sm mt-3 tracking-widest">{currentUser?.profile.healthId}</p>
                    </div>
                  </div>
                  <div className="flex flex-wrap gap-6">
                    <div className="bg-white/5 px-6 py-3 rounded-[1.5rem] border border-white/10 text-center"><span className="text-[9px] font-black text-indigo-400 uppercase block mb-1">Age Group</span><p className="text-lg font-bold">{currentUser?.profile.age} Yrs</p></div>
                    <div className="bg-white/5 px-6 py-3 rounded-[1.5rem] border border-white/10 text-center"><span className="text-[9px] font-black text-indigo-400 uppercase block mb-1">Blood Type</span><p className="text-lg font-bold">{currentUser?.profile.bloodGroup}</p></div>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <RecordCard title="Priority Reminders" icon={<i className="fas fa-calendar-check"></i>} isLoading={isSyncingReminders} loadingMessage="AI Syncing Timeline...">
                  <div className="space-y-6">
                    {currentUser?.reminders?.slice(0, 3).map(r => (
                      <div key={r.id} className="p-6 bg-slate-50 rounded-[2.5rem] flex items-center justify-between border border-slate-100 group hover:border-indigo-200 transition-all">
                        <div><p className="font-bold text-slate-900">{r.title}</p><p className="text-[10px] font-black text-slate-400 uppercase mt-1">{r.time}</p></div>
                        <i className={`fas fa-check-circle text-2xl ${r.status === 'completed' ? 'text-emerald-500' : 'text-slate-200'}`}></i>
                      </div>
                    ))}
                    <button className="w-full py-5 bg-indigo-600 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-xl shadow-indigo-600/20">Manage Schedule</button>
                  </div>
                </RecordCard>
                <RecordCard title="Medical Insurance" icon={ICONS.CREDIT_CARD} onAdd={() => setShowAddModal('add_insurance')}>
                   <div className="space-y-6">
                    {currentUser?.insurances?.map(ins => (
                      <div key={ins.id} className="p-8 bg-gradient-to-br from-indigo-600 to-indigo-900 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden">
                        <div className="absolute -bottom-4 -right-4 opacity-10 rotate-12"><i className="fas fa-shield-alt text-8xl"></i></div>
                        <p className="text-[10px] font-black uppercase text-indigo-300 mb-4">{ins.provider}</p>
                        <p className="text-3xl font-black tracking-tight leading-none">₹{ins.coverageAmount}</p>
                        <p className="text-[10px] font-mono text-white/40 mt-4 uppercase tracking-[0.2em]">{ins.policyNumber}</p>
                      </div>
                    ))}
                    {!currentUser?.insurances?.length && <div className="text-center py-10 border-2 border-dashed border-slate-100 rounded-[3rem] text-slate-300 font-bold uppercase text-[10px]">No insurance logged</div>}
                  </div>
                </RecordCard>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'search' && roleMode === 'doctor' && (
          <div className="space-y-12">
            <div className="bg-white rounded-[4.5rem] p-16 shadow-2xl border border-slate-100">
              <h3 className="text-4xl font-black text-slate-900 tracking-tight mb-8 uppercase leading-none">Global Patient Index</h3>
              <form onSubmit={handleSearchPatient} className="flex gap-6">
                <input 
                  className="flex-grow bg-slate-50 border-2 border-slate-100 rounded-full px-10 py-6 text-lg font-bold placeholder:text-slate-300 focus:border-indigo-500 focus:bg-white outline-none transition-all shadow-inner" 
                  placeholder="Enter Name or Health ID..." 
                  value={patientSearchQuery} 
                  onChange={e => setPatientSearchQuery(e.target.value)} 
                />
                <button type="submit" disabled={isSearchingPatient} className="px-12 py-6 bg-slate-950 text-white rounded-full font-black uppercase tracking-[0.2em] shadow-2xl hover:-translate-y-1 transition-all">
                  {isSearchingPatient ? <i className="fas fa-circle-notch animate-spin"></i> : 'Execute Search'}
                </button>
              </form>

              {patientSearchResults.length > 0 && (
                <div className="mt-16 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 animate-slide-in">
                  {patientSearchResults.map(patient => (
                    <div key={patient.profile.healthId} className="bg-slate-50 border border-slate-100 rounded-[4rem] p-10 hover:shadow-2xl transition-all group flex flex-col items-center text-center">
                      <div className="w-24 h-24 rounded-[2.5rem] bg-white shadow-xl flex items-center justify-center mb-8 shrink-0 overflow-hidden group-hover:scale-105 transition-transform">
                        {patient.profile.profilePicture ? (
                          <img src={patient.profile.profilePicture} alt="" className="w-full h-full object-cover" />
                        ) : (
                          <i className="fas fa-user text-3xl text-slate-300"></i>
                        )}
                      </div>
                      <h4 className="text-2xl font-black text-slate-900 mb-2">{patient.profile.name}</h4>
                      <p className="text-[11px] font-mono text-slate-400 mb-8 uppercase tracking-widest">{patient.profile.healthId}</p>
                      <button 
                        onClick={() => { setSearchedPatient(patient); setShowAddModal('doctor_auth'); }}
                        className="w-full py-5 bg-white border-2 border-slate-200 rounded-full font-black uppercase tracking-[0.2em] text-[10px] text-slate-600 hover:bg-indigo-600 hover:text-white hover:border-indigo-600 transition-all"
                      >
                        Initialize Session
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {searchedPatient && authorizedPatientId === searchedPatient.profile.healthId && (
              <div className="animate-pop-in space-y-12">
                <div className="bg-emerald-50 border-2 border-emerald-100 rounded-[4rem] p-12 flex justify-between items-center">
                  <div>
                    <h4 className="text-3xl font-black text-emerald-900 tracking-tight leading-none mb-4">{searchedPatient.profile.name}</h4>
                    <div className="flex gap-6 text-[10px] font-black uppercase text-emerald-600 tracking-[0.1em]">
                      <span>{searchedPatient.profile.gender}</span>
                      <span>•</span>
                      <span>{searchedPatient.profile.age} Yrs</span>
                      <span>•</span>
                      <span>Blood: {searchedPatient.profile.bloodGroup}</span>
                    </div>
                  </div>
                  <div className="bg-white px-8 py-4 rounded-full text-[10px] font-black uppercase text-emerald-700 shadow-sm border border-emerald-100">Session Authorized</div>
                </div>
                {/* Doctor's view of patient records would go here */}
              </div>
            )}
          </div>
        )}

        {activeTab === 'records' && (
          <div className="space-y-12">
            <div className="flex justify-between items-end">
              <div>
                <h3 className="text-4xl font-black text-slate-900 tracking-tight uppercase leading-none">Medical Ledger</h3>
                <p className="text-slate-400 font-medium mt-4">Immutable record of your clinical history</p>
              </div>
              <div className="flex bg-slate-100 p-2 rounded-full shadow-inner">
                <button onClick={() => setRecordFilter('present')} className={`px-10 py-4 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${recordFilter === 'present' ? 'bg-white text-indigo-600 shadow-xl' : 'text-slate-400'}`}>Present</button>
                <button onClick={() => setRecordFilter('past')} className={`px-10 py-4 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${recordFilter === 'past' ? 'bg-white text-indigo-600 shadow-xl' : 'text-slate-400'}`}>Historical</button>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
              <RecordCard title="Condition Ledger" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')} isLoading={!!isAnalyzingRecord} loadingMessage="AI Mapping Assets...">
                <div className="space-y-8">
                  {(searchedPatient || currentUser)?.problems.filter(p => recordFilter === 'present' ? p.status === 'present' : p.status !== 'present').map(p => (
                    <div key={p.id} className="p-10 bg-slate-50 rounded-[3.5rem] border border-slate-100 hover:shadow-xl transition-all">
                       <div className="flex justify-between items-start mb-6">
                         <h4 className="text-2xl font-black text-slate-900 leading-tight uppercase tracking-tight">{p.condition}</h4>
                         <span className={`text-[9px] font-black uppercase px-4 py-2 rounded-full ${p.severity === 'severe' ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>{p.severity} Priority</span>
                       </div>
                       <button onClick={() => runSchemeAnalysis(p.id)} className="text-[10px] font-black text-indigo-600 hover:underline uppercase tracking-widest flex items-center gap-3">
                         <i className="fas fa-search-dollar"></i> Welfare Coverage Check
                       </button>
                    </div>
                  ))}
                  {!(searchedPatient || currentUser)?.problems.length && <div className="text-center py-20 text-slate-300 font-black uppercase tracking-widest text-xs">No ledger entries archived</div>}
                </div>
              </RecordCard>
              <RecordCard title="Surgical History" icon={ICONS.SURGERY} onAdd={() => setShowAddModal('surgery')}>
                <div className="space-y-8">
                  {(searchedPatient || currentUser)?.surgeries?.map(s => (
                    <div key={s.id} className="p-10 bg-slate-50 rounded-[3.5rem] border border-slate-100">
                      <div className="flex justify-between items-start mb-6">
                        <h4 className="text-2xl font-black text-slate-900 leading-tight uppercase tracking-tight">{s.type}</h4>
                        <span className="text-[11px] font-mono text-slate-400">{new Date(s.date).toLocaleDateString()}</span>
                      </div>
                      <div className="flex flex-col gap-3">
                         <p className="text-[11px] font-black uppercase text-indigo-600 tracking-widest"><i className="fas fa-hospital mr-3"></i> {s.hospital}</p>
                         <p className="text-[11px] font-black uppercase text-slate-500 tracking-widest"><i className="fas fa-user-md mr-3"></i> Dr. {s.surgeon}</p>
                      </div>
                    </div>
                  ))}
                  {!(searchedPatient || currentUser)?.surgeries?.length && <div className="text-center py-20 text-slate-300 font-black uppercase tracking-widest text-xs">No procedures archived</div>}
                </div>
              </RecordCard>
            </div>
          </div>
        )}
      </div>

      {/* Premium OTP Modal Logic */}
      {showAddModal === 'doctor_auth' && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-2xl z-[100] flex items-center justify-center p-8">
          <div className="bg-white rounded-[4.5rem] w-full max-w-xl p-16 animate-pop-in relative text-center shadow-2xl">
            <h3 className="text-4xl font-black text-slate-900 tracking-tight mb-8">Patient Authorization</h3>
            <p className="text-slate-500 text-lg mb-12 leading-relaxed px-10">A secure token has been sent to the patient. Enter the 4-digit code to initialize session access.</p>

            <div className="relative mb-12 group">
              <div className="flex justify-center items-center gap-10 py-12 border-2 border-indigo-100 rounded-[3.5rem] bg-slate-50 focus-within:border-indigo-500 focus-within:bg-white transition-all shadow-inner">
                {Array.from({ length: 4 }).map((_, i) => (
                  <span key={i} className={`text-7xl font-black transition-all ${accessOtpInput[i] ? 'text-indigo-600 scale-110' : 'text-slate-200'}`}>
                    {accessOtpInput[i] || (i + 1)}
                  </span>
                ))}
              </div>
              <input 
                autoFocus
                type="text" 
                maxLength={4} 
                className="absolute inset-0 opacity-0 cursor-default" 
                value={accessOtpInput} 
                onChange={(e) => {
                  const val = e.target.value.replace(/\D/g, '');
                  if (val.length <= 4) setAccessOtpInput(val);
                }} 
              />
            </div>

            <button 
              onClick={() => {
                if (accessOtpInput.length === 4) {
                  setAuthorizedPatientId(searchedPatient?.profile.healthId || null);
                  setShowAddModal(null);
                  setAccessOtpInput('');
                }
              }} 
              className="w-full bg-indigo-600 text-white py-8 rounded-full font-black uppercase tracking-[0.3em] text-sm shadow-2xl shadow-indigo-600/30 hover:bg-indigo-700 hover:-translate-y-1 active:translate-y-0 transition-all"
            >
              Authorize Access
            </button>
          </div>
        </div>
      )}

      {/* Universal Modals (Simplified) */}
      {showAddModal === 'problem' && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-8">
          <div className="bg-white rounded-[4rem] w-full max-w-2xl p-16 animate-pop-in relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 w-16 h-16 rounded-full bg-slate-50 text-slate-400 hover:text-slate-900 transition-all text-3xl">&times;</button>
            <h3 className="text-4xl font-black text-slate-900 tracking-tight mb-12 uppercase">Archive Condition</h3>
            <form onSubmit={async (e) => {
              e.preventDefault();
              const target = searchedPatient || currentUser;
              if (!target) return;
              const formData = new FormData(e.currentTarget);
              const pId = Date.now().toString();
              const updated = { ...target, problems: [{ id: pId, condition: formData.get('condition') as string, status: 'present', severity: formData.get('severity') as any, onsetDate: new Date().toISOString() }, ...target.problems] };
              if (searchedPatient) setSearchedPatient(updated);
              else setCurrentUser(updated);
              await dbService.saveRecord(updated);
              setShowAddModal(null);
              runSchemeAnalysis(pId);
            }} className="space-y-10">
              <div className="space-y-3">
                <label className="text-[11px] font-black uppercase text-slate-400 ml-4 tracking-widest">Medical Descriptor</label>
                <input name="condition" required className="w-full bg-slate-50 border-2 border-slate-100 rounded-[2rem] px-10 py-6 text-lg font-bold outline-none focus:border-indigo-500" placeholder="e.g. Type 2 Diabetes" />
              </div>
              <div className="space-y-3">
                <label className="text-[11px] font-black uppercase text-slate-400 ml-4 tracking-widest">Clinical Severity</label>
                <select name="severity" className="w-full bg-slate-50 border-2 border-slate-100 rounded-[2rem] px-10 py-6 text-lg font-bold outline-none appearance-none cursor-pointer">
                  <option value="mild">Mild Maintenance</option>
                  <option value="moderate">Moderate Attention</option>
                  <option value="severe">Severe Critical</option>
                </select>
              </div>
              <button type="submit" className="w-full py-8 bg-indigo-600 text-white rounded-full font-black uppercase tracking-[0.25em] text-sm shadow-2xl transition-all">Publish to Ledger</button>
            </form>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  UserProfile, 
  HealthRecord, 
  ChatMessage, 
  MedicalProblem, 
  Insurance,
  TreatmentNote,
  DoctorAccessLog,
  Surgery,
  Reminder
} from './types';
import { ICONS, APP_NAME, MAX_LOGIN_ATTEMPTS, LOCKOUT_DURATION_MS, OTP_EXPIRY_MS } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord, findApplicableSchemes, generateSmartReminders } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';

type ModalType = 'problem' | 'add_insurance' | 'add_note' | 'doctor_auth' | 'surgery' | 'profile_edit' | null;

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [loginMethod, setLoginMethod] = useState<'healthid' | 'phone'>('healthid');
  const [roleMode, setRoleMode] = useState<'patient' | 'doctor'>('patient');

  const [activeTab, setActiveTab] = useState('dashboard');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');
  const [authError, setAuthError] = useState('');

  const [loginId, setLoginId] = useState('');
  const [phoneInput, setPhoneInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);

  const [loginAttempts, setLoginAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);
  const [activeOtp, setActiveOtp] = useState<{ code: string, expiresAt: number } | null>(null);

  // Search States
  const [patientSearchQuery, setPatientSearchQuery] = useState('');
  const [patientSearchResults, setPatientSearchResults] = useState<HealthRecord[]>([]);
  const [searchedPatient, setSearchedPatient] = useState<HealthRecord | null>(null);
  const [isSearchingPatient, setIsSearchingPatient] = useState(false);
  const [authorizedPatientId, setAuthorizedPatientId] = useState<string | null>(null);
  const [accessOtpInput, setAccessOtpInput] = useState('');

  // AI & Analysis States
  const [isAnalyzingRecord, setIsAnalyzingRecord] = useState<string | null>(null);
  const [isSyncingReminders, setIsSyncingReminders] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', role: 'patient'
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
          setRoleMode(record.profile.role);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (lockoutUntil && Date.now() < lockoutUntil) return;
    setAuthError('');
    setIsSubmitting(true);

    let record: HealthRecord | null = null;
    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
      if (!record || record.profile.role !== roleMode) {
        handleLoginFailure();
        return;
      }
    } else {
      if (!isVerifyingOtp) {
        record = await dbService.getRecordByPhone(phoneInput);
        if (record && record.profile.role === roleMode) {
          const code = Math.floor(1000 + Math.random() * 9000).toString();
          console.log(`[SECURE AUTH] CODE FOR ${phoneInput}: ${code}`);
          setActiveOtp({ code, expiresAt: Date.now() + OTP_EXPIRY_MS });
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
          return;
        } else {
          handleLoginFailure();
          return;
        }
      } else {
        if (activeOtp && otpInput === activeOtp.code) {
          record = await dbService.getRecordByPhone(phoneInput);
        } else {
          handleLoginFailure();
          return;
        }
      }
    }

    if (record) {
      setCurrentUser(record);
      setIsAuth(true);
      localStorage.setItem(SESSION_KEY, record.profile.healthId);
    }
    setIsSubmitting(false);
  };

  const handleLoginFailure = () => {
    const attempts = loginAttempts + 1;
    setLoginAttempts(attempts);
    if (attempts >= MAX_LOGIN_ATTEMPTS) setLockoutUntil(Date.now() + LOCKOUT_DURATION_MS);
    setAuthError(`Verification failed. ${MAX_LOGIN_ATTEMPTS - attempts} attempts left.`);
    setIsSubmitting(false);
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const prefix = roleMode === 'doctor' ? 'DR' : 'HS';
    const healthId = `${prefix}-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.floor(1000 + Math.random() * 9000)}`;
    const newRecord: HealthRecord = {
      profile: { ...regForm, healthId, role: roleMode },
      problems: [], medications: [], surgeries: [], allergies: [], notes: [],
      familyHistory: [], insurances: [], reminders: [], interactions: [], accessHistory: [],
      lastUpdated: Date.now()
    };
    await dbService.saveRecord(newRecord);
    setCurrentUser(newRecord);
    setIsAuth(true);
    localStorage.setItem(SESSION_KEY, healthId);
    setIsSubmitting(false);
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    localStorage.removeItem(SESSION_KEY);
    setActiveTab('dashboard');
  };

  const handleSearchPatient = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSearchingPatient(true);
    const allRecords = await dbService.getAllRecords();
    const results = allRecords.filter(r => 
      r.profile.role === 'patient' && 
      (r.profile.name.toLowerCase().includes(patientSearchQuery.toLowerCase()) || 
       r.profile.healthId.includes(patientSearchQuery.toUpperCase()))
    );
    setPatientSearchResults(results);
    setIsSearchingPatient(false);
  };

  const runSchemeAnalysis = async (problemId: string) => {
    const target = searchedPatient || currentUser;
    if (!target) return;
    const problem = target.problems.find(p => p.id === problemId);
    if (!problem) return;
    setIsAnalyzingRecord(problemId);
    try {
      const schemes = await findApplicableSchemes(problem, target.profile.age);
      const updatedUser = { ...target, problems: target.problems.map(p => p.id === problemId ? { ...p, applicableSchemes: schemes } : p) };
      if (searchedPatient) setSearchedPatient(updatedUser);
      else setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
    } finally { setIsAnalyzingRecord(null); }
  };

  const handleAskAi = async () => {
    const target = searchedPatient || currentUser;
    if (!userQuery.trim() || !target) return;
    setChatHistory(prev => [...prev, { role: 'user', content: userQuery, timestamp: Date.now() }]);
    setIsAiLoading(true);
    try {
      const response = await analyzeHealthRecord(target, userQuery);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    } finally { setIsAiLoading(false); setUserQuery(''); }
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;
    await dbService.saveRecord(currentUser);
    setShowAddModal(null);
  };

  if (isLoading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-slate-950 text-white">
      <div className="w-20 h-20 border-t-4 border-indigo-500 rounded-full animate-spin mb-8 shadow-[0_0_40px_rgba(79,70,229,0.3)]"></div>
      <p className="font-black uppercase tracking-[0.5em] text-[11px] animate-pulse">Initializing Neural Link</p>
    </div>
  );

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-8 bg-slate-950 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-[60vw] h-[60vw] bg-indigo-600/10 blur-[180px] rounded-full -translate-x-1/2 -translate-y-1/2 animate-pulse"></div>
        <div className="absolute bottom-0 right-0 w-[60vw] h-[60vw] bg-purple-600/10 blur-[180px] rounded-full translate-x-1/2 translate-y-1/2 animate-pulse"></div>

        <div className="w-full max-w-2xl relative z-10">
          <div className="glass-dark rounded-[5rem] p-20 shadow-2xl animate-pop-in border-t border-white/10">
            <div className="text-center mb-16">
              <div className="w-28 h-28 bg-gradient-to-br from-indigo-500 to-indigo-800 rounded-[3rem] flex items-center justify-center text-5xl text-white mx-auto mb-10 shadow-[0_20px_60px_-15px_rgba(79,70,229,0.5)] transform hover:rotate-6 transition-transform">
                {ICONS.LOCK}
              </div>
              <h1 className="text-5xl font-black text-white tracking-tighter mb-4">{APP_NAME}</h1>
              <p className="text-slate-400 text-lg font-medium opacity-80">Quantum-Secured Medical Data Architecture</p>
            </div>

            <div className="flex bg-white/5 p-2 rounded-[2.5rem] mb-12 border border-white/5">
              <button onClick={() => setRoleMode('patient')} className={`flex-1 py-5 rounded-[2rem] text-[11px] font-black uppercase tracking-[0.2em] transition-all ${roleMode === 'patient' ? 'bg-indigo-600 text-white shadow-2xl' : 'text-slate-500 hover:text-slate-300'}`}>Patient Terminal</button>
              <button onClick={() => setRoleMode('doctor')} className={`flex-1 py-5 rounded-[2rem] text-[11px] font-black uppercase tracking-[0.2em] transition-all ${roleMode === 'doctor' ? 'bg-indigo-600 text-white shadow-2xl' : 'text-slate-500 hover:text-slate-300'}`}>Medical Officer</button>
            </div>

            <div className="flex bg-white/5 p-2 rounded-3xl mb-10 border border-white/5">
              <button onClick={() => setAuthMode('login')} className={`flex-1 py-4 rounded-2xl text-[11px] font-black uppercase transition-all ${authMode === 'login' ? 'bg-white/10 text-white shadow-lg' : 'text-slate-500'}`}>Access Portal</button>
              <button onClick={() => setAuthMode('register')} className={`flex-1 py-4 rounded-2xl text-[11px] font-black uppercase transition-all ${authMode === 'register' ? 'bg-white/10 text-white shadow-lg' : 'text-slate-500'}`}>Register Node</button>
            </div>

            {authMode === 'login' ? (
              <form onSubmit={handleLogin} className="space-y-8">
                <div className="flex bg-white/5 p-2 rounded-2xl mb-8 border border-white/5">
                  <button type="button" onClick={() => setLoginMethod('healthid')} className={`flex-1 py-4 rounded-xl text-[11px] font-black uppercase transition-all ${loginMethod === 'healthid' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Health ID</button>
                  <button type="button" onClick={() => setLoginMethod('phone')} className={`flex-1 py-4 rounded-xl text-[11px] font-black uppercase transition-all ${loginMethod === 'phone' ? 'bg-white/10 text-white' : 'text-slate-500'}`}>Smart Link</button>
                </div>

                {loginMethod === 'healthid' ? (
                  <input required placeholder={roleMode === 'doctor' ? "DR-XXXX-XXXX" : "HS-XXXX-XXXX"} className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] px-10 py-7 text-xl text-white font-mono uppercase focus:ring-4 focus:ring-indigo-500/20 outline-none transition-all placeholder:text-white/20" value={loginId} onChange={e => setLoginId(e.target.value)} />
                ) : (
                  <div className="space-y-8">
                    {!isVerifyingOtp ? (
                      <input required type="tel" placeholder="+91 XXXXX XXXXX" className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] px-10 py-7 text-xl text-white outline-none focus:ring-4 focus:ring-indigo-500/20 transition-all" value={phoneInput} onChange={e => setPhoneInput(e.target.value)} />
                    ) : (
                      <div className="space-y-8 animate-slide-in">
                        <p className="text-center text-[11px] font-black uppercase text-indigo-400 tracking-[0.4em]">Biometric Access Token</p>
                        <input required maxLength={4} className="w-full bg-white/5 border border-white/10 rounded-[3rem] py-12 text-7xl font-black tracking-[0.5em] text-center text-white outline-none focus:ring-4 focus:ring-indigo-500/20" value={otpInput} onChange={e => setOtpInput(e.target.value.replace(/\D/g, ''))} />
                      </div>
                    )}
                  </div>
                )}
                {authError && <p className="text-red-400 text-[11px] font-black uppercase tracking-widest text-center bg-red-500/10 py-4 rounded-2xl border border-red-500/20">{authError}</p>}
                <button type="submit" disabled={isSubmitting} className="w-full py-8 rounded-full bg-indigo-600 hover:bg-indigo-500 text-white font-black uppercase tracking-[0.3em] text-sm shadow-[0_20px_40px_-10px_rgba(79,70,229,0.5)] active:scale-95 transition-all">
                  {isSubmitting ? 'Verifying Integrity...' : 'Establish Secure Link'}
                </button>
              </form>
            ) : (
              <form onSubmit={handleRegister} className="space-y-6 animate-slide-in">
                <input required placeholder="Legal Entity Name" className="w-full bg-white/5 border border-white/10 rounded-[2rem] px-8 py-6 text-white text-lg outline-none focus:ring-2 focus:ring-indigo-500" onChange={e => setRegForm({...regForm, name: e.target.value})} />
                <div className="grid grid-cols-2 gap-6">
                  <input required type="number" placeholder="Age" className="w-full bg-white/5 border border-white/10 rounded-[2rem] px-8 py-6 text-white text-lg outline-none focus:ring-2 focus:ring-indigo-500" onChange={e => setRegForm({...regForm, age: parseInt(e.target.value)})} />
                  <select className="w-full bg-slate-900 border border-white/10 rounded-[2rem] px-8 py-6 text-white text-lg outline-none cursor-pointer" onChange={e => setRegForm({...regForm, bloodGroup: e.target.value})}>
                    {['A+', 'B+', 'O+', 'AB+', 'A-', 'B-', 'O-', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                  </select>
                </div>
                <input required type="tel" placeholder="Secure Contact Number" className="w-full bg-white/5 border border-white/10 rounded-[2rem] px-8 py-6 text-white text-lg outline-none" onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                <button type="submit" disabled={isSubmitting} className="w-full py-8 rounded-full bg-indigo-600 hover:bg-indigo-500 text-white font-black uppercase tracking-[0.3em] text-sm shadow-2xl active:scale-95 transition-all">Create Encrypted Node</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  const activeDisplayUser = searchedPatient || currentUser;

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      userName={currentUser?.profile.name || ''} 
      healthId={currentUser?.profile.healthId || ''}
      role={roleMode}
      profilePicture={currentUser?.profile.profilePicture}
      onLogout={handleLogout}
    >
      <div className="max-w-7xl mx-auto space-y-16 animate-pop-in pb-24">
        {/* Universal Header Stat Panel */}
        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            <div className="lg:col-span-3 space-y-12">
              <div className="bg-slate-950 rounded-[5rem] p-16 text-white shadow-3xl relative overflow-hidden group border border-white/5">
                <div className="absolute top-0 right-0 p-16 opacity-[0.05] group-hover:scale-110 transition-transform duration-1000"><i className="fas fa-microchip text-[20rem]"></i></div>
                <div className="relative z-10 flex flex-col md:flex-row justify-between md:items-center gap-12">
                  <div className="flex items-center gap-12">
                    <div className="w-40 h-40 rounded-[4rem] bg-white/5 border border-white/10 flex items-center justify-center shrink-0 overflow-hidden shadow-[0_0_60px_rgba(255,255,255,0.05)]">
                       {currentUser?.profile.profilePicture ? (
                         <img src={currentUser.profile.profilePicture} alt="" className="w-full h-full object-cover" />
                       ) : (
                         <i className="fas fa-fingerprint text-6xl text-indigo-400"></i>
                       )}
                    </div>
                    <div>
                      <p className="text-indigo-400 text-[11px] font-black uppercase tracking-[0.5em] mb-4">Authenticated Operator</p>
                      <h3 className="text-6xl font-black tracking-tighter leading-none mb-4">{currentUser?.profile.name}</h3>
                      <div className="flex items-center gap-4">
                        <span className="px-4 py-2 bg-indigo-500/10 rounded-xl text-indigo-300 font-mono text-sm tracking-widest border border-indigo-500/20">{currentUser?.profile.healthId}</span>
                        {roleMode === 'doctor' && <span className="px-4 py-2 bg-emerald-500/10 rounded-xl text-emerald-300 font-black text-[10px] uppercase tracking-widest border border-emerald-500/20">Medical Specialist</span>}
                      </div>
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-6 shrink-0">
                    <div className="bg-white/5 p-6 rounded-[2rem] border border-white/10 text-center backdrop-blur-md">
                      <span className="text-[10px] font-black text-indigo-400 uppercase block mb-2 tracking-widest">Bio-Age</span>
                      <p className="text-2xl font-black">{currentUser?.profile.age} <span className="text-sm opacity-40">YR</span></p>
                    </div>
                    <div className="bg-white/5 p-6 rounded-[2rem] border border-white/10 text-center backdrop-blur-md">
                      <span className="text-[10px] font-black text-indigo-400 uppercase block mb-2 tracking-widest">Hemogroup</span>
                      <p className="text-2xl font-black">{currentUser?.profile.bloodGroup}</p>
                    </div>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <RecordCard title="Smart Health Timeline" icon={<i className="fas fa-stream"></i>}>
                  <div className="space-y-6">
                    {currentUser?.reminders?.length ? currentUser.reminders.slice(0, 3).map(r => (
                      <div key={r.id} className="p-8 bg-slate-50 rounded-[3rem] border border-slate-100 flex items-center justify-between hover:border-indigo-200 transition-all shadow-sm">
                        <div>
                          <p className="font-black text-slate-800 uppercase text-xs tracking-tight">{r.title}</p>
                          <p className="text-[10px] font-bold text-slate-400 uppercase mt-2 tracking-widest"><i className="far fa-clock mr-2"></i> {r.time}</p>
                        </div>
                        <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-slate-200 shadow-inner group-hover:text-emerald-500 transition-colors cursor-pointer">
                           <i className="fas fa-check-circle text-2xl"></i>
                        </div>
                      </div>
