                           {['A+', 'B+', 'O+', 'AB+', 'A-', 'B-', 'O-', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                        </select>
                      </div>
                      <div className="space-y-4">
                        <label className="text-[11px] font-black uppercase text-slate-400 ml-6 tracking-widest">Age Record</label>
                        <input type="number" className="w-full bg-slate-50 border-2 border-slate-100 rounded-full px-10 py-6 text-lg font-bold outline-none focus:border-indigo-500" value={currentUser?.profile.age} onChange={e => setCurrentUser(prev => prev ? {...prev, profile: {...prev.profile, age: parseInt(e.target.value)}} : null)} />
                      </div>
                   </div>

                   <div className="pt-12 border-t border-slate-50">
                      <button type="submit" className="w-full py-8 bg-slate-950 text-white rounded-full font-black uppercase tracking-[0.3em] text-sm shadow-3xl hover:bg-indigo-600 transition-all">Update Node Config</button>
                   </div>
                </form>

                <div className="mt-20 pt-16 border-t border-slate-50 flex flex-col md:flex-row justify-between items-center gap-8">
                   <div className="text-center md:text-left">
                      <p className="text-slate-900 font-black uppercase text-xs tracking-widest mb-2">Vault Identifier</p>
                      <p className="text-slate-400 font-mono text-sm uppercase tracking-widest">{currentUser?.profile.healthId}</p>
                   </div>
                   <div className="flex gap-4">
                      <button onClick={handleLogout} className="px-10 py-5 bg-red-50 text-red-600 rounded-full text-[11px] font-black uppercase tracking-widest border border-red-100 shadow-sm hover:bg-red-600 hover:text-white transition-all">Destroy Local Session</button>
                   </div>
                </div>
             </div>
          </div>
        )}
      </div>

      {/* Authorize Access OTP Modal (Visual Match to Request) */}
      {showAddModal === 'doctor_auth' && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-3xl z-[100] flex items-center justify-center p-12">
          <div className="bg-white rounded-[6rem] w-full max-w-2xl p-24 animate-pop-in relative text-center shadow-4xl border border-slate-100">
            <h3 className="text-5xl font-black text-slate-900 tracking-tighter mb-10 leading-none">Patient Authorization</h3>
            <p className="text-slate-500 text-xl mb-16 leading-relaxed px-12 font-medium">A secure token has been sent to the patient's terminal. Enter the 4-digit code to initialize encrypted session access.</p>

            <div className="relative mb-20">
              <div className="flex justify-center items-center gap-12 py-16 border-2 border-indigo-100 rounded-[4.5rem] bg-slate-50 focus-within:border-indigo-500 focus-within:bg-white transition-all shadow-inner">
                {Array.from({ length: 4 }).map((_, i) => (
                  <span key={i} className={`text-8xl font-black transition-all ${accessOtpInput[i] ? 'text-indigo-600 scale-110' : 'text-slate-200'}`}>
                    {accessOtpInput[i] || (i + 1)}
                  </span>
                ))}
              </div>
              <input 
                autoFocus
                type="text" 
                maxLength={4} 
                className="absolute inset-0 opacity-0 cursor-default" 
                value={accessOtpInput} 
                onChange={(e) => {
                  const val = e.target.value.replace(/\D/g, '');
                  if (val.length <= 4) setAccessOtpInput(val);
                }} 
              />
            </div>

            <button 
              onClick={() => {
                if (accessOtpInput.length === 4) {
                  setAuthorizedPatientId(searchedPatient?.profile.healthId || null);
                  setShowAddModal(null);
                  setAccessOtpInput('');
                }
              }} 
              className="w-full bg-indigo-600 text-white py-10 rounded-full font-black uppercase tracking-[0.4em] text-sm shadow-4xl shadow-indigo-600/30 hover:bg-indigo-700 hover:-translate-y-2 active:translate-y-0 transition-all"
            >
              Authorize Access
            </button>
          </div>
        </div>
      )}

      {/* Generic Forms (Problem, Surgery, etc.) */}
      {showAddModal === 'problem' && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-3xl z-[100] flex items-center justify-center p-12">
          <div className="bg-white rounded-[6rem] w-full max-w-3xl p-24 animate-pop-in relative border border-slate-100 shadow-4xl">
            <button onClick={() => setShowAddModal(null)} className="absolute top-12 right-12 w-20 h-20 rounded-full bg-slate-50 text-slate-400 hover:text-slate-900 transition-all text-4xl">&times;</button>
            <h3 className="text-4xl font-black text-slate-900 tracking-tighter mb-16 uppercase leading-none">Record Clinical Condition</h3>
            <form onSubmit={async (e) => {
              e.preventDefault();
              const target = searchedPatient || currentUser;
              if (!target) return;
              const formData = new FormData(e.currentTarget);
              const pId = Date.now().toString();
              const updated = { ...target, problems: [{ id: pId, condition: formData.get('condition') as string, status: 'present', severity: formData.get('severity') as any, onsetDate: new Date().toISOString() }, ...target.problems] };
              if (searchedPatient) setSearchedPatient(updated);
              else setCurrentUser(updated);
              await dbService.saveRecord(updated);
              setShowAddModal(null);
              runSchemeAnalysis(pId);
            }} className="space-y-12">
              <div className="space-y-4">
                <label className="text-[12px] font-black uppercase text-slate-400 ml-8 tracking-[0.3em]">Medical Diagnosis Descriptor</label>
                <input name="condition" required className="w-full bg-slate-50 border-2 border-slate-100 rounded-[3rem] px-12 py-8 text-2xl font-bold outline-none focus:border-indigo-500 focus:bg-white transition-all shadow-inner" placeholder="e.g. Chronic Hypertension" />
              </div>
              <div className="space-y-4">
                <label className="text-[12px] font-black uppercase text-slate-400 ml-8 tracking-[0.3em]">Clinical Urgency Level</label>
                <select name="severity" className="w-full bg-slate-50 border-2 border-slate-100 rounded-[3rem] px-12 py-8 text-2xl font-bold outline-none appearance-none cursor-pointer focus:border-indigo-500">
                  <option value="mild">Level 1: Routine Maintenance</option>
                  <option value="moderate">Level 2: Active Monitoring</option>
                  <option value="severe">Level 3: Critical Priority</option>
                </select>
              </div>
              <button type="submit" className="w-full py-10 bg-slate-950 text-white rounded-full font-black uppercase tracking-[0.4em] text-sm shadow-3xl hover:bg-indigo-600 transition-all mt-8">Commit to Ledger</button>
            </form>
          </div>
        </div>
      )}

      {/* Other modals follow the same pattern... */}
    </Layout>
  );
};

export default App;

