          </div>
          <span className="text-xl font-bold text-slate-900 tracking-tight">{APP_NAME}</span>
        </div>

        <div className="p-4 border-b border-slate-100 bg-slate-50/50">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 rounded-full bg-indigo-100 border border-indigo-200 flex items-center justify-center overflow-hidden">
              {profilePicture ? (
                <img src={profilePicture} alt={userName} className="w-full h-full object-cover" />
              ) : (
                <i className="fas fa-user text-indigo-400"></i>
              )}
            </div>
            <div className="min-w-0">
              <p className="text-sm font-semibold text-slate-900 truncate">{userName}</p>
              <button onClick={handleCopy} className="text-[10px] text-slate-400 flex items-center gap-1 hover:text-indigo-600 transition-colors">
                <span className="truncate">{healthId}</span>
                <i className={`fas ${copied ? 'fa-check text-green-500' : 'fa-copy'}`}></i>
              </button>
            </div>
          </div>
        </div>

        <nav className="flex-grow p-4 space-y-1 overflow-y-auto custom-scrollbar">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${
                activeTab === item.id
                  ? 'bg-indigo-50 text-indigo-700 border border-indigo-100'
                  : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              <span className="text-lg">{item.icon}</span>
              <span>{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-100">
          <button 
            onClick={onLogout}
            className="w-full flex items-center justify-center space-x-2 px-4 py-2.5 text-sm font-semibold text-red-600 hover:bg-red-50 rounded-lg transition-colors border border-transparent hover:border-red-100"
          >
            <span>{ICONS.LOGOUT}</span>
            <span>Sign Out</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-grow flex flex-col min-w-0 h-screen overflow-hidden">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0">
          <h2 className="text-lg font-bold text-slate-800">
            {navItems.find(n => n.id === activeTab)?.label}
          </h2>
          <div className="flex items-center gap-2">
            <div className="flex items-center text-xs font-semibold text-emerald-700 bg-emerald-50 px-3 py-1.5 rounded-full border border-emerald-100">
              <span className="w-2 h-2 bg-emerald-500 rounded-full mr-2"></span>
              Secure Session Active
            </div>
          </div>
        </header>

        <div className="p-8 flex-grow overflow-y-auto custom-scrollbar">
          {children}
        </div>
      </main>
    </div>
  );
};

export default Layout;

import React, { useState, useEffect } from 'react';
import { 
  UserProfile, 
  HealthRecord, 
  ChatMessage, 
  MedicalProblem, 
  NotificationSettings,
  VisitingHours,
  GovernmentScheme,
  AuditLog,
  Medication
} from './types';
import { ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord, findApplicableSchemes } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';

type ModalType = 'problem' | 'add_insurance' | 'doctor_auth' | 'surgery' | 'medication' | null;

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [loginMethod, setLoginMethod] = useState<'healthid' | 'phone'>('healthid');
  const [roleMode, setRoleMode] = useState<'patient' | 'doctor'>('patient');

  const [activeTab, setActiveTab] = useState('dashboard');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');
  const [authError, setAuthError] = useState('');

  const [loginId, setLoginId] = useState('');
  const [phoneInput, setPhoneInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);

  // Search States
  const [patientSearchQuery, setPatientSearchQuery] = useState('');
  const [patientSearchResults, setPatientSearchResults] = useState<HealthRecord[]>([]);
  const [searchedPatient, setSearchedPatient] = useState<HealthRecord | null>(null);
  const [isSearchingPatient, setIsSearchingPatient] = useState(false);
  const [authorizedPatientId, setAuthorizedPatientId] = useState<string | null>(null);
  const [accessOtpInput, setAccessOtpInput] = useState('');

  // AI & Schemes States
  const [isAnalyzingRecord, setIsAnalyzingRecord] = useState<string | null>(null);
  const [isSearchingSchemes, setIsSearchingSchemes] = useState(false);
  const [generalSchemes, setGeneralSchemes] = useState<GovernmentScheme[]>([]);
  const [userQuery, setUserQuery] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', role: 'patient',
    notificationSettings: { email: true, sms: true, push: true, sound: true },
    visitingHours: { start: '09:00', end: '17:00', days: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'] }
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
          setRoleMode(record.profile.role);
          loadGeneralSchemes(record.profile.age);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  const loadGeneralSchemes = async (age: number) => {
    setIsSearchingSchemes(true);
    const schemes = await findApplicableSchemes(null, age);
    setGeneralSchemes(schemes);
    setIsSearchingSchemes(false);
  };

  const createAuditLog = (action: AuditLog['action'], resource: string, details: string): AuditLog => ({
    id: `LOG-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`.toUpperCase(),
    doctorId: currentUser?.profile.healthId || 'SYSTEM',
    doctorName: currentUser?.profile.name || 'System Operator',
    action,
    resource,
    details,
    timestamp: Date.now()
  });

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    setIsSubmitting(true);

    let record: HealthRecord | null = null;
    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
      if (!record || record.profile.role !== roleMode) {
        setAuthError("Invalid Health ID or Role mismatch.");
        setIsSubmitting(false);
        return;
      }
    } else {
      if (!isVerifyingOtp) {
        record = await dbService.getRecordByPhone(phoneInput);
        if (record && record.profile.role === roleMode) {
          const code = Math.floor(1000 + Math.random() * 9000).toString();
          console.log(`[AUTH CODE]: ${code}`);
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
          return;
        } else {
          setAuthError("Phone number not registered.");
          setIsSubmitting(false);
          return;
        }
      } else {
        record = await dbService.getRecordByPhone(phoneInput);
      }
    }

    if (record) {
      setCurrentUser(record);
      setIsAuth(true);
      localStorage.setItem(SESSION_KEY, record.profile.healthId);
      loadGeneralSchemes(record.profile.age);
    }
    setIsSubmitting(false);
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const prefix = roleMode === 'doctor' ? 'DR' : 'HS';
    const healthId = `${prefix}-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.floor(1000 + Math.random() * 9000)}`;
    const newRecord: HealthRecord = {
      profile: { ...regForm, healthId, role: roleMode },
      problems: [], medications: [], surgeries: [], allergies: [], notes: [],
      familyHistory: [], insurances: [], reminders: [], lastUpdated: Date.now(),
      auditLogs: []
    };
    await dbService.saveRecord(newRecord);
    setCurrentUser(newRecord);
    setIsAuth(true);
    localStorage.setItem(SESSION_KEY, healthId);
    loadGeneralSchemes(newRecord.profile.age);
    setIsSubmitting(false);
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    localStorage.removeItem(SESSION_KEY);
    setActiveTab('dashboard');
  };

  const handleSearchPatient = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSearchingPatient(true);
    const allRecords = await dbService.getAllRecords();
    const results = allRecords.filter(r => 
      r.profile.role === 'patient' && 
      (r.profile.name.toLowerCase().includes(patientSearchQuery.toLowerCase()) || 
       r.profile.healthId.includes(patientSearchQuery.toUpperCase()))
    );
    setPatientSearchResults(results);
    setIsSearchingPatient(false);
  };

  const runSchemeAnalysis = async (problemId: string) => {
    const target = searchedPatient || currentUser;
    if (!target) return;
    const problem = target.problems.find(p => p.id === problemId);
    if (!problem) return;
    setIsAnalyzingRecord(problemId);
    try {
      const schemes = await findApplicableSchemes(problem, target.profile.age);
      const updatedUser = { ...target, problems: target.problems.map(p => p.id === problemId ? { ...p, applicableSchemes: schemes } : p) };
      if (searchedPatient) setSearchedPatient(updatedUser);
      else setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
    } finally { setIsAnalyzingRecord(null); }
  };

  const handleAskAi = async () => {
    const target = searchedPatient || currentUser;
    if (!userQuery.trim() || !target) return;
    setChatHistory(prev => [...prev, { role: 'user', content: userQuery, timestamp: Date.now() }]);
    setIsAiLoading(true);
    try {
      const response = await analyzeHealthRecord(target, userQuery);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    } finally { setIsAiLoading(false); setUserQuery(''); }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setRegForm({ ...regForm, profilePicture: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const updateNotificationSetting = (key: keyof NotificationSettings) => {
    if (!currentUser) return;
    const settings = currentUser.profile.notificationSettings || { email: true, sms: true, push: true, sound: true };
    const updated = { ...currentUser, profile: { ...currentUser.profile, notificationSettings: { ...settings, [key]: !settings[key] } } };
    setCurrentUser(updated);
    dbService.saveRecord(updated);
  };

  const updateVisitingHours = (field: keyof VisitingHours, value: any) => {
    if (!currentUser) return;
    const vh = currentUser.profile.visitingHours || { start: '09:00', end: '17:00', days: [] };
    const updated = { ...currentUser, profile: { ...currentUser.profile, visitingHours: { ...vh, [field]: value } } };
    setCurrentUser(updated);
    dbService.saveRecord(updated);
  };

  const toggleVisitingDay = (day: string) => {
    if (!currentUser) return;
    const vh = currentUser.profile.visitingHours || { start: '09:00', end: '17:00', days: [] };
    const days = vh.days.includes(day) ? vh.days.filter(d => d !== day) : [...vh.days, day];
    updateVisitingHours('days', days);
  };

  if (isLoading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
      <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
    </div>
  );

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-100 p-6">
        <div className="w-full max-w-md bg-white rounded-2xl shadow-xl p-8 border border-slate-200 animate-fade-in">
          <div className="text-center mb-8">
            <div className="w-16 h-16 bg-indigo-600 rounded-xl flex items-center justify-center text-3xl text-white mx-auto mb-4 shadow-lg">
              {ICONS.LOCK}
            </div>
            <h1 className="text-2xl font-bold text-slate-900">{APP_NAME}</h1>
            <p className="text-slate-500 text-sm mt-1">Secure Medical Records Access</p>
          </div>

          <div className="flex bg-slate-100 p-1 rounded-lg mb-6">
            <button onClick={() => setRoleMode('patient')} className={`flex-1 py-2 text-xs font-bold uppercase rounded-md transition-all ${roleMode === 'patient' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Patient</button>
            <button onClick={() => setRoleMode('doctor')} className={`flex-1 py-2 text-xs font-bold uppercase rounded-md transition-all ${roleMode === 'doctor' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Doctor</button>
          </div>

          <div className="flex justify-center space-x-6 mb-6 text-sm">
            <button onClick={() => setAuthMode('login')} className={`font-bold pb-1 border-b-2 transition-all ${authMode === 'login' ? 'text-indigo-600 border-indigo-600' : 'text-slate-400 border-transparent'}`}>Login</button>
            <button onClick={() => setAuthMode('register')} className={`font-bold pb-1 border-b-2 transition-all ${authMode === 'register' ? 'text-indigo-600 border-indigo-600' : 'text-slate-400 border-transparent'}`}>Sign Up</button>
          </div>

          {authMode === 'login' ? (
            <form onSubmit={handleLogin} className="space-y-4">
              <div className="flex bg-slate-100 p-1 rounded-lg mb-4">
                <button type="button" onClick={() => setLoginMethod('healthid')} className={`flex-1 py-1.5 text-[10px] font-bold uppercase rounded transition-all ${loginMethod === 'healthid' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Health ID</button>
                <button type="button" onClick={() => setLoginMethod('phone')} className={`flex-1 py-1.5 text-[10px] font-bold uppercase rounded transition-all ${loginMethod === 'phone' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Phone</button>
              </div>

              {loginMethod === 'healthid' ? (
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Health ID</label>
                  <input required placeholder={roleMode === 'doctor' ? "DR-XXXX-XXXX" : "HS-XXXX-XXXX"} className="w-full border border-slate-200 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all" value={loginId} onChange={e => setLoginId(e.target.value.toUpperCase())} />
                </div>
              ) : (
                <div className="space-y-4">
                  {!isVerifyingOtp ? (
                    <div className="space-y-1">
                      <label className="text-xs font-bold text-slate-500 uppercase ml-1">Phone Number</label>
                      <input required type="tel" placeholder="+91 XXXXX XXXXX" className="w-full border border-slate-200 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={phoneInput} onChange={e => setPhoneInput(e.target.value)} />
                    </div>
                  ) : (
                    <div className="space-y-2 text-center animate-fade-in">
                      <label className="text-xs font-bold text-slate-500 uppercase block mb-2">Access Token</label>
                      <input required maxLength={4} className="w-full border-2 border-indigo-200 rounded-lg py-4 text-3xl font-bold tracking-widest text-center text-indigo-700 outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={otpInput} onChange={e => setOtpInput(e.target.value.replace(/\D/g, ''))} />
                      <p className="text-[10px] text-slate-400">Sent via SMS secure link</p>
                    </div>
                  )}
                </div>
              )}
              {authError && <p className="text-red-500 text-xs font-bold text-center">{authError}</p>}
              <button type="submit" disabled={isSubmitting} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-lg shadow-md transition-all active:scale-95">
                {isSubmitting ? 'Verifying...' : (isVerifyingOtp ? 'Login' : 'Access Portal')}
              </button>
            </form>
          ) : (
            <form onSubmit={handleRegister} className="space-y-4 animate-fade-in">
              <div className="flex flex-col items-center mb-4">
                <label className="w-20 h-20 rounded-full bg-slate-100 border-2 border-dashed border-slate-300 flex flex-col items-center justify-center cursor-pointer hover:bg-slate-200 transition-all overflow-hidden relative">
                  {regForm.profilePicture ? (
                    <img src={regForm.profilePicture} alt="Preview" className="w-full h-full object-cover" />
                  ) : (
                    <>
                      <i className="fas fa-camera text-slate-400 mb-1"></i>
                      <span className="text-[10px] text-slate-400 font-bold">Photo</span>
                    </>
                  )}
                  <input type="file" className="hidden" accept="image/*" onChange={handleFileChange} />
                </label>
              </div>
              <input required placeholder="Legal Name" className="w-full border border-slate-200 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500" onChange={e => setRegForm({...regForm, name: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                <input required type="number" placeholder="Age" className="w-full border border-slate-200 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500" onChange={e => setRegForm({...regForm, age: parseInt(e.target.value)})} />
                <select className="w-full border border-slate-200 rounded-lg px-4 py-2.5 outline-none bg-white cursor-pointer" onChange={e => setRegForm({...regForm, bloodGroup: e.target.value})}>
                  {['A+', 'B+', 'O+', 'AB+', 'A-', 'B-', 'O-', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                </select>
              </div>
              <input required type="tel" placeholder="Phone Number" className="w-full border border-slate-200 rounded-lg px-4 py-2.5 outline-none" onChange={e => setRegForm({...regForm, phone: e.target.value})} />
              <button type="submit" disabled={isSubmitting} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-lg shadow-md transition-all">Create Account</button>
            </form>
          )}
        </div>
      </div>
    );
  }

  const activeDisplayUser = searchedPatient || currentUser;

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      userName={currentUser?.profile.name || ''} 
      healthId={currentUser?.profile.healthId || ''}
      role={roleMode}
      profilePicture={currentUser?.profile.profilePicture}
      onLogout={handleLogout}
    >
      <div className="space-y-12 animate-fade-in pb-16">
        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-8 space-y-8">
              <div className="bg-white rounded-2xl p-8 border border-slate-200 shadow-sm flex items-center gap-8">
                <div className="w-28 h-28 rounded-full bg-slate-50 border-4 border-white shadow-md flex items-center justify-center overflow-hidden">
                   {currentUser?.profile.profilePicture ? (
                     <img src={currentUser.profile.profilePicture} alt="" className="w-full h-full object-cover" />
                   ) : (
                     <i className="fas fa-user text-5xl text-slate-200"></i>
                   )}
                </div>
                <div>
                  <h3 className="text-3xl font-bold text-slate-900">{currentUser?.profile.name}</h3>
                  <div className="flex flex-wrap gap-4 mt-3">
                    <span className="text-xs font-bold text-slate-500 bg-slate-100 px-4 py-1.5 rounded-full uppercase tracking-wider">{currentUser?.profile.healthId}</span>
                    <span className="text-xs font-bold text-slate-500 bg-slate-100 px-4 py-1.5 rounded-full uppercase tracking-wider">{currentUser?.profile.age} Yrs</span>
                    {currentUser?.profile.role === 'doctor' && (
                      <span className="text-xs font-bold text-emerald-600 bg-emerald-50 px-4 py-1.5 rounded-full uppercase tracking-wider border border-emerald-100">Professional</span>
                    )}
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <RecordCard title="Clinical Snapshot" icon={ICONS.MEDICAL}>
                  <div className="space-y-4">
                    {currentUser?.problems.slice(0, 3).map(p => (
                      <div key={p.id} className="p-4 bg-slate-50 rounded-xl border border-slate-100 flex justify-between items-center transition-all hover:bg-slate-100">
                        <span className="text-sm font-bold text-slate-800">{p.condition}</span>
                        <span className={`text-[10px] font-black uppercase px-2 py-1 rounded ${p.severity === 'severe' ? 'text-red-600' : 'text-slate-400'}`}>{p.severity}</span>
                      </div>
                    ))}
                    {!currentUser?.problems.length && <p className="text-xs text-slate-400 italic py-4">No active conditions logged in your vault.</p>}
                  </div>
                </RecordCard>

                {currentUser?.profile.role === 'doctor' ? (
                  <RecordCard title="Operating Hours" icon={<i className="fas fa-clock"></i>}>
                    <div className="space-y-4">
                      <div className="flex items-center gap-4">
                         <div className="w-12 h-12 rounded-full bg-indigo-50 flex items-center justify-center text-indigo-600">
                            <i className="fas fa-business-time"></i>
                         </div>
                         <div>
                            <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">Session Availability</p>
                            <p className="text-lg font-bold text-slate-800">{currentUser.profile.visitingHours?.start} — {currentUser.profile.visitingHours?.end}</p>
                         </div>
                      </div>
                      <div className="flex flex-wrap gap-2 pt-2">
                        {currentUser.profile.visitingHours?.days.map(d => (
                          <span key={d} className="text-[10px] font-bold px-3 py-1 bg-indigo-50 text-indigo-700 rounded-lg border border-indigo-100 uppercase">{d}</span>
                        ))}
                      </div>
                    </div>
                  </RecordCard>
                ) : (
                  <RecordCard title="Access Audit Ledger" icon={<i className="fas fa-user-shield"></i>}>
                     <div className="space-y-4">
                       {currentUser?.auditLogs?.slice(0, 3).map(log => (
                         <div key={log.id} className="p-4 bg-slate-50 rounded-xl border border-slate-100">
                            <p className="text-[9px] font-black uppercase text-indigo-600 mb-1">{log.action} • {new Date(log.timestamp).toLocaleTimeString()}</p>
                            <p className="text-xs font-bold text-slate-800">{log.doctorName} accessed {log.resource}</p>
                         </div>
                       ))}
                       {!currentUser?.auditLogs?.length && <p className="text-xs text-slate-400 italic py-4">No recent security events.</p>}
                       {currentUser?.auditLogs && currentUser.auditLogs.length > 0 && (
                         <button onClick={() => setActiveTab('audit')} className="text-[10px] font-black uppercase text-indigo-600 hover:underline">View All Security Logs</button>
                       )}
                     </div>
                  </RecordCard>
                )}
              </div>
            </div>

            <div className="lg:col-span-4">
               <RecordCard title="Shield AI Intelligence" icon={ICONS.AI} className="h-full">
                  <div className="space-y-6">
                    <div className="p-5 bg-indigo-50 border border-indigo-100 rounded-2xl">
                       <p className="text-xs font-bold text-indigo-900 leading-relaxed mb-4">Shield AI analyzes your clinical ledger and matches you with real-time government welfare benefits.</p>
                       <div className="flex items-center gap-3 text-[10px] font-black uppercase text-indigo-400 tracking-widest">
                          <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                          Neural Core Active
                       </div>
                    </div>
                    <button onClick={() => setActiveTab('shield')} className="w-full py-4 bg-slate-900 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-slate-800 transition-all active:scale-95">
                       Open Analysis Console
                    </button>
                  </div>
               </RecordCard>
            </div>
          </div>
        )}

        {activeTab === 'audit' && (
          <div className="max-w-4xl mx-auto space-y-8">
            <div className="bg-slate-900 text-white p-12 rounded-[3rem] shadow-2xl relative overflow-hidden">
               <div className="absolute top-0 right-0 p-12 opacity-10"><i className="fas fa-user-shield text-[10rem]"></i></div>
               <h3 className="text-4xl font-black tracking-tighter mb-4 uppercase">Security Audit Ledger</h3>
               <p className="text-slate-400 text-lg font-medium opacity-80">Transparent record of all medical professionals who have interacted with your clinical data vault.</p>
            </div>

            <div className="space-y-6">
               {currentUser?.auditLogs?.sort((a,b) => b.timestamp - a.timestamp).map(log => (
                 <div key={log.id} className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm flex items-center justify-between">
                    <div className="flex items-center gap-6">
                       <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${log.action === 'VIEW' ? 'bg-blue-50 text-blue-600' : 'bg-amber-50 text-amber-600'}`}>
                          <i className={`fas ${log.action === 'VIEW' ? 'fa-eye' : 'fa-edit'}`}></i>
                       </div>
                       <div>
                          <p className="text-sm font-black text-slate-800 uppercase tracking-tight">{log.doctorName} <span className="text-slate-400 font-mono text-[10px] ml-2">({log.doctorId})</span></p>
                          <p className="text-xs text-slate-500 font-medium">{log.details}</p>
                       </div>
                    </div>
                    <div className="text-right">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{new Date(log.timestamp).toLocaleDateString()}</p>
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{new Date(log.timestamp).toLocaleTimeString()}</p>
                    </div>
                 </div>
               ))}
               {!currentUser?.auditLogs?.length && (
                 <div className="py-20 text-center bg-white rounded-3xl border-2 border-dashed border-slate-100">
                    <p className="text-slate-300 font-black uppercase tracking-widest text-xs">No audit events generated yet</p>
                 </div>
               )}
            </div>
          </div>
        )}

        {activeTab === 'search' && roleMode === 'doctor' && (
          <div className="max-w-6xl mx-auto space-y-10">
            <div className="bg-white rounded-3xl p-12 shadow-2xl border border-slate-100 text-center">
              <h3 className="text-4xl font-black text-slate-900 mb-8 uppercase tracking-tighter leading-none">Global Patient Index</h3>
              <form onSubmit={handleSearchPatient} className="max-w-3xl mx-auto relative group">
                <i className="fas fa-search absolute left-8 top-1/2 -translate-y-1/2 text-slate-300 text-xl transition-colors group-focus-within:text-indigo-600"></i>
                <input 
                  className="w-full bg-slate-50 border-2 border-slate-100 rounded-full pl-16 pr-8 py-6 text-xl font-bold placeholder:text-slate-300 focus:border-indigo-500 focus:bg-white outline-none transition-all shadow-inner" 
                  placeholder="Query Name or Health ID..." 
                  value={patientSearchQuery} 
                  onChange={e => setPatientSearchQuery(e.target.value)} 
                />
                <button type="submit" disabled={isSearchingPatient} className="absolute right-3 top-1/2 -translate-y-1/2 px-10 py-4 bg-slate-950 text-white rounded-full font-black uppercase tracking-widest text-xs hover:bg-indigo-600 transition-all">
                  {isSearchingPatient ? <i className="fas fa-circle-notch animate-spin"></i> : 'Execute'}
                </button>
              </form>

              {patientSearchResults.length > 0 && (
                <div className="mt-16 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 text-left animate-slide-in">
                  {patientSearchResults.map(patient => (
                    <div key={patient.profile.healthId} className="bg-white border border-slate-100 rounded-3xl p-8 hover:shadow-2xl hover:-translate-y-2 transition-all flex flex-col items-center text-center">
                      <div className="w-20 h-20 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center mb-6 overflow-hidden">
                        {patient.profile.profilePicture ? <img src={patient.profile.profilePicture} className="w-full h-full object-cover" /> : <i className="fas fa-user-ninja text-2xl text-slate-200"></i>}
                      </div>
                      <h4 className="text-xl font-bold text-slate-900 mb-1">{patient.profile.name}</h4>
                      <p className="text-[11px] font-mono text-slate-400 uppercase tracking-widest mb-8">{patient.profile.healthId}</p>
                      <button 
                        onClick={() => { setSearchedPatient(patient); setShowAddModal('doctor_auth'); }}
                        className="w-full py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black uppercase tracking-widest text-[10px] text-slate-600 hover:bg-indigo-600 hover:text-white hover:border-indigo-600 transition-all"
                      >
                        Request Token Access
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {searchedPatient && authorizedPatientId === searchedPatient.profile.healthId && (
              <div className="space-y-10 animate-fade-in">
                <div className="bg-emerald-50 border-2 border-emerald-100 rounded-3xl p-10 flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-8">
                     <div className="w-16 h-16 bg-white rounded-2xl shadow-xl flex items-center justify-center text-emerald-600 border border-emerald-100 shrink-0">
                        <i className="fas fa-unlock-alt text-2xl"></i>
                     </div>
                     <div>
                       <h4 className="text-3xl font-black text-emerald-900 tracking-tight leading-none mb-2">{searchedPatient.profile.name}</h4>
                       <p className="text-xs font-bold text-emerald-600 uppercase tracking-widest opacity-80">Clinical Assets Unlocked</p>
                     </div>
                  </div>
                  <button onClick={() => { setSearchedPatient(null); setAuthorizedPatientId(null); }} className="bg-white border-2 border-emerald-200 text-emerald-700 px-10 py-4 rounded-full font-black uppercase text-xs tracking-widest hover:bg-emerald-600 hover:text-white hover:border-emerald-600 transition-all">Close Secure Tunnel</button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                  <RecordCard title="Patient Clinical History" icon={ICONS.MEDICAL}>
                    <div className="space-y-6">
                       {searchedPatient.problems.map(p => (
                         <div key={p.id} className="p-6 border border-slate-100 rounded-2xl bg-slate-50 group hover:bg-white hover:shadow-lg transition-all">
                            <div className="flex justify-between items-start mb-4">
                              <h4 className="text-lg font-bold text-slate-900 leading-tight uppercase tracking-tight">{p.condition}</h4>
                              <span className={`text-[10px] font-black uppercase px-3 py-1 rounded-lg ${p.severity === 'severe' ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>{p.severity}</span>
                            </div>
                            <div className="flex items-center gap-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                               <span><i className="fas fa-history mr-2"></i> Onset: {new Date(p.onsetDate).toLocaleDateString()}</span>
                               <button onClick={() => runSchemeAnalysis(p.id)} className="ml-auto text-indigo-600 hover:underline">Match Govt Benefits</button>
                            </div>
                         </div>
                       ))}
                       {!searchedPatient.problems.length && <div className="text-center py-16 text-slate-300 text-xs italic">Clear clinical record.</div>}
                    </div>
                  </RecordCard>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'records' && (
          <div className="max-w-5xl mx-auto space-y-10">
            <div className="flex flex-col md:flex-row justify-between items-center gap-6 bg-white rounded-3xl p-6 border border-slate-100 shadow-sm">
              <div className="flex bg-slate-100 p-1.5 rounded-2xl w-full md:w-auto border border-slate-200 shadow-inner">
                <button onClick={() => setRecordFilter('present')} className={`flex-1 md:flex-none px-10 py-4 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${recordFilter === 'present' ? 'bg-white text-indigo-700 shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}>Active Vault</button>
                <button onClick={() => setRecordFilter('past')} className={`flex-1 md:flex-none px-10 py-4 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${recordFilter === 'past' ? 'bg-white text-indigo-700 shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}>Historical Log</button>
              </div>
              <div className="flex gap-4">
                 <button onClick={() => setShowAddModal('problem')} className="px-6 py-3 bg-slate-950 text-white rounded-xl font-black uppercase tracking-widest text-[9px] hover:bg-indigo-600 transition-all shadow-xl">Archive Condition</button>
                 <button onClick={() => setShowAddModal('medication')} className="px-6 py-3 bg-indigo-600 text-white rounded-xl font-black uppercase tracking-widest text-[9px] hover:bg-indigo-700 transition-all shadow-xl">Log Medication</button>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <RecordCard title="Medical Ledger" icon={ICONS.MEDICAL} isLoading={!!isAnalyzingRecord} loadingMessage="Querying Central Welfare Database...">
                <div className="space-y-6">
                  {activeDisplayUser?.problems.filter(p => recordFilter === 'present' ? p.status === 'present' : p.status !== 'present').map(p => (
                    <div key={p.id} className="p-8 border border-slate-100 rounded-3xl bg-slate-50/50 hover:bg-white hover:shadow-2xl transition-all relative overflow-hidden group">
                       <div className="absolute top-0 right-0 p-6 opacity-0 group-hover:opacity-10 transition-opacity"><i className="fas fa-dna text-4xl"></i></div>
                       <div className="flex justify-between items-start mb-6">
                         <h4 className="text-xl font-bold text-slate-900 uppercase tracking-tight leading-tight">{p.condition}</h4>
                         <span className={`text-[10px] font-black uppercase px-3 py-1 rounded-lg ${p.severity === 'severe' ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-emerald-50 text-emerald-600 border border-emerald-100'}`}>{p.severity}</span>
                       </div>
                       <div className="flex items-center gap-4">
                        <button onClick={() => runSchemeAnalysis(p.id)} className="text-[10px] font-black text-indigo-600 hover:text-indigo-800 uppercase tracking-widest flex items-center gap-2 bg-indigo-50 px-4 py-2 rounded-xl border border-indigo-100 transition-all">
                          <i className="fas fa-search-dollar"></i> Map Govt Benefits
                        </button>
                        <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest ml-auto">{new Date(p.onsetDate).toLocaleDateString()}</span>
                       </div>
                    </div>
                  ))}
                  {!activeDisplayUser?.problems.length && <div className="text-center py-24 bg-slate-50/50 rounded-3xl border-2 border-dashed border-slate-100 text-slate-300 font-black uppercase tracking-widest text-xs">Ledger Clear</div>}
                </div>
              </RecordCard>

              <RecordCard title="Medication Vault" icon={ICONS.MEDS}>
                <div className="space-y-6">
                   {activeDisplayUser?.medications.filter(m => recordFilter === 'present' ? m.status === 'active' : m.status !== 'active').map(m => (
                     <div key={m.id} className="p-8 border border-slate-100 rounded-3xl bg-white shadow-sm hover:shadow-xl transition-all">
                        <div className="flex justify-between items-center mb-6">
                           <h4 className="text-xl font-bold text-slate-900 uppercase tracking-tighter leading-none">{m.name}</h4>
                           <span className={`text-[9px] font-black uppercase px-2 py-1 rounded ${m.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-slate-50 text-slate-400'}`}>{m.status}</span>
                        </div>
                        <div className="grid grid-cols-2 gap-6 pt-4 border-t border-slate-50">
                           <div><span className="text-[9px] font-black uppercase text-slate-300 block mb-1">Dosage</span><p className="text-sm font-bold text-slate-700">{m.dosage}</p></div>
                           <div><span className="text-[9px] font-black uppercase text-slate-300 block mb-1">Frequency</span><p className="text-sm font-bold text-slate-700">{m.frequency}</p></div>
                           <div className="col-span-2"><span className="text-[9px] font-black uppercase text-slate-300 block mb-1">Duration</span><p className="text-xs font-semibold text-slate-500">{m.duration}</p></div>
                        </div>
                     </div>
                   ))}
                   {!activeDisplayUser?.medications.length && <div className="text-center py-24 bg-slate-50/50 rounded-3xl border-2 border-dashed border-slate-100 text-slate-300 font-black uppercase tracking-widest text-xs">No Medications Logged</div>}
                </div>
              </RecordCard>
            </div>
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="max-w-4xl mx-auto space-y-12 animate-fade-in">
             <div className="bg-white rounded-[3rem] p-16 shadow-3xl border border-slate-100">
                <h3 className="text-3xl font-black text-slate-900 tracking-tighter mb-12 uppercase leading-none">Vault Configuration</h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-10 mb-16">
                   <div className="space-y-3">
                     <label className="text-[10px] font-black uppercase text-slate-400 ml-4 tracking-widest">Display Node Name</label>
                     <input className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-sm font-bold outline-none focus:border-indigo-500" value={currentUser?.profile.name} onChange={e => setCurrentUser(prev => prev ? {...prev, profile: {...prev.profile, name: e.target.value}} : null)} />
                   </div>
                   <div className="space-y-3">
                     <label className="text-[10px] font-black uppercase text-slate-400 ml-4 tracking-widest">Communication Link</label>
                     <input className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-sm font-bold outline-none focus:border-indigo-500" value={currentUser?.profile.phone} onChange={e => setCurrentUser(prev => prev ? {...prev, profile: {...prev.profile, phone: e.target.value}} : null)} />
                   </div>
                </div>

                <div className="space-y-8">
                   <h4 className="text-[11px] font-black uppercase text-slate-400 tracking-[0.3em] border-b border-slate-50 pb-4">Notification Protocols</h4>
                   <div className="grid grid-cols-2 sm:grid-cols-4 gap-6">
                      {(['email', 'sms', 'push', 'sound'] as const).map(key => (
                        <button 
                          key={key}
                          onClick={() => updateNotificationSetting(key)}
                          className={`flex flex-col items-center justify-center p-6 rounded-3xl border-2 transition-all ${
                            currentUser?.profile.notificationSettings?.[key]
                              ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl shadow-indigo-600/20'
                              : 'bg-white border-slate-100 text-slate-300'
                          }`}
                        >
                          <i className={`fas ${key === 'email' ? 'fa-envelope' : key === 'sms' ? 'fa-comment' : key === 'push' ? 'fa-mobile' : 'fa-volume-up'} text-xl mb-3`}></i>
                          <span className="text-[9px] font-black uppercase tracking-widest">{key}</span>
                        </button>
                      ))}
                   </div>
                </div>

                <div className="mt-20 pt-12 border-t border-slate-50 flex flex-col md:flex-row justify-between items-center gap-8">
                   <div className="text-center md:text-left">
                      <p className="text-slate-900 font-black uppercase text-[10px] tracking-widest mb-1">Authenticated Node ID</p>
                      <p className="text-slate-400 font-mono text-xs uppercase tracking-widest">{currentUser?.profile.healthId}</p>
                   </div>
                   <button onClick={handleLogout} className="px-10 py-4 bg-red-50 text-red-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-red-100 shadow-sm hover:bg-red-600 hover:text-white transition-all">Destroy Local Session</button>
                </div>
             </div>
          </div>
        )}

        {activeTab === 'shield' && (
          <div className="max-w-4xl mx-auto h-[calc(100vh-16rem)] bg-white rounded-[4rem] shadow-3xl border border-slate-100 overflow-hidden flex flex-col animate-fade-in">
            <div className="p-10 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 bg-indigo-600 rounded-[2rem] flex items-center justify-center text-white text-2xl shadow-xl">{ICONS.AI}</div>
                <div><h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter leading-none mb-1">Shield Intelligence Console</h3><p className="text-[10px] text-indigo-500 font-black uppercase tracking-widest">Neural Analysis Active</p></div>
              </div>
            </div>
            <div className="flex-grow overflow-y-auto p-10 space-y-8 custom-scrollbar bg-slate-50/10">
              {chatHistory.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center p-16 opacity-30">
                  <i className="fas fa-brain text-7xl text-slate-200 mb-8"></i>
                  <p className="text-lg font-black text-slate-400 uppercase tracking-widest">Neural Link Offline</p>
                  <p className="text-xs font-medium text-slate-300 mt-2">Query clinical history or welfare pathways.</p>
                </div>
              )}
              {chatHistory.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-8 rounded-[3rem] shadow-xl ${m.role === 'user' ? 'bg-slate-950 text-white rounded-tr-none' : 'bg-white border border-slate-100 text-slate-800 rounded-tl-none'}`}>
                    <p className="text-sm font-medium whitespace-pre-wrap leading-relaxed opacity-90">{m.content}</p>
                    <div className={`mt-4 pt-3 border-t ${m.role === 'user' ? 'border-white/10' : 'border-slate-50'} text-[8px] font-black uppercase tracking-widest opacity-40 text-right`}>
                       {m.role === 'user' ? 'Operator' : 'AI'} • {new Date(m.timestamp).toLocaleTimeString()}
                    </div>
                  </div>
                </div>
              ))}
              {isAiLoading && (
                <div className="p-6 bg-white border border-slate-100 rounded-3xl w-fit shadow-xl flex items-center gap-4">
                  <div className="flex space-x-1.5">
                    <div className="w-2.5 h-2.5 bg-indigo-600 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                    <div className="w-2.5 h-2.5 bg-indigo-600 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                    <div className="w-2.5 h-2.5 bg-indigo-600 rounded-full animate-bounce"></div>
                  </div>
                </div>
              )}
            </div>
            <div className="p-10 border-t border-slate-100 bg-white">
              <div className="bg-slate-100 rounded-full p-2.5 flex items-center border border-slate-200/50 shadow-inner">
                <input className="flex-grow bg-transparent outline-none px-8 py-4 text-sm font-bold placeholder:text-slate-300" placeholder="Ask about clinical conditions or welfare matches..." value={userQuery} onChange={(e) => setUserQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleAskAi()} />
                <button onClick={handleAskAi} disabled={isAiLoading} className="w-16 h-16 bg-slate-950 text-white rounded-full flex items-center justify-center shadow-xl disabled:opacity-50 hover:bg-indigo-600 transition-all active:scale-95">
                  {isAiLoading ? <i className="fas fa-circle-notch animate-spin"></i> : <i className="fas fa-paper-plane text-xl"></i>}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Patient Auth OTP Modal */}
      {showAddModal === 'doctor_auth' && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-8">
          <div className="bg-white rounded-[4rem] w-full max-w-xl p-20 animate-fade-in relative text-center shadow-4xl border border-slate-100">
            <h3 className="text-3xl font-black text-slate-900 tracking-tighter mb-8 leading-none">Authorization Token</h3>
            <p className="text-slate-500 text-sm mb-12 leading-relaxed px-12">Enter the 4-digit cryptographic token generated by the patient's mobile terminal to initialize secure access.</p>
            <div className="relative mb-16">
              <input 
                autoFocus
                type="text" 
                maxLength={4} 
                className="w-full border-2 border-indigo-100 rounded-3xl py-12 text-7xl font-black tracking-[0.5em] text-center text-indigo-700 outline-none focus:ring-4 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all shadow-inner" 
                value={accessOtpInput} 
                onChange={(e) => setAccessOtpInput(e.target.value.replace(/\D/g, ''))} 
              />
            </div>
            <button 
              onClick={async () => {
                if (accessOtpInput.length === 4 && searchedPatient) {
                  const auditLog = createAuditLog('VIEW', 'Complete Medical Vault', `Doctor initialized secure session via token verification.`);
                  const updatedPatient = {
                    ...searchedPatient,
                    auditLogs: [auditLog, ...(searchedPatient.auditLogs || [])]
                  };
                  await dbService.saveRecord(updatedPatient);
                  setSearchedPatient(updatedPatient);
                  setAuthorizedPatientId(searchedPatient.profile.healthId);
                  setShowAddModal(null);
                  setAccessOtpInput('');
                }
              }} 
              className="w-full bg-indigo-600 text-white py-6 rounded-full font-black uppercase tracking-[0.3em] text-xs shadow-3xl shadow-indigo-600/30 hover:bg-indigo-700 hover:-translate-y-1 transition-all"
            >
              Verify & Establish Link
            </button>
            <button onClick={() => setShowAddModal(null)} className="mt-8 text-[10px] text-slate-300 font-black uppercase tracking-widest hover:text-slate-600 transition-colors">Abort Procedure</button>
          </div>
        </div>
      )}

      {/* Medication Modal */}
      {showAddModal === 'medication' && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-3xl z-[100] flex items-center justify-center p-8">
          <div className="bg-white rounded-[4rem] w-full max-w-2xl p-20 animate-fade-in relative border border-slate-100 shadow-4xl max-h-[90vh] overflow-y-auto custom-scrollbar">
            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 w-12 h-12 rounded-full bg-slate-50 text-slate-300 hover:text-slate-900 transition-all text-2xl flex items-center justify-center">&times;</button>
            <h3 className="text-3xl font-black text-slate-900 tracking-tighter mb-12 uppercase leading-none">Prescription Entry</h3>
            <form onSubmit={async (e) => {
              e.preventDefault();
              const target = searchedPatient || currentUser;
              if (!target) return;
              const formData = new FormData(e.currentTarget);
              const mId = `MED-${Date.now()}`;

              const newMed: Medication = {
                id: mId,
                name: formData.get('name') as string,
                dosage: formData.get('dosage') as string,
                frequency: formData.get('frequency') as string,
                duration: formData.get('duration') as string,
                startDate: formData.get('startDate') as string || new Date().toISOString(),
                status: formData.get('status') as any,
                prescribedBy: roleMode === 'doctor' ? currentUser?.profile.name : 'Self-Log'
              };

              let updated = { ...target, medications: [newMed, ...(target.medications || [])] };

              if (roleMode === 'doctor') {
                 const auditLog = createAuditLog('CREATE', `Medication: ${newMed.name}`, `Medical professional added a new medication prescription.`);
                 updated = { ...updated, auditLogs: [auditLog, ...(updated.auditLogs || [])] };
              }

              if (searchedPatient) setSearchedPatient(updated);
              else setCurrentUser(updated);

              await dbService.saveRecord(updated);
              setShowAddModal(null);
            }} className="space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Medication Name</label>
                  <input required name="name" placeholder="e.g. Metformin 500mg" className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl px-6 py-4 text-sm font-bold outline-none focus:border-indigo-500" />
                </div>
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Dosage</label>
                  <input required name="dosage" placeholder="e.g. 1 Tablet" className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl px-6 py-4 text-sm font-bold outline-none focus:border-indigo-500" />
                </div>
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Frequency</label>
                  <select name="frequency" className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl px-6 py-4 text-sm font-bold outline-none cursor-pointer">
                    <option value="Once daily (OD)">Once daily (OD)</option>
                    <option value="Twice daily (BD)">Twice daily (BD)</option>
                    <option value="Three times daily (TD)">Three times daily (TD)</option>
                    <option value="Four times daily (QD)">Four times daily (QD)</option>
                    <option value="As needed (PRN)">As needed (PRN)</option>
                  </select>
                </div>
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Duration</label>
                  <input name="duration" placeholder="e.g. 14 Days" className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl px-6 py-4 text-sm font-bold outline-none focus:border-indigo-500" />
                </div>
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Start Date</label>
                  <input type="date" name="startDate" defaultValue={new Date().toISOString().split('T')[0]} className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl px-6 py-4 text-sm font-bold outline-none" />
                </div>
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Current Status</label>
                  <select name="status" className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl px-6 py-4 text-sm font-bold outline-none cursor-pointer">
                    <option value="active">Active Intake</option>
                    <option value="discontinued">Discontinued</option>
                  </select>
                </div>
              </div>
              <button className="w-full py-6 bg-slate-950 text-white rounded-full font-black uppercase tracking-[0.4em] text-xs shadow-3xl hover:bg-indigo-600 transition-all mt-6">Commit to Prescription Ledger</button>
            </form>
          </div>
        </div>
      )}

      {/* Basic Record Modal */}
      {showAddModal === 'problem' && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-3xl z-[100] flex items-center justify-center p-8">
          <div className="bg-white rounded-[4rem] w-full max-w-2xl p-20 animate-fade-in relative border border-slate-100 shadow-4xl">
            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 w-12 h-12 rounded-full bg-slate-50 text-slate-300 hover:text-slate-900 transition-all text-2xl flex items-center justify-center">&times;</button>
            <h3 className="text-3xl font-black text-slate-900 tracking-tighter mb-16 uppercase leading-none">Archive Condition Node</h3>
            <form onSubmit={async (e) => {
              e.preventDefault();
              const target = searchedPatient || currentUser;
              if (!target) return;
              const formData = new FormData(e.currentTarget);
              const pId = Date.now().toString();
              const condition = formData.get('condition') as string;
              const severity = formData.get('severity') as any;

              const newProb: MedicalProblem = {
                id: pId,
                condition,
                severity,
                status: 'present',
                onsetDate: new Date().toISOString()
              };

              let updated = { ...target, problems: [newProb, ...target.problems] };

              if (roleMode === 'doctor') {
                 const auditLog = createAuditLog('CREATE', `Condition: ${condition}`, `Medical professional added a new clinical diagnosis to the ledger.`);
                 updated = { ...updated, auditLogs: [auditLog, ...(updated.auditLogs || [])] };
              }

              if (searchedPatient) setSearchedPatient(updated);
              else setCurrentUser(updated);

              await dbService.saveRecord(updated);
              setShowAddModal(null);
              runSchemeAnalysis(pId);
            }} className="space-y-10">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Clinical Diagnosis</label>
                <input required name="condition" placeholder="e.g. Type 2 Diabetes Mellitus" className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl px-8 py-5 text-xl font-bold outline-none focus:border-indigo-500 focus:bg-white transition-all shadow-inner" />
              </div>
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Clinical Severity Priority</label>
                <select name="severity" className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl px-8 py-5 text-xl font-bold outline-none appearance-none cursor-pointer focus:border-indigo-500">
                  <option value="mild">Level 1: Routine</option>
                  <option value="moderate">Level 2: Active</option>
                  <option value="severe">Level 3: Critical</option>
                </select>
              </div>
              <button className="w-full py-7 bg-slate-950 text-white rounded-full font-black uppercase tracking-[0.4em] text-xs shadow-3xl hover:bg-indigo-600 transition-all mt-8">Commit to Vault</button>
            </form>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

export interface VisitingHours {
  start: string; // HH:mm
  end: string;   // HH:mm
  days: string[]; // ['Mon', 'Tue', ...]
}

export interface NotificationSettings {
  email: boolean;
  sms: boolean;
  push: boolean;
  sound: boolean;
}

export interface GovernmentScheme {
  id: string;
  name: string;
  benefits: string;
  eligibility: string;
  coverageAmount?: string;
  matchReason?: string;
  officialLink?: string;
  officialSources?: { title: string; uri: string }[];
  requiredDocuments?: string[];
  applicationSteps?: string[];
}

export interface Insurance {
  id: string;
  provider: string;
  policyNumber: string;
  coverageAmount: string;
  expiryDate: string;
  policyType: 'Individual' | 'Family Floater' | 'Critical Illness';
  contactPhone: string;
  status: 'active' | 'expired';
}

export interface Reminder {
  id: string;
  title: string;
  description: string;
  time?: string; // HH:mm
  date?: string; // YYYY-MM-DD
  type: 'medication' | 'followup' | 'lifestyle' | 'custom';
  status: 'pending' | 'completed';
}

export interface AuditLog {
  id: string;
  doctorId: string;
  doctorName: string;
  action: 'VIEW' | 'CREATE' | 'UPDATE' | 'DELETE';
  resource: string;
  details: string;
  timestamp: number;
}

export interface UserProfile {
  name: string;
  age: number;
  dob: string;
  gender: string;
  phone: string;
  aadhaar: string;
  healthId: string;
  bloodGroup: string;
  role: 'patient' | 'doctor';
  profilePicture?: string; // Base64 encoded string
  specialization?: string;
  licenseNumber?: string;
  emergencyContactName?: string;
  emergencyContactPhone?: string;
  isPremium?: boolean;
  subscriptionPlan?: 'standard' | 'pro' | 'family';
  subscriptionExpiry?: string;
  visitingHours?: VisitingHours;
  notificationSettings?: NotificationSettings;
}

export interface MedicalProblem {
  id: string;
  condition: string;
  status: 'past' | 'present' | 'recovered';
  isChronic?: boolean;
  onsetDate: string;
  endDate?: string;
  severity: 'mild' | 'moderate' | 'severe';
  treatment?: string;
  notes?: string;
  applicableSchemes?: GovernmentScheme[];
  treatmentProvider?: string;
  prescriptionDetails?: string;
}

export interface Medication {
  id: string;
  name: string;
  dosage: string;
  duration: string;
  frequency: string;
  startDate: string;
  instructions?: string;
  prescribedBy?: string;
  status: 'active' | 'discontinued';
}

export interface Surgery {
  id: string;
  type: string;
  date: string;
  hospital: string;
  surgeon: string;
  outcome?: string;
}

export interface Allergy {
  id: string;
  substance: string;
  severity: 'low' | 'moderate' | 'high';
  reaction?: string;
  firstObserved?: string;
}

export interface TreatmentNote {
  id: string;
  doctorName: string;
  date: string;
  note: string;
  clinicName?: string;
  category?: 'Consultation' | 'Follow-up' | 'Emergency' | 'Surgery';
}

export interface FamilyHistory {
  id: string;
  relation: string;
  condition: string;
  notableNotes?: string;
}

export interface Interaction {
  id: string;
  query: string;
  response: string;
  timestamp: number;
}

export interface DoctorAccessLog {
  patientHealthId: string;
  patientName: string;
  timestamp: number;
}

export interface HealthRecord {
  profile: UserProfile;
  problems: MedicalProblem[];
  medications: Medication[];
  surgeries: Surgery[];
  allergies: Allergy[];
  notes: TreatmentNote[];
  familyHistory: FamilyHistory[];
  insurances?: Insurance[];
  reminders?: Reminder[];
  interactions?: Interaction[];
  accessHistory?: DoctorAccessLog[];
  auditLogs?: AuditLog[];
  lastUpdated?: number;
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
}

import React, { useState, useEffect } from 'react';
import { 
  UserProfile, 
  HealthRecord, 
  ChatMessage, 
  MedicalProblem, 
  NotificationSettings,
  VisitingHours,
  GovernmentScheme,
  AuditLog,
  Medication,
  Reminder
} from './types';
import { ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord, findApplicableSchemes } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';

type ModalType = 'problem' | 'add_insurance' | 'doctor_auth' | 'surgery' | 'medication' | 'reminder' | null;

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [loginMethod, setLoginMethod] = useState<'healthid' | 'phone'>('healthid');
  const [roleMode, setRoleMode] = useState<'patient' | 'doctor'>('patient');

  const [activeTab, setActiveTab] = useState('dashboard');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');
  const [authError, setAuthError] = useState('');

  const [loginId, setLoginId] = useState('');
  const [phoneInput, setPhoneInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);

  // Search States
  const [patientSearchQuery, setPatientSearchQuery] = useState('');
  const [patientSearchResults, setPatientSearchResults] = useState<HealthRecord[]>([]);
  const [searchedPatient, setSearchedPatient] = useState<HealthRecord | null>(null);
  const [isSearchingPatient, setIsSearchingPatient] = useState(false);
  const [authorizedPatientId, setAuthorizedPatientId] = useState<string | null>(null);
  const [accessOtpInput, setAccessOtpInput] = useState('');

  // AI & Schemes States
  const [isAnalyzingRecord, setIsAnalyzingRecord] = useState<string | null>(null);
  const [isSearchingSchemes, setIsSearchingSchemes] = useState(false);
  const [generalSchemes, setGeneralSchemes] = useState<GovernmentScheme[]>([]);
  const [userQuery, setUserQuery] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', role: 'patient',
    notificationSettings: { email: true, sms: true, push: true, sound: true },
    visitingHours: { start: '09:00', end: '17:00', days: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'] }
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
          setRoleMode(record.profile.role);
          loadGeneralSchemes(record.profile.age);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  const loadGeneralSchemes = async (age: number) => {
    setIsSearchingSchemes(true);
    const schemes = await findApplicableSchemes(null, age);
    setGeneralSchemes(schemes);
    setIsSearchingSchemes(false);
  };

  const createAuditLog = (action: AuditLog['action'], resource: string, details: string): AuditLog => ({
    id: `LOG-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`.toUpperCase(),
    doctorId: currentUser?.profile.healthId || 'SYSTEM',
    doctorName: currentUser?.profile.name || 'System Operator',
    action,
    resource,
    details,
    timestamp: Date.now()
  });

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    setIsSubmitting(true);

    let record: HealthRecord | null = null;
    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
      if (!record || record.profile.role !== roleMode) {
        setAuthError("Invalid Health ID or Role mismatch.");
        setIsSubmitting(false);
        return;
      }
    } else {
      if (!isVerifyingOtp) {
        record = await dbService.getRecordByPhone(phoneInput);
        if (record && record.profile.role === roleMode) {
          const code = Math.floor(1000 + Math.random() * 9000).toString();
          console.log(`[AUTH CODE]: ${code}`);
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
          return;
        } else {
          setAuthError("Phone number not registered.");
          setIsSubmitting(false);
          return;
        }
      } else {
        record = await dbService.getRecordByPhone(phoneInput);
      }
    }

    if (record) {
      setCurrentUser(record);
      setIsAuth(true);
      localStorage.setItem(SESSION_KEY, record.profile.healthId);
      loadGeneralSchemes(record.profile.age);
    }
    setIsSubmitting(false);
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const prefix = roleMode === 'doctor' ? 'DR' : 'HS';
    const healthId = `${prefix}-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.floor(1000 + Math.random() * 9000)}`;
    const newRecord: HealthRecord = {
      profile: { ...regForm, healthId, role: roleMode },
      problems: [], medications: [], surgeries: [], allergies: [], notes: [],
      familyHistory: [], insurances: [], reminders: [], lastUpdated: Date.now(),
      auditLogs: []
    };
    await dbService.saveRecord(newRecord);
    setCurrentUser(newRecord);
    setIsAuth(true);
    localStorage.setItem(SESSION_KEY, healthId);
    loadGeneralSchemes(newRecord.profile.age);
    setIsSubmitting(false);
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    localStorage.removeItem(SESSION_KEY);
    setActiveTab('dashboard');
  };

  const handleSearchPatient = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSearchingPatient(true);
    const allRecords = await dbService.getAllRecords();
    const results = allRecords.filter(r => 
      r.profile.role === 'patient' && 
      (r.profile.name.toLowerCase().includes(patientSearchQuery.toLowerCase()) || 
       r.profile.healthId.includes(patientSearchQuery.toUpperCase()))
    );
    setPatientSearchResults(results);
    setIsSearchingPatient(false);
  };

  const runSchemeAnalysis = async (problemId: string) => {
    const target = searchedPatient || currentUser;
    if (!target) return;
    const problem = target.problems.find(p => p.id === problemId);
    if (!problem) return;
    setIsAnalyzingRecord(problemId);
    try {
      const schemes = await findApplicableSchemes(problem, target.profile.age);
      const updatedUser = { ...target, problems: target.problems.map(p => p.id === problemId ? { ...p, applicableSchemes: schemes } : p) };
      if (searchedPatient) setSearchedPatient(updatedUser);
      else setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
    } finally { setIsAnalyzingRecord(null); }
  };

  const handleAskAi = async () => {
    const target = searchedPatient || currentUser;
    if (!userQuery.trim() || !target) return;
    setChatHistory(prev => [...prev, { role: 'user', content: userQuery, timestamp: Date.now() }]);
    setIsAiLoading(true);
    try {
      const response = await analyzeHealthRecord(target, userQuery);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    } finally { setIsAiLoading(false); setUserQuery(''); }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setRegForm({ ...regForm, profilePicture: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const updateNotificationSetting = (key: keyof NotificationSettings) => {
    if (!currentUser) return;
    const settings = currentUser.profile.notificationSettings || { email: true, sms: true, push: true, sound: true };
    const updated = { ...currentUser, profile: { ...currentUser.profile, notificationSettings: { ...settings, [key]: !settings[key] } } };
    setCurrentUser(updated);
    dbService.saveRecord(updated);
  };

  const updateVisitingHours = (field: keyof VisitingHours, value: any) => {
    if (!currentUser) return;
    const vh = currentUser.profile.visitingHours || { start: '09:00', end: '17:00', days: [] };
    const updated = { ...currentUser, profile: { ...currentUser.profile, visitingHours: { ...vh, [field]: value } } };
    setCurrentUser(updated);
    dbService.saveRecord(updated);
  };

  const toggleVisitingDay = (day: string) => {
    if (!currentUser) return;
    const vh = currentUser.profile.visitingHours || { start: '09:00', end: '17:00', days: [] };
    const days = vh.days.includes(day) ? vh.days.filter(d => d !== day) : [...vh.days, day];
    updateVisitingHours('days', days);
  };

  if (isLoading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
      <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
    </div>
  );

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-100 p-6">
        <div className="w-full max-w-md bg-white rounded-2xl shadow-xl p-8 border border-slate-200 animate-fade-in">
          <div className="text-center mb-8">
            <div className="w-16 h-16 bg-indigo-600 rounded-xl flex items-center justify-center text-3xl text-white mx-auto mb-4 shadow-lg">
              {ICONS.LOCK}
            </div>
            <h1 className="text-2xl font-bold text-slate-900">{APP_NAME}</h1>
            <p className="text-slate-500 text-sm mt-1">Secure Medical Records Access</p>
          </div>

          <div className="flex bg-slate-100 p-1 rounded-lg mb-6">
            <button onClick={() => setRoleMode('patient')} className={`flex-1 py-2 text-xs font-bold uppercase rounded-md transition-all ${roleMode === 'patient' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Patient</button>
            <button onClick={() => setRoleMode('doctor')} className={`flex-1 py-2 text-xs font-bold uppercase rounded-md transition-all ${roleMode === 'doctor' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Doctor</button>
          </div>

          <div className="flex justify-center space-x-6 mb-6 text-sm">
            <button onClick={() => setAuthMode('login')} className={`font-bold pb-1 border-b-2 transition-all ${authMode === 'login' ? 'text-indigo-600 border-indigo-600' : 'text-slate-400 border-transparent'}`}>Login</button>
            <button onClick={() => setAuthMode('register')} className={`font-bold pb-1 border-b-2 transition-all ${authMode === 'register' ? 'text-indigo-600 border-indigo-600' : 'text-slate-400 border-transparent'}`}>Sign Up</button>
          </div>

          {authMode === 'login' ? (
            <form onSubmit={handleLogin} className="space-y-4">
              <div className="flex bg-slate-100 p-1 rounded-lg mb-4">
                <button type="button" onClick={() => setLoginMethod('healthid')} className={`flex-1 py-1.5 text-[10px] font-bold uppercase rounded transition-all ${loginMethod === 'healthid' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Health ID</button>
                <button type="button" onClick={() => setLoginMethod('phone')} className={`flex-1 py-1.5 text-[10px] font-bold uppercase rounded transition-all ${loginMethod === 'phone' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Phone</button>
              </div>

              {loginMethod === 'healthid' ? (
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Health ID</label>
                  <input required placeholder={roleMode === 'doctor' ? "DR-XXXX-XXXX" : "HS-XXXX-XXXX"} className="w-full border border-slate-200 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all" value={loginId} onChange={e => setLoginId(e.target.value.toUpperCase())} />
                </div>
              ) : (
                <div className="space-y-4">
                  {!isVerifyingOtp ? (
                    <div className="space-y-1">
                      <label className="text-xs font-bold text-slate-500 uppercase ml-1">Phone Number</label>
                      <input required type="tel" placeholder="+91 XXXXX XXXXX" className="w-full border border-slate-200 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={phoneInput} onChange={e => setPhoneInput(e.target.value)} />
                    </div>
                  ) : (
                    <div className="space-y-2 text-center animate-fade-in">
                      <label className="text-xs font-bold text-slate-500 uppercase block mb-2">Access Token</label>
                      <input required maxLength={4} className="w-full border-2 border-indigo-200 rounded-lg py-4 text-3xl font-bold tracking-widest text-center text-indigo-700 outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={otpInput} onChange={e => setOtpInput(e.target.value.replace(/\D/g, ''))} />
                      <p className="text-[10px] text-slate-400">Sent via SMS secure link</p>
                    </div>
                  )}
                </div>
              )}
              {authError && <p className="text-red-500 text-xs font-bold text-center">{authError}</p>}
              <button type="submit" disabled={isSubmitting} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-lg shadow-md transition-all active:scale-95">
                {isSubmitting ? 'Verifying...' : (isVerifyingOtp ? 'Login' : 'Access Portal')}
              </button>
            </form>
          ) : (
            <form onSubmit={handleRegister} className="space-y-4 animate-fade-in">
              <div className="flex flex-col items-center mb-4">
                <label className="w-20 h-20 rounded-full bg-slate-100 border-2 border-dashed border-slate-300 flex flex-col items-center justify-center cursor-pointer hover:bg-slate-200 transition-all overflow-hidden relative">
                  {regForm.profilePicture ? (
                    <img src={regForm.profilePicture} alt="Preview" className="w-full h-full object-cover" />
                  ) : (
                    <>
                      <i className="fas fa-camera text-slate-400 mb-1"></i>
                      <span className="text-[10px] text-slate-400 font-bold">Photo</span>
                    </>
                  )}
                  <input type="file" className="hidden" accept="image/*" onChange={handleFileChange} />
                </label>
              </div>
              <input required placeholder="Legal Name" className="w-full border border-slate-200 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500" onChange={e => setRegForm({...regForm, name: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                <input required type="number" placeholder="Age" className="w-full border border-slate-200 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500" onChange={e => setRegForm({...regForm, age: parseInt(e.target.value)})} />
                <select className="w-full border border-slate-200 rounded-lg px-4 py-2.5 outline-none bg-white cursor-pointer" onChange={e => setRegForm({...regForm, bloodGroup: e.target.value})}>
                  {['A+', 'B+', 'O+', 'AB+', 'A-', 'B-', 'O-', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                </select>
              </div>
              <input required type="tel" placeholder="Phone Number" className="w-full border border-slate-200 rounded-lg px-4 py-2.5 outline-none" onChange={e => setRegForm({...regForm, phone: e.target.value})} />
              <button type="submit" disabled={isSubmitting} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-lg shadow-md transition-all">Create Account</button>
            </form>
          )}
        </div>
      </div>
    );
  }

  const activeDisplayUser = searchedPatient || currentUser;

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      userName={currentUser?.profile.name || ''} 
      healthId={currentUser?.profile.healthId || ''}
      role={roleMode}
      profilePicture={currentUser?.profile.profilePicture}
      onLogout={handleLogout}
    >
      <div className="space-y-12 animate-fade-in pb-16">
        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-8 space-y-8">
              <div className="bg-white rounded-2xl p-8 border border-slate-200 shadow-sm flex items-center gap-8">
                <div className="w-28 h-28 rounded-full bg-slate-50 border-4 border-white shadow-md flex items-center justify-center overflow-hidden">
                   {currentUser?.profile.profilePicture ? (
                     <img src={currentUser.profile.profilePicture} alt="" className="w-full h-full object-cover" />
                   ) : (
                     <i className="fas fa-user text-5xl text-slate-200"></i>
                   )}
                </div>
                <div>
                  <h3 className="text-3xl font-bold text-slate-900">{currentUser?.profile.name}</h3>
                  <div className="flex flex-wrap gap-4 mt-3">
                    <span className="text-xs font-bold text-slate-500 bg-slate-100 px-4 py-1.5 rounded-full uppercase tracking-wider">{currentUser?.profile.healthId}</span>
                    <span className="text-xs font-bold text-slate-500 bg-slate-100 px-4 py-1.5 rounded-full uppercase tracking-wider">{currentUser?.profile.age} Yrs</span>
                    {currentUser?.profile.role === 'doctor' && (
                      <span className="text-xs font-bold text-emerald-600 bg-emerald-50 px-4 py-1.5 rounded-full uppercase tracking-wider border border-emerald-100">Professional</span>
                    )}
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <RecordCard title="Clinical Snapshot" icon={ICONS.MEDICAL}>
                  <div className="space-y-4">
                    {currentUser?.problems.slice(0, 3).map(p => (
                      <div key={p.id} className="p-4 bg-slate-50 rounded-xl border border-slate-100 flex justify-between items-center transition-all hover:bg-slate-100">
                        <span className="text-sm font-bold text-slate-800">{p.condition}</span>
                        <span className={`text-[10px] font-black uppercase px-2 py-1 rounded ${p.severity === 'severe' ? 'text-red-600' : 'text-slate-400'}`}>{p.severity}</span>
                      </div>
                    ))}
                    {!currentUser?.problems.length && <p className="text-xs text-slate-400 italic py-4">No active conditions logged in your vault.</p>}
                  </div>
                </RecordCard>

                {currentUser?.profile.role === 'doctor' ? (
                  <RecordCard title="Operating Hours" icon={<i className="fas fa-clock"></i>}>
                    <div className="space-y-4">
                      <div className="flex items-center gap-4">
                         <div className="w-12 h-12 rounded-full bg-indigo-50 flex items-center justify-center text-indigo-600">
                            <i className="fas fa-business-time"></i>
                         </div>
                         <div>
                            <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">Session Availability</p>
                            <p className="text-lg font-bold text-slate-800">{currentUser.profile.visitingHours?.start} — {currentUser.profile.visitingHours?.end}</p>
                         </div>
                      </div>
                      <div className="flex flex-wrap gap-2 pt-2">
                        {currentUser.profile.visitingHours?.days.map(d => (
                          <span key={d} className="text-[10px] font-bold px-3 py-1 bg-indigo-50 text-indigo-700 rounded-lg border border-indigo-100 uppercase">{d}</span>
                        ))}
                      </div>
                    </div>
                  </RecordCard>
                ) : (
                  <RecordCard title="Access Audit Ledger" icon={<i className="fas fa-user-shield"></i>}>
                     <div className="space-y-4">
                       {currentUser?.auditLogs?.slice(0, 3).map(log => (
                         <div key={log.id} className="p-4 bg-slate-50 rounded-xl border border-slate-100">
                            <p className="text-[9px] font-black uppercase text-indigo-600 mb-1">{log.action} • {new Date(log.timestamp).toLocaleTimeString()}</p>
                            <p className="text-xs font-bold text-slate-800">{log.doctorName} accessed {log.resource}</p>
                         </div>
                       ))}
                       {!currentUser?.auditLogs?.length && <p className="text-xs text-slate-400 italic py-4">No recent security events.</p>}
                       {currentUser?.auditLogs && currentUser.auditLogs.length > 0 && (
                         <button onClick={() => setActiveTab('audit')} className="text-[10px] font-black uppercase text-indigo-600 hover:underline">View All Security Logs</button>
                       )}
                     </div>
                  </RecordCard>
                )}
              </div>
            </div>

            <div className="lg:col-span-4">
               <RecordCard title="Shield AI Intelligence" icon={ICONS.AI} className="h-full">
                  <div className="space-y-6">
                    <div className="p-5 bg-indigo-50 border border-indigo-100 rounded-2xl">
                       <p className="text-xs font-bold text-indigo-900 leading-relaxed mb-4">Shield AI analyzes your clinical ledger and matches you with real-time government welfare benefits.</p>
                       <div className="flex items-center gap-3 text-[10px] font-black uppercase text-indigo-400 tracking-widest">
                          <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                          Neural Core Active
                       </div>
                    </div>
                    <button onClick={() => setActiveTab('shield')} className="w-full py-4 bg-slate-900 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-slate-800 transition-all active:scale-95">
                       Open Analysis Console
                    </button>
                  </div>
               </RecordCard>
            </div>
          </div>
        )}

        {activeTab === 'audit' && (
          <div className="max-w-4xl mx-auto space-y-8">
            <div className="bg-slate-900 text-white p-12 rounded-[3rem] shadow-2xl relative overflow-hidden">
               <div className="absolute top-0 right-0 p-12 opacity-10"><i className="fas fa-user-shield text-[10rem]"></i></div>
               <h3 className="text-4xl font-black tracking-tighter mb-4 uppercase">Security Audit Ledger</h3>
               <p className="text-slate-400 text-lg font-medium opacity-80">Transparent record of all medical professionals who have interacted with your clinical data vault.</p>
            </div>

            <div className="space-y-6">
               {currentUser?.auditLogs?.sort((a,b) => b.timestamp - a.timestamp).map(log => (
                 <div key={log.id} className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm flex items-center justify-between">
                    <div className="flex items-center gap-6">
                       <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${log.action === 'VIEW' ? 'bg-blue-50 text-blue-600' : 'bg-amber-50 text-amber-600'}`}>
                          <i className={`fas ${log.action === 'VIEW' ? 'fa-eye' : 'fa-edit'}`}></i>
                       </div>
                       <div>
                          <p className="text-sm font-black text-slate-800 uppercase tracking-tight">{log.doctorName} <span className="text-slate-400 font-mono text-[10px] ml-2">({log.doctorId})</span></p>
                          <p className="text-xs text-slate-500 font-medium">{log.details}</p>
                       </div>
                    </div>
                    <div className="text-right">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{new Date(log.timestamp).toLocaleDateString()}</p>
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{new Date(log.timestamp).toLocaleTimeString()}</p>
                    </div>
                 </div>
               ))}
               {!currentUser?.auditLogs?.length && (
                 <div className="py-20 text-center bg-white rounded-3xl border-2 border-dashed border-slate-100">
                    <p className="text-slate-300 font-black uppercase tracking-widest text-xs">No audit events generated yet</p>
                 </div>
               )}
            </div>
          </div>
        )}

        {activeTab === 'search' && roleMode === 'doctor' && (
          <div className="max-w-6xl mx-auto space-y-10">
            <div className="bg-white rounded-3xl p-12 shadow-2xl border border-slate-100 text-center">
              <h3 className="text-4xl font-black text-slate-900 mb-8 uppercase tracking-tighter leading-none">Global Patient Index</h3>
              <form onSubmit={handleSearchPatient} className="max-w-3xl mx-auto relative group">
                <i className="fas fa-search absolute left-8 top-1/2 -translate-y-1/2 text-slate-300 text-xl transition-colors group-focus-within:text-indigo-600"></i>
                <input 
                  className="w-full bg-slate-50 border-2 border-slate-100 rounded-full pl-16 pr-8 py-6 text-xl font-bold placeholder:text-slate-300 focus:border-indigo-500 focus:bg-white outline-none transition-all shadow-inner" 
                  placeholder="Query Name or Health ID..." 
                  value={patientSearchQuery} 
                  onChange={e => setPatientSearchQuery(e.target.value)} 
                />
                <button type="submit" disabled={isSearchingPatient} className="absolute right-3 top-1/2 -translate-y-1/2 px-10 py-4 bg-slate-950 text-white rounded-full font-black uppercase tracking-widest text-xs hover:bg-indigo-600 transition-all">
                  {isSearchingPatient ? <i className="fas fa-circle-notch animate-spin"></i> : 'Execute'}
                </button>
              </form>

              {patientSearchResults.length > 0 && (
                <div className="mt-16 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 text-left animate-slide-in">
                  {patientSearchResults.map(patient => (
                    <div key={patient.profile.healthId} className="bg-white border border-slate-100 rounded-3xl p-8 hover:shadow-2xl hover:-translate-y-2 transition-all flex flex-col items-center text-center">
                      <div className="w-20 h-20 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center mb-6 overflow-hidden">
                        {patient.profile.profilePicture ? <img src={patient.profile.profilePicture} className="w-full h-full object-cover" /> : <i className="fas fa-user-ninja text-2xl text-slate-200"></i>}
                      </div>
                      <h4 className="text-xl font-bold text-slate-900 mb-1">{patient.profile.name}</h4>
                      <p className="text-[11px] font-mono text-slate-400 uppercase tracking-widest mb-8">{patient.profile.healthId}</p>
                      <button 
                        onClick={() => { setSearchedPatient(patient); setShowAddModal('doctor_auth'); }}
                        className="w-full py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black uppercase tracking-widest text-[10px] text-slate-600 hover:bg-indigo-600 hover:text-white hover:border-indigo-600 transition-all"
                      >
                        Request Token Access
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {searchedPatient && authorizedPatientId === searchedPatient.profile.healthId && (
              <div className="space-y-10 animate-fade-in">
                <div className="bg-emerald-50 border-2 border-emerald-100 rounded-3xl p-10 flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-8">
                     <div className="w-16 h-16 bg-white rounded-2xl shadow-xl flex items-center justify-center text-emerald-600 border border-emerald-100 shrink-0">
                        <i className="fas fa-unlock-alt text-2xl"></i>
                     </div>
                     <div>
                       <h4 className="text-3xl font-black text-emerald-900 tracking-tight leading-none mb-2">{searchedPatient.profile.name}</h4>
                       <p className="text-xs font-bold text-emerald-600 uppercase tracking-widest opacity-80">Clinical Assets Unlocked</p>
                     </div>
                  </div>
                  <button onClick={() => { setSearchedPatient(null); setAuthorizedPatientId(null); }} className="bg-white border-2 border-emerald-200 text-emerald-700 px-10 py-4 rounded-full font-black uppercase text-xs tracking-widest hover:bg-emerald-600 hover:text-white hover:border-emerald-600 transition-all">Close Secure Tunnel</button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                  <RecordCard title="Patient Clinical History" icon={ICONS.MEDICAL}>
                    <div className="space-y-6">
