import { GoogleGenAI, Type } from "@google/genai";
import { HealthRecord, MedicalProblem, GovernmentScheme, HospitalRecommendation } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeHealthRecord = async (record: HealthRecord, query: string): Promise<string> => {
  const systemInstruction = `
    You are Shield AI, a professional medical records analyst and healthcare navigator. 
    Analyze the provided health history: ${JSON.stringify(record)}.

    CRITICAL MISSION:
    Identify and suggest specific Indian Government Health Schemes (like Ayushman Bharat - PM-JAY, RSBY, state-specific schemes like CMCHIS in TN or Aarogyasri in Telangana) that the user might be eligible for.

    Guidelines:
    1. DISCLAIMER: "I am Shield AI, a guidance assistant. I am not a substitute for professional medical advice or official government eligibility verification."
    2. Check for drug-drug interactions if medication data is present.
    3. Use the severity and status of conditions to prioritize advice. Severe/Present conditions need immediate scheme mapping.
    4. Mask sensitive IDs in your response.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: query,
      config: {
        systemInstruction,
        temperature: 0.6,
        thinkingConfig: { thinkingBudget: 4000 }
      },
    });

    return response.text || "I'm sorry, I couldn't process your request.";
  } catch (error) {
    console.error("Gemini AI error:", error);
    return "I encountered an error while analyzing your health data.";
  }
};

export const findBestHospitals = async (condition: string): Promise<HospitalRecommendation[]> => {
  const searchPrompt = `Find the top 5 most highly-rated and specialized hospitals and medical centers for treating "${condition}" in India. 
  Include their main location, what they are specifically known for regarding this condition, and provide official website links.`;

  try {
    const searchResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: searchPrompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const infoText = searchResponse.text;
    const groundingChunks = searchResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
    const sources = groundingChunks
      ? groundingChunks
          .filter((chunk: any) => chunk.web)
          .map((chunk: any) => ({
            title: chunk.web.title,
            uri: chunk.web.uri
          }))
      : [];

    const parsePrompt = `
      Convert the following info into a JSON array of HospitalRecommendation objects.
      Info: ${infoText}

      Schema:
      {
        "id": "unique-id",
        "name": "Hospital Name",
        "location": "City, State",
        "specialty": "Why it is top-rated for this condition",
        "highlights": ["Key feature 1", "Key feature 2"],
        "rating": "e.g., 4.8/5 or NABH Accredited"
      }
    `;

    const parseResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: parsePrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              name: { type: Type.STRING },
              location: { type: Type.STRING },
              specialty: { type: Type.STRING },
              highlights: { type: Type.ARRAY, items: { type: Type.STRING } },
              rating: { type: Type.STRING }
            },
            required: ["id", "name", "location", "specialty", "highlights"]
          }
        }
      }
    });

    const hospitals: any[] = JSON.parse(parseResponse.text || "[]");
    return hospitals.map(h => ({
      ...h,
      officialLinks: sources.slice(0, 2)
    }));
  } catch (error) {
    console.error("Hospital search failed:", error);
    return [];
  }
};

export const findApplicableSchemes = async (problem: MedicalProblem | null, userAge: number): Promise<GovernmentScheme[]> => {
