              coverageAmount: { type: Type.STRING },
              eligibility: { type: Type.STRING },
              matchReason: { type: Type.STRING },
              applicationSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
              requiredDocuments: { type: Type.ARRAY, items: { type: Type.STRING } }
