/**
 * HealthDB Service
 * Integrated with Supabase for centralized cloud storage.
 * 
 * Required Supabase Table Schema ('records'):
 * - id: text (Primary Key) - Stores the Health ID
 * - phone: text - Stores user phone number
 * - name: text - Stores user legal name
 * - data: jsonb - Stores the complete medical record object
 */
export class HealthDB {
  private supabase: SupabaseClient;

  constructor() {
    this.supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
  }

  // API Compatibility method
  async init(): Promise<void> {
    console.log("HealthShield: Supabase connection established.");
  }

  async saveRecord(record: HealthRecord): Promise<void> {
    const healthId = record.profile.healthId.toUpperCase().trim();
    const phone = record.profile.phone.trim();
    const name = record.profile.name.trim();

    // Add metadata
    const recordWithMeta = { ...record, lastUpdated: Date.now() };

    const { error } = await this.supabase
      .from('records')
      .upsert({
        id: healthId,
        phone: phone,
        name: name,
        data: recordWithMeta
      }, { onConflict: 'id' });

    if (error) {
      console.error("Supabase Save Error:", error.message);
      throw error;
    }
  }

  async getRecord(healthId: string): Promise<HealthRecord | null> {
    const { data, error } = await this.supabase
      .from('records')
      .select('data')
      .eq('id', healthId.toUpperCase().trim())
      .maybeSingle();

    if (error) {
      console.error("Supabase Fetch Error:", error.message);
      return null;
    }

    return data?.data as HealthRecord || null;
  }

  async getRecordByPhone(phone: string): Promise<HealthRecord | null> {
    const { data, error } = await this.supabase
      .from('records')
      .select('data')
      .eq('phone', phone.trim())
      .maybeSingle();

    if (error) {
      console.error("Supabase Phone Query Error:", error.message);
      return null;
    }

    return data?.data as HealthRecord || null;
  }

  async getRecordsByName(name: string): Promise<HealthRecord[]> {
    const { data, error } = await this.supabase
      .from('records')
      .select('data')
      .ilike('name', `%${name.trim()}%`);

    if (error) {
      console.error("Supabase Name Search Error:", error.message);
      return [];
    }

    return (data || []).map(row => row.data as HealthRecord);
  }

  async getAllRecords(): Promise<HealthRecord[]> {
    const { data, error } = await this.supabase
      .from('records')
      .select('data');

    if (error) {
      console.error("Supabase Global Query Error:", error.message);
      return [];
    }

    return (data || []).map(row => row.data as HealthRecord);
  }

  async deleteRecord(healthId: string): Promise<void> {
    const { error } = await this.supabase
      .from('records')
      .delete()
      .eq('id', healthId);

    if (error) {
      console.error("Supabase Delete Error:", error.message);
      throw error;
    }
  }
}

