                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Compound / Medicine Name</label>
                    <input required name="name" placeholder="e.g. Metformin HCL" className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl px-10 py-6 text-xl font-black outline-none shadow-inner" />
                  </div>
                  <div className="grid grid-cols-2 gap-10">
                    <div className="space-y-4"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Dosage</label><input required name="dosage" placeholder="500mg" className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl px-10 py-6 text-xl font-black outline-none shadow-inner" /></div>
                    <div className="space-y-4"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Frequency</label><input required name="frequency" placeholder="1-0-1" className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl px-10 py-6 text-xl font-black outline-none shadow-inner" /></div>
                  </div>
                  <button className="w-full py-8 bg-indigo-600 text-white rounded-[2.5rem] font-black uppercase tracking-[0.5em] text-[10px] shadow-3xl shadow-indigo-600/20 hover:bg-indigo-700 transition-all mt-10">Authorize Vault Addition</button>
                </form>
              </>
            )}
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

export interface VisitingHours {
  start: string; // HH:mm
  end: string;   // HH:mm
  days: string[]; // ['Mon', 'Tue', ...]
}

export interface NotificationSettings {
  email: boolean;
  sms: boolean;
  push: boolean;
  sound: boolean;
}

export interface GovernmentScheme {
  id: string;
  name: string;
  benefits: string;
  eligibility: string;
  coverageAmount?: string;
  matchReason?: string;
  officialLink?: string;
  officialSources?: { title: string; uri: string }[];
  requiredDocuments?: string[];
  applicationSteps?: string[];
}

export interface HospitalRecommendation {
  id: string;
  name: string;
  location: string;
  specialty: string;
  highlights: string[];
  rating?: string;
  officialLinks: { title: string; uri: string }[];
}

export interface Insurance {
  id: string;
  provider: string;
  policyNumber: string;
  coverageAmount: string;
  expiryDate: string;
  policyType: 'Individual' | 'Family Floater' | 'Critical Illness';
  contactPhone: string;
  status: 'active' | 'expired';
}

export interface Reminder {
  id: string;
  title: string;
  description: string;
  time?: string; // HH:mm
  date?: string; // YYYY-MM-DD
  type: 'appointment' | 'refill' | 'followup' | 'personal' | 'custom' | 'medication' | 'lifestyle';
  status: 'pending' | 'completed';
}

export interface AuditLog {
  id: string;
  doctorId: string;
  doctorName: string;
  action: 'VIEW' | 'CREATE' | 'UPDATE' | 'DELETE';
  resource: string;
  details: string;
  timestamp: number;
}

export interface UserProfile {
  name: string;
  age: number;
  dob: string;
  gender: string;
  phone: string;
  aadhaar: string;
  healthId: string;
  bloodGroup: string;
  role: 'patient' | 'doctor';
  profilePicture?: string; // Base64 encoded string
  specialization?: string;
  licenseNumber?: string;
  clinicName?: string;
  emergencyContactName?: string;
  emergencyContactPhone?: string;
  isPremium?: boolean;
  subscriptionPlan?: 'standard' | 'pro' | 'family';
  subscriptionExpiry?: string;
  visitingHours?: VisitingHours;
  notificationSettings?: NotificationSettings;
}

export interface MedicalProblem {
  id: string;
  condition: string;
  status: 'past' | 'present' | 'recovered';
  isChronic?: boolean;
  onsetDate: string;
  endDate?: string;
  severity: 'mild' | 'moderate' | 'severe';
  treatment?: string;
  notes?: string;
  applicableSchemes?: GovernmentScheme[];
  applicableHospitals?: HospitalRecommendation[];
  treatmentProvider?: string;
  prescriptionDetails?: string;
}

export interface Medication {
  id: string;
  name: string;
  dosage: string;
  duration: string;
  frequency: string;
  startDate: string;
  instructions?: string;
  prescribedBy?: string;
  status: 'active' | 'discontinued';
}

export interface Surgery {
  id: string;
  type: string;
  date: string;
  hospital: string;
  surgeon: string;
  outcome?: string;
}

export interface Allergy {
  id: string;
  substance: string;
  severity: 'low' | 'moderate' | 'high';
  reaction?: string;
  firstObserved?: string;
}

export interface TreatmentNote {
  id: string;
  doctorName: string;
  date: string;
  note: string;
  clinicName?: string;
  category?: 'Consultation' | 'Follow-up' | 'Emergency' | 'Surgery';
}

export interface FamilyHistory {
  id: string;
  relation: string;
  condition: string;
  notableNotes?: string;
}

export interface Interaction {
  id: string;
  query: string;
  response: string;
  timestamp: number;
}

export interface DoctorAccessLog {
  patientHealthId: string;
  patientName: string;
  timestamp: number;
}

export interface HealthRecord {
  profile: UserProfile;
  problems: MedicalProblem[];
  medications: Medication[];
  surgeries: Surgery[];
  allergies: Allergy[];
  notes: TreatmentNote[];
  familyHistory: FamilyHistory[];
  insurances?: Insurance[];
  reminders?: Reminder[];
  interactions?: Interaction[];
  accessHistory?: DoctorAccessLog[];
  auditLogs?: AuditLog[];
  lastUpdated?: number;
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
}

import React, { useState, useEffect } from 'react';
import { 
  UserProfile, 
  HealthRecord, 
  ChatMessage, 
  MedicalProblem, 
  NotificationSettings, 
  VisitingHours, 
  GovernmentScheme, 
  AuditLog, 
  Medication, 
  Reminder,
  Insurance,
  HospitalRecommendation
} from './types';
import { ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord, findApplicableSchemes, findBestHospitals } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';

type ModalType = 'problem' | 'add_insurance' | 'doctor_auth' | 'surgery' | 'medication' | 'reminder' | 'hospital_results' | 'sql_guide' | null;
type SettingsTab = 'personal' | 'professional' | 'notifications' | 'security';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [loginMethod, setLoginMethod] = useState<'healthid' | 'phone'>('healthid');
  const [roleMode, setRoleMode] = useState<'patient' | 'doctor'>('patient');

  const [activeTab, setActiveTab] = useState('dashboard');
  const [settingsSubTab, setSettingsSubTab] = useState<SettingsTab>('personal');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [recordFilter, setRecordFilter] = useState<'present' | 'past'>('present');
  const [authError, setAuthError] = useState('');

  const [loginId, setLoginId] = useState('');
  const [phoneInput, setPhoneInput] = useState('');
  const [otpInput, setOtpInput] = useState('');
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);

  // Search States
  const [patientSearchQuery, setPatientSearchQuery] = useState('');
  const [patientSearchResults, setPatientSearchResults] = useState<HealthRecord[]>([]);
  const [searchedPatient, setSearchedPatient] = useState<HealthRecord | null>(null);
  const [isSearchingPatient, setIsSearchingPatient] = useState(false);
  const [authorizedPatientId, setAuthorizedPatientId] = useState<string | null>(null);
  const [accessOtpInput, setAccessOtpInput] = useState('');
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [searchInitiated, setSearchInitiated] = useState(false);

  // Edit States
  const [editProblem, setEditProblem] = useState<MedicalProblem | null>(null);
  const [editMedication, setEditMedication] = useState<Medication | null>(null);
  const [editReminder, setEditReminder] = useState<Reminder | null>(null);
  const [editInsurance, setEditInsurance] = useState<Insurance | null>(null);

  // AI & Schemes States
  const [isAnalyzingRecord, setIsAnalyzingRecord] = useState<string | null>(null);
  const [isSearchingSchemes, setIsSearchingSchemes] = useState(false);
  const [generalSchemes, setGeneralSchemes] = useState<GovernmentScheme[]>([]);
  const [schemeSearchQuery, setSchemeSearchQuery] = useState('');
  const [userQuery, setUserQuery] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Hospital Results State
  const [isSearchingHospitals, setIsSearchingHospitals] = useState(false);
  const [hospitalSearchQuery, setHospitalSearchQuery] = useState('');
  const [selectedHospitalResults, setSelectedHospitalResults] = useState<HospitalRecommendation[]>([]);
  const [selectedProblemForHospital, setSelectedProblemForHospital] = useState<string>('');

  const activeDisplayUser = searchedPatient || currentUser;

  const [regForm, setRegForm] = useState<UserProfile>({
    name: '', age: 0, dob: '', gender: 'Male', phone: '', aadhaar: '',
    healthId: '', bloodGroup: 'O+', role: 'patient',
    specialization: '', licenseNumber: '', clinicName: '',
    notificationSettings: { email: true, sms: true, push: true, sound: true },
    visitingHours: { start: '09:00', end: '17:00', days: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'] }
  });

  useEffect(() => {
    const init = async () => {
      await dbService.init();
      const savedSession = localStorage.getItem(SESSION_KEY);
      if (savedSession) {
        const record = await dbService.getRecord(savedSession);
        if (record) {
          setCurrentUser(record);
          setIsAuth(true);
          setRoleMode(record.profile.role);
          loadGeneralSchemes(record.profile.age);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  const loadGeneralSchemes = async (age: number) => {
    setIsSearchingSchemes(true);
    const schemes = await findApplicableSchemes(null, age);
    setGeneralSchemes(schemes);
    setIsSearchingSchemes(false);
  };

  const handleSchemeSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!schemeSearchQuery.trim()) return;
    setIsSearchingSchemes(true);
    const results = await findApplicableSchemes({ condition: schemeSearchQuery } as any, currentUser?.profile.age || 30);
    setGeneralSchemes(results);
    setIsSearchingSchemes(false);
  };

  const createAuditLog = (action: AuditLog['action'], resource: string, details: string): AuditLog => ({
    id: `LOG-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`.toUpperCase(),
    doctorId: currentUser?.profile.healthId || 'SYSTEM',
    doctorName: currentUser?.profile.name || 'System Operator',
    action,
    resource,
    details,
    timestamp: Date.now()
  });

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    setIsSubmitting(true);

    let record: HealthRecord | null = null;
    if (loginMethod === 'healthid') {
      record = await dbService.getRecord(loginId);
      if (!record || record.profile.role !== roleMode) {
        setAuthError(`Invalid ${roleMode === 'doctor' ? 'DR' : 'HS'} ID or Role mismatch.`);
        setIsSubmitting(false);
        return;
      }
    } else {
      if (!isVerifyingOtp) {
        record = await dbService.getRecordByPhone(phoneInput);
        if (record && record.profile.role === roleMode) {
          setIsVerifyingOtp(true);
          setIsSubmitting(false);
          return;
        } else {
          setAuthError("Phone number not registered.");
          setIsSubmitting(false);
          return;
        }
      } else {
        record = await dbService.getRecordByPhone(phoneInput);
      }
    }

    if (record) {
      setCurrentUser(record);
      setIsAuth(true);
      localStorage.setItem(SESSION_KEY, record.profile.healthId);
      loadGeneralSchemes(record.profile.age);
    }
    setIsSubmitting(false);
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setAuthError('');

    const prefix = roleMode === 'doctor' ? 'DR' : 'HS';
    const healthId = `${prefix}-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.floor(1000 + Math.random() * 9000)}`;

    const newRecord: HealthRecord = {
      profile: { ...regForm, healthId, role: roleMode },
      problems: [], medications: [], surgeries: [], allergies: [], notes: [],
      familyHistory: [], insurances: [], reminders: [], lastUpdated: Date.now(),
      auditLogs: []
    };

    try {
      await dbService.saveRecord(newRecord);
      setCurrentUser(newRecord);
      setIsAuth(true);
      localStorage.setItem(SESSION_KEY, healthId);
      loadGeneralSchemes(newRecord.profile.age);
    } catch (err: any) {
      setAuthError(`Registration failed: ${err.message || 'Storage Error'}`);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleLogout = () => {
    setIsAuth(false);
    setCurrentUser(null);
    localStorage.removeItem(SESSION_KEY);
    setActiveTab('dashboard');
    setPatientSearchResults([]);
    setSearchedPatient(null);
    setAuthorizedPatientId(null);
  };

  const handleSearchPatient = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!patientSearchQuery.trim()) return;
    setIsSearchingPatient(true);
    setSearchInitiated(true);
    const allRecords = await dbService.getAllRecords();
    const results = allRecords.filter(r => 
      r.profile.role === 'patient' && 
      (r.profile.name.toLowerCase().includes(patientSearchQuery.toLowerCase()) || 
       (r.profile.healthId && r.profile.healthId.includes(patientSearchQuery.toUpperCase())))
    );
    setPatientSearchResults(results);
    setIsSearchingPatient(false);
  };

  const runSchemeAnalysis = async (problemId: string) => {
    const target = searchedPatient || currentUser;
    if (!target) return;
    const problem = target.problems.find(p => p.id === problemId);
    if (!problem) return;
    setIsAnalyzingRecord(problemId);
    try {
      const schemes = await findApplicableSchemes(problem, target.profile.age);
      const updatedUser = { ...target, problems: target.problems.map(p => p.id === problemId ? { ...p, applicableSchemes: schemes } : p) };
      if (searchedPatient) setSearchedPatient(updatedUser);
      else setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
    } finally { setIsAnalyzingRecord(null); }
  };

  const handleSearchHospitals = async (condition: string) => {
    setIsSearchingHospitals(true);
    setSelectedProblemForHospital(condition);
    setHospitalSearchQuery(condition);
    try {
      const results = await findBestHospitals(condition);
      setSelectedHospitalResults(results);
      setActiveTab('specialists');
    } catch (err) {
      console.error("Hospital search failed", err);
    } finally {
      setIsSearchingHospitals(false);
    }
  };

  const handleAskAi = async () => {
    const target = searchedPatient || currentUser;
    if (!userQuery.trim() || !target) return;
    setChatHistory(prev => [...prev, { role: 'user', content: userQuery, timestamp: Date.now() }]);
    setIsAiLoading(true);
    try {
      const response = await analyzeHealthRecord(target, userQuery);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    } finally { setIsAiLoading(false); setUserQuery(''); }
  };

  const handleCopyId = (id: string) => {
    navigator.clipboard.writeText(id);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const updateNotificationSetting = (key: keyof NotificationSettings) => {
    if (!currentUser) return;
    const settings = currentUser.profile.notificationSettings || { email: true, sms: true, push: true, sound: true };
    const updated = { ...currentUser, profile: { ...currentUser.profile, notificationSettings: { ...settings, [key]: !settings[key] } } };
    setCurrentUser(updated);
    dbService.saveRecord(updated);
  };

  const openEditModal = (type: ModalType, data: any) => {
    if (type === 'problem') setEditProblem(data);
    else if (type === 'medication') setEditMedication(data);
    else if (type === 'reminder') setEditReminder(data);
    else if (type === 'add_insurance') setEditInsurance(data);
    setShowAddModal(type);
  };

  const closeModals = () => {
    setShowAddModal(null);
    setEditProblem(null);
    setEditMedication(null);
    setEditReminder(null);
    setEditInsurance(null);
  };

  const toggleVisitingDay = (day: string) => {
    if (!currentUser) return;
    const currentDays = currentUser.profile.visitingHours?.days || [];
    const newDays = currentDays.includes(day)
      ? currentDays.filter(d => d !== day)
      : [...currentDays, day];

    setCurrentUser({
      ...currentUser,
      profile: {
        ...currentUser.profile,
        visitingHours: {
          ...(currentUser.profile.visitingHours || { start: '09:00', end: '17:00' }),
          days: newDays
        } as VisitingHours
      }
    });
  };

  if (isLoading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
      <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
    </div>
  );

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-100 p-6">
        <div className="w-full max-w-xl bg-white rounded-3xl shadow-2xl p-10 border border-slate-200 animate-fade-in">
          <div className="text-center mb-10">
            <div className="w-20 h-20 bg-indigo-600 rounded-2xl flex items-center justify-center text-4xl text-white mx-auto mb-6 shadow-xl">
              {ICONS.LOCK}
            </div>
            <h1 className="text-3xl font-black text-slate-900 tracking-tight">{APP_NAME}</h1>
            <p className="text-slate-500 text-sm mt-2 font-medium">Next-Generation Clinical Vault</p>
          </div>

          <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-8 border border-slate-200 shadow-inner">
            <button 
              onClick={() => { setRoleMode('patient'); setAuthError(''); }} 
              className={`flex-1 py-3 text-xs font-black uppercase rounded-xl transition-all tracking-widest ${roleMode === 'patient' ? 'bg-white text-indigo-700 shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Patient Path
            </button>
            <button 
              onClick={() => { setRoleMode('doctor'); setAuthError(''); }} 
              className={`flex-1 py-3 text-xs font-black uppercase rounded-xl transition-all tracking-widest ${roleMode === 'doctor' ? 'bg-white text-indigo-700 shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Medical Professional
            </button>
          </div>

          <div className="flex justify-center space-x-10 mb-10 text-sm">
            <button onClick={() => setAuthMode('login')} className={`font-black pb-2 border-b-2 transition-all uppercase tracking-widest ${authMode === 'login' ? 'text-indigo-600 border-indigo-600' : 'text-slate-300 border-transparent'}`}>Access Vault</button>
            <button onClick={() => setAuthMode('register')} className={`font-black pb-2 border-b-2 transition-all uppercase tracking-widest ${authMode === 'register' ? 'text-indigo-600 border-indigo-600' : 'text-slate-300 border-transparent'}`}>Create Identity</button>
          </div>

          {authMode === 'login' ? (
            <form onSubmit={handleLogin} className="space-y-6">
              <div className="flex bg-slate-50 p-1.5 rounded-xl border border-slate-200 mb-6">
                <button type="button" onClick={() => setLoginMethod('healthid')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all tracking-widest ${loginMethod === 'healthid' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-400'}`}>Node ID</button>
                <button type="button" onClick={() => setLoginMethod('phone')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all tracking-widest ${loginMethod === 'phone' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-400'}`}>Biometric SMS</button>
              </div>

              {loginMethod === 'healthid' ? (
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Assigned Identifier</label>
                  <input 
                    required 
                    placeholder={roleMode === 'doctor' ? "DR-XXXX-XXXX" : "HS-XXXX-XXXX"} 
                    className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all font-bold text-slate-800" 
                    value={loginId} 
                    onChange={e => setLoginId(e.target.value.toUpperCase())} 
                  />
                </div>
              ) : (
                <div className="space-y-6">
                  {!isVerifyingOtp ? (
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Phone Identifier</label>
                      <input required type="tel" placeholder="+91 XXXXX XXXXX" className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-6 py-4 outline-none font-bold" value={phoneInput} onChange={e => setPhoneInput(e.target.value)} />
                    </div>
                  ) : (
                    <div className="space-y-4 text-center">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-4">Establishing Secure Link...</label>
                      <input required maxLength={4} className="w-full border-4 border-indigo-100 bg-indigo-50 rounded-3xl py-6 text-5xl font-black tracking-[0.5em] text-center text-indigo-700 outline-none transition-all shadow-inner" value={otpInput} onChange={e => setOtpInput(e.target.value.replace(/\D/g, ''))} />
                    </div>
                  )}
                </div>
              )}
              {authError && <p className="text-red-500 text-xs font-black text-center uppercase tracking-tight">{authError}</p>}
              <button type="submit" disabled={isSubmitting} className="w-full bg-slate-900 hover:bg-indigo-600 text-white font-black py-5 rounded-2xl shadow-xl transition-all uppercase tracking-[0.3em] text-xs">
                {isSubmitting ? 'Verifying Node...' : (isVerifyingOtp ? 'Initialize' : 'Access Tunnel')}
              </button>
            </form>
          ) : (
            <form onSubmit={handleRegister} className="space-y-6 animate-fade-in">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Legal Name</label>
                <input required placeholder="Dr. Jane Smith / John Doe" className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-6 py-4 outline-none font-bold" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
              </div>

              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Age</label>
                   <input required type="number" className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-6 py-4 outline-none font-bold" value={regForm.age || ''} onChange={e => setRegForm({...regForm, age: parseInt(e.target.value)})} />
                </div>
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Gender</label>
                   <select required className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-6 py-4 outline-none font-bold appearance-none bg-white" value={regForm.gender} onChange={e => setRegForm({...regForm, gender: e.target.value})}>
                     <option value="Male">Male</option>
                     <option value="Female">Female</option>
                     <option value="Non-binary">Non-binary</option>
                     <option value="Other">Other</option>
                   </select>
                </div>
              </div>

              {roleMode === 'doctor' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-6 bg-indigo-50/50 rounded-3xl border border-indigo-100">
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Specialization</label>
