    setIsAnalyzingRecord(problemId);
    try {
      const schemes = await findApplicableSchemes(problem, target.profile.age);
      const updatedUser = { ...target, problems: target.problems.map(p => p.id === problemId ? { ...p, applicableSchemes: schemes } : p) };
      if (searchedPatient) setSearchedPatient(updatedUser);
      else setCurrentUser(updatedUser);
      await dbService.saveRecord(updatedUser);
    } finally { setIsAnalyzingRecord(null); }
  };

  const handleSearchHospitals = async (condition: string) => {
    setIsSearchingHospitals(true);
    setSelectedProblemForHospital(condition);
    setHospitalSearchQuery(condition);
    try {
      const results = await findBestHospitals(condition);
      setSelectedHospitalResults(results);
      setActiveTab('specialists');
    } catch (err) {
      console.error("Hospital search failed", err);
    } finally {
      setIsSearchingHospitals(false);
    }
  };

  const handleAskAi = async () => {
    const target = searchedPatient || currentUser;
    if (!userQuery.trim() || !target) return;
    setChatHistory(prev => [...prev, { role: 'user', content: userQuery, timestamp: Date.now() }]);
    setIsAiLoading(true);
    try {
      const response = await analyzeHealthRecord(target, userQuery);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    } finally { setIsAiLoading(false); setUserQuery(''); }
  };

  const handleCopyId = (id: string) => {
    navigator.clipboard.writeText(id);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const updateNotificationSetting = (key: keyof NotificationSettings) => {
    if (!currentUser || !currentUser.profile) return;
    const settings = currentUser.profile.notificationSettings || { email: true, sms: true, push: true, sound: true };
    const updated = { ...currentUser, profile: { ...currentUser.profile, notificationSettings: { ...settings, [key]: !settings[key] } } };
    setCurrentUser(updated);
    dbService.saveRecord(updated);
  };

  const openEditModal = (type: ModalType, data: any) => {
    if (type === 'problem') setEditProblem(data);
    else if (type === 'medication') setEditMedication(data);
    else if (type === 'reminder') setEditReminder(data);
    else if (type === 'add_insurance') setEditInsurance(data);
    setShowAddModal(type);
  };

  const closeModals = () => {
    setShowAddModal(null);
    setEditProblem(null);
    setEditMedication(null);
    setEditReminder(null);
    setEditInsurance(null);
  };

  const toggleVisitingDay = (day: string) => {
    if (!currentUser || !currentUser.profile) return;
    const currentDays = currentUser.profile.visitingHours?.days || [];
    const newDays = currentDays.includes(day)
      ? currentDays.filter(d => d !== day)
      : [...currentDays, day];

    setCurrentUser({
      ...currentUser,
      profile: {
        ...currentUser.profile,
        visitingHours: {
          ...(currentUser.profile.visitingHours || { start: '09:00', end: '17:00' }),
          days: newDays
        } as VisitingHours
      }
    });
  };

  if (isLoading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
      <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
    </div>
  );

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-100 p-6">
        <div className="w-full max-w-xl bg-white rounded-3xl shadow-2xl p-10 border border-slate-200 animate-fade-in">
          <div className="text-center mb-10">
            <div className="w-20 h-20 bg-indigo-600 rounded-2xl flex items-center justify-center text-4xl text-white mx-auto mb-6 shadow-xl">
              {ICONS.LOCK}
            </div>
            <h1 className="text-3xl font-black text-slate-900 tracking-tight">{APP_NAME}</h1>
            <p className="text-slate-500 text-sm mt-2 font-medium">Next-Generation Clinical Vault</p>
          </div>

          <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-8 border border-slate-200 shadow-inner">
            <button 
              onClick={() => { setRoleMode('patient'); setAuthError(''); }} 
              className={`flex-1 py-3 text-xs font-black uppercase rounded-xl transition-all tracking-widest ${roleMode === 'patient' ? 'bg-white text-indigo-700 shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Patient Path
            </button>
            <button 
              onClick={() => { setRoleMode('doctor'); setAuthError(''); }} 
              className={`flex-1 py-3 text-xs font-black uppercase rounded-xl transition-all tracking-widest ${roleMode === 'doctor' ? 'bg-white text-indigo-700 shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Medical Professional
            </button>
          </div>

          <div className="flex justify-center space-x-10 mb-10 text-sm">
            <button onClick={() => setAuthMode('login')} className={`font-black pb-2 border-b-2 transition-all uppercase tracking-widest ${authMode === 'login' ? 'text-indigo-600 border-indigo-600' : 'text-slate-300 border-transparent'}`}>Access Vault</button>
            <button onClick={() => setAuthMode('register')} className={`font-black pb-2 border-b-2 transition-all uppercase tracking-widest ${authMode === 'register' ? 'text-indigo-600 border-indigo-600' : 'text-slate-300 border-transparent'}`}>Create Identity</button>
          </div>

          {authMode === 'login' ? (
            <form onSubmit={handleLogin} className="space-y-6">
              <div className="flex bg-slate-50 p-1.5 rounded-xl border border-slate-200 mb-6">
                <button type="button" onClick={() => setLoginMethod('healthid')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all tracking-widest ${loginMethod === 'healthid' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-400'}`}>Node ID</button>
                <button type="button" onClick={() => setLoginMethod('phone')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all tracking-widest ${loginMethod === 'phone' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-400'}`}>Biometric SMS</button>
              </div>

              {loginMethod === 'healthid' ? (
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Assigned Identifier</label>
                  <input 
                    required 
                    placeholder={roleMode === 'doctor' ? "DR-XXXX-XXXX" : "HS-XXXX-XXXX"} 
                    className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all font-bold text-slate-800" 
                    value={loginId} 
                    onChange={e => setLoginId(e.target.value.toUpperCase())} 
                  />
                </div>
              ) : (
                <div className="space-y-6">
                  {!isVerifyingOtp ? (
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Phone Identifier</label>
                      <input required type="tel" placeholder="+91 XXXXX XXXXX" className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-6 py-4 outline-none font-bold" value={phoneInput} onChange={e => setPhoneInput(e.target.value)} />
                    </div>
                  ) : (
                    <div className="space-y-4 text-center">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-4">Establishing Secure Link...</label>
                      <input required maxLength={4} className="w-full border-4 border-indigo-100 bg-indigo-50 rounded-3xl py-6 text-5xl font-black tracking-[0.5em] text-center text-indigo-700 outline-none transition-all shadow-inner" value={otpInput} onChange={e => setOtpInput(e.target.value.replace(/\D/g, ''))} />
                    </div>
                  )}
                </div>
              )}
              {authError && <p className="text-red-500 text-xs font-black text-center uppercase tracking-tight">{authError}</p>}
              <button type="submit" disabled={isSubmitting} className="w-full bg-slate-900 hover:bg-indigo-600 text-white font-black py-5 rounded-2xl shadow-xl transition-all uppercase tracking-[0.3em] text-xs">
                {isSubmitting ? 'Verifying Node...' : (isVerifyingOtp ? 'Initialize' : 'Access Tunnel')}
              </button>
            </form>
          ) : (
            <form onSubmit={handleRegister} className="space-y-6 animate-fade-in">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Legal Name</label>
                <input required placeholder="Dr. Jane Smith / John Doe" className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-6 py-4 outline-none font-bold" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
              </div>

              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Age</label>
                   <input required type="number" className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-6 py-4 outline-none font-bold" value={regForm.age || ''} onChange={e => setRegForm({...regForm, age: parseInt(e.target.value)})} />
                </div>
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Gender</label>
                   <select required className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-6 py-4 outline-none font-bold appearance-none bg-white" value={regForm.gender} onChange={e => setRegForm({...regForm, gender: e.target.value})}>
                     <option value="Male">Male</option>
                     <option value="Female">Female</option>
                     <option value="Non-binary">Non-binary</option>
                     <option value="Other">Other</option>
                   </select>
                </div>
              </div>

              {roleMode === 'doctor' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-6 bg-indigo-50/50 rounded-3xl border border-indigo-100">
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Specialization</label>
                      <input required placeholder="e.g. Cardiologist" className="w-full border-2 border-white bg-white rounded-2xl px-5 py-3 outline-none font-bold text-sm" value={regForm.specialization} onChange={e => setRegForm({...regForm, specialization: e.target.value})} />
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Medical License #</label>
                      <input required placeholder="NMC-123456" className="w-full border-2 border-white bg-white rounded-2xl px-5 py-3 outline-none font-bold text-sm" value={regForm.licenseNumber} onChange={e => setRegForm({...regForm, licenseNumber: e.target.value})} />
                   </div>
                </div>
              )}

              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Blood Group</label>
                   <select className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-6 py-4 outline-none font-bold appearance-none bg-white" value={regForm.bloodGroup} onChange={e => setRegForm({...regForm, bloodGroup: e.target.value})}>
                     {['A+', 'B+', 'O+', 'AB+', 'A-', 'B-', 'O-', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                   </select>
                </div>
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Contact Phone</label>
                   <input required type="tel" className="w-full border-2 border-slate-100 bg-slate-50 rounded-2xl px-6 py-4 outline-none font-bold" value={regForm.phone} onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                </div>
              </div>

              {authError && <p className="text-red-500 text-xs font-black text-center uppercase">{authError}</p>}
              <button type="submit" disabled={isSubmitting} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-black py-5 rounded-2xl shadow-xl transition-all uppercase tracking-[0.3em] text-xs">
                {isSubmitting ? 'Provisioning...' : 'Initialize Identity'}
              </button>
            </form>
          )}

          {dbService.isUsingLocalVault() && (
            <div className="mt-10 p-4 bg-amber-50 border border-amber-200 rounded-2xl text-center">
              <p className="text-[10px] font-black text-amber-700 uppercase tracking-widest leading-relaxed">
                Supabase 'records' table missing. <button onClick={() => setShowAddModal('sql_guide')} className="text-indigo-600 underline">Resolve Infrastructure Error</button>
              </p>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      userName={currentUser?.profile?.name || ''} 
      healthId={currentUser?.profile?.healthId || ''}
      role={roleMode}
      profilePicture={currentUser?.profile?.profilePicture}
      onLogout={handleLogout}
    >
      {dbService.isUsingLocalVault() && (
        <div className="mb-8 p-6 bg-amber-50 border-2 border-amber-200 rounded-[2rem] flex items-center justify-between animate-fade-in shadow-lg">
          <div className="flex items-center gap-6">
             <div className="w-12 h-12 bg-amber-100 rounded-2xl flex items-center justify-center text-amber-600 shadow-inner">
                <i className="fas fa-database text-xl"></i>
             </div>
             <div>
                <p className="text-sm font-black text-amber-900 uppercase tracking-tight">Cloud Sync Offline</p>
                <p className="text-xs font-medium text-amber-700/80">Table 'records' missing in Supabase. All data is locked to this terminal's Local Vault.</p>
             </div>
          </div>
          <button 
            onClick={() => setShowAddModal('sql_guide')}
            className="px-8 py-3 bg-amber-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-amber-600/20 hover:bg-amber-700 transition-all"
          >
            Fix Infrastructure
          </button>
        </div>
      )}

      <div className="space-y-12 animate-fade-in pb-16">
        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-8 space-y-8">
              <div className="bg-white rounded-[2.5rem] p-10 border border-slate-200 shadow-sm flex items-center gap-10">
                <div className="w-32 h-32 rounded-3xl bg-slate-50 border-4 border-white shadow-xl flex items-center justify-center overflow-hidden shrink-0 group relative cursor-pointer">
                   {currentUser?.profile?.profilePicture ? (
                     <img src={currentUser.profile.profilePicture} alt="" className="w-full h-full object-cover" />
                   ) : (
                     <i className="fas fa-user-shield text-5xl text-slate-200"></i>
                   )}
                </div>
                <div>
                  <h3 className="text-4xl font-black text-slate-900 tracking-tighter mb-2">{currentUser?.profile?.name || 'Authorized User'}</h3>
                  <div className="flex flex-wrap gap-4 items-center">
                    <div className="flex items-center bg-slate-100 rounded-full px-5 py-2 border border-slate-200">
                      <span className="text-xs font-black text-slate-500 uppercase tracking-[0.2em]">{currentUser?.profile?.healthId || 'N/A'}</span>
                      <button 
                        onClick={() => handleCopyId(currentUser?.profile?.healthId || '')}
                        className="ml-4 text-slate-400 hover:text-indigo-600 transition-colors"
                        title="Copy Health ID"
                      >
                        <i className={`fas ${copiedId === currentUser?.profile?.healthId ? 'fa-check text-green-500' : 'fa-copy'}`}></i>
                      </button>
                    </div>
                    <span className="text-[10px] font-black text-slate-400 bg-slate-100 px-5 py-2 rounded-full uppercase tracking-widest">{currentUser?.profile?.age || 0} Years</span>
                    <span className="text-[10px] font-black text-slate-400 bg-slate-100 px-5 py-2 rounded-full uppercase tracking-widest">{currentUser?.profile?.gender || 'N/A'}</span>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <RecordCard title="Clinical Snapshot" icon={ICONS.MEDICAL}>
                  <div className="space-y-4">
                    {currentUser?.problems?.slice(0, 3).map(p => (
                      <div key={p.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 flex justify-between items-center group">
                        <span className="text-sm font-bold text-slate-800">{p.condition}</span>
                        <div className="flex items-center gap-3">
                           <span className={`text-[9px] font-black uppercase px-3 py-1 rounded-lg ${p.severity === 'severe' ? 'bg-red-50 text-red-600' : 'bg-slate-200 text-slate-500'}`}>{p.severity}</span>
                        </div>
                      </div>
                    ))}
                    {(!currentUser?.problems || currentUser.problems.length === 0) && <p className="text-xs text-slate-400 italic py-6 text-center">Your clinical ledger is currently clear.</p>}
                  </div>
                </RecordCard>
                <RecordCard title="Welfare Benefits" icon={ICONS.SCHEME}>
                     <div className="space-y-4">
                       {generalSchemes.slice(0, 3).map(scheme => (
                         <div key={scheme.id} className="p-5 bg-indigo-50/30 rounded-2xl border border-indigo-100/50">
                            <p className="text-[10px] font-black text-indigo-700 mb-1 uppercase tracking-widest">{scheme.name}</p>
                            <p className="text-xs font-bold text-slate-600 leading-tight line-clamp-2">{scheme.benefits}</p>
                         </div>
                       ))}
                       <button onClick={() => setActiveTab('schemes')} className="w-full py-3 bg-white border border-slate-200 rounded-xl text-[9px] font-black uppercase tracking-[0.2em] text-slate-400 hover:text-indigo-600 hover:border-indigo-100 transition-all">Explore All Pathways</button>
                     </div>
                </RecordCard>
              </div>
            </div>
            <div className="lg:col-span-4">
               <RecordCard title="Intelligence Core" icon={ICONS.AI} className="h-full">
                  <div className="space-y-8 flex flex-col h-full justify-between pb-4">
                    <div className="p-8 bg-slate-950 rounded-[2rem] border border-white/10 shadow-2xl">
                       <p className="text-xs font-bold text-indigo-300 leading-relaxed mb-6 opacity-80">Shield AI cross-references your clinical history with real-time Indian Government gazettes to map eligibility for 200+ welfare schemes.</p>
                       <div className="flex items-center gap-4 text-[9px] font-black uppercase text-white tracking-[0.3em]">
                          <span className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_#10b981]"></span>
                          Neural Sync Active
                       </div>
                    </div>
                    <button onClick={() => setActiveTab('shield')} className="w-full py-6 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.4em] shadow-2xl shadow-indigo-600/20 hover:bg-indigo-700 hover:scale-[1.02] transition-all">
                       Initialize Chat Analysis
                    </button>
                  </div>
               </RecordCard>
            </div>
          </div>
        )}

        {activeTab === 'records' && (
          <div className="max-w-5xl mx-auto space-y-10 animate-fade-in">
            <div className="flex flex-col md:flex-row justify-between items-center gap-8 bg-white rounded-[2.5rem] p-8 border border-slate-100 shadow-sm">
              <div className="flex bg-slate-100 p-1.5 rounded-2xl w-full md:w-auto border border-slate-200 shadow-inner">
                <button onClick={() => setRecordFilter('present')} className={`flex-1 md:flex-none px-12 py-4 rounded-xl text-xs font-black uppercase tracking-[0.2em] transition-all ${recordFilter === 'present' ? 'bg-white text-indigo-700 shadow-xl' : 'text-slate-400'}`}>Current</button>
                <button onClick={() => setRecordFilter('past')} className={`flex-1 md:flex-none px-12 py-4 rounded-xl text-xs font-black uppercase tracking-[0.2em] transition-all ${recordFilter === 'past' ? 'bg-white text-indigo-700 shadow-xl' : 'text-slate-400'}`}>Log</button>
              </div>
              <div className="flex flex-wrap gap-4">
                 <button onClick={() => setShowAddModal('problem')} className="px-8 py-3.5 bg-slate-900 text-white rounded-xl font-black uppercase tracking-widest text-[9px] shadow-xl hover:bg-indigo-600 transition-all">Add Condition</button>
                 <button onClick={() => setShowAddModal('medication')} className="px-8 py-3.5 bg-white border-2 border-slate-100 text-slate-900 rounded-xl font-black uppercase tracking-widest text-[9px] shadow-sm hover:border-indigo-500 transition-all">New Med</button>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <RecordCard title="Clinical Diagnostic Ledger" icon={ICONS.MEDICAL}>
                <div className="space-y-6">
                  {activeDisplayUser?.problems?.filter(p => recordFilter === 'present' ? p.status === 'present' : p.status !== 'present').map(p => (
                    <div key={p.id} className="p-8 border border-slate-100 rounded-[2rem] bg-slate-50/50 hover:bg-white hover:shadow-2xl transition-all relative group">
                       <div className="flex justify-between items-start mb-6">
                         <h4 className="text-xl font-black text-slate-900 uppercase tracking-tighter leading-none">{p.condition}</h4>
                         <div className="flex items-center gap-4">
                           <span className={`text-[9px] font-black uppercase px-4 py-1.5 rounded-full ${p.severity === 'severe' ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>{p.severity}</span>
                           <button onClick={() => openEditModal('problem', p)} className="text-slate-300 hover:text-indigo-600 transition-all"><i className="fas fa-edit"></i></button>
                         </div>
                       </div>
                       <div className="flex items-center text-[10px] font-black text-slate-400 uppercase tracking-widest mb-8">
                        <i className="fas fa-calendar-day mr-3 text-indigo-500"></i> Date of Onset: {new Date(p.onsetDate).toLocaleDateString()}
                       </div>
                       <div className="flex gap-4">
                          <button onClick={() => runSchemeAnalysis(p.id)} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-indigo-600/20 hover:bg-indigo-700 transition-all">Identify Benefits</button>
                          <button onClick={() => handleSearchHospitals(p.condition)} className="flex-1 py-4 bg-white border-2 border-slate-100 text-slate-900 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:border-indigo-500 transition-all">Locate Experts</button>
                       </div>
                    </div>
                  ))}
                  {(!activeDisplayUser?.problems || activeDisplayUser.problems.filter(p => recordFilter === 'present' ? p.status === 'present' : p.status !== 'present').length === 0) && (
                    <div className="py-20 text-center border-2 border-dashed border-slate-100 rounded-3xl">
                       <i className="fas fa-folder-open text-4xl text-slate-100 mb-4"></i>
                       <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em]">No records in this sector</p>
                    </div>
                  )}
                </div>
              </RecordCard>

              <RecordCard title="Active Pharmaceutical Vault" icon={ICONS.MEDS}>
                <div className="space-y-6">
                   {activeDisplayUser?.medications?.filter(m => recordFilter === 'present' ? m.status === 'active' : m.status !== 'active').map(m => (
                     <div key={m.id} className="p-8 border border-slate-100 rounded-[2rem] bg-white shadow-sm hover:shadow-2xl transition-all group">
                        <div className="flex justify-between items-center mb-6">
                           <h4 className="text-xl font-black text-slate-900 uppercase tracking-tighter leading-none">{m.name}</h4>
                           <span className={`text-[9px] font-black uppercase px-3 py-1 rounded-full ${m.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-slate-100 text-slate-400'}`}>{m.status}</span>
                        </div>
                        <div className="grid grid-cols-2 gap-8 py-6 border-t border-slate-50">
                           <div>
                              <p className="text-[9px] font-black uppercase text-slate-300 tracking-widest mb-2">Dosage Profile</p>
                              <p className="text-sm font-black text-slate-700">{m.dosage}</p>
                           </div>
                           <div>
                              <p className="text-[9px] font-black uppercase text-slate-300 tracking-widest mb-2">Frequency Rate</p>
                              <p className="text-sm font-black text-slate-700">{m.frequency}</p>
                           </div>
                        </div>
